window.RB_PAGES={"Main": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird \u2014 Home\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0;background:#F2F2F4}\na{color:#C8102E}a:hover{color:#9E0B22}\n\u003c/style>\n\u003cstyle>\n@media (max-width: 640px) {\n  [style*=\"max-width: 1200px\"] { padding-left: 20px !important; padding-right: 20px !important; }\n  [style*=\"flex: 1 1\"] { flex-basis: 100% !important; min-width: 0 !important; }\n  h1 { font-size: 56px !important; line-height: 0.92 !important; letter-spacing: 1.5px !important; text-wrap: balance; }\n  h2[style*=\"font-size: 72px\"], h2[style*=\"font-size: 56px\"] { font-size: 44px !important; }\n  h2[style*=\"font-size: 48px\"], h2[style*=\"font-size: 44px\"] { font-size: 36px !important; }\n\n  /* header: logo + Find a shop on top, page links in a swipeable row underneath */\n  header > div { gap: 0 10px !important; padding-top: 8px !important; padding-bottom: 8px !important; }\n  header a[aria-label=\"Redbird home\"] img { height: 26px !important; }\n  header a[href=\"Drops.dc.html\"][style*=\"height: 44px\"] { height: 40px !important; padding: 0 14px !important; }\n  header > div > div { margin-left: auto; }\n  header a[aria-label=\"Redbird on Instagram\"] { display: none !important; }\n  /* menu button: tap to show the page links as a list under the header row */\n  header label[for=\"rb-menu\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] { order: 3; flex: 1 1 100% !important; display: none !important; flex-direction: column; gap: 0 !important; margin: 8px -20px -8px; padding: 4px 20px 10px; border-top: 1px solid rgba(0,0,0,0.08); }\n  header #rb-menu:checked ~ nav[aria-label=\"Main\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] > span[aria-hidden=\"true\"] { display: none !important; }\n  header nav[aria-label=\"Main\"] a { display: flex; align-items: center; min-height: 48px; padding: 0 12px !important; margin: 2px 0; font-size: 17px !important; border-radius: 8px; }\n  header nav[aria-label=\"Main\"] a span { margin-left: 8px !important; }\n\n  /* photos */\n  img[style*=\"height: 600px\"], img[style*=\"height: 520px\"] { height: 300px !important; }\n  img[style*=\"height: 210px\"] { height: 130px !important; }\n  [style*=\"min-height: 560px\"], [style*=\"min-height: 460px\"] { min-height: 300px !important; }\n  [style*=\"right: 28px; bottom: 28px\"] { position: static !important; max-width: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n  /* grids */\n  [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { padding: 14px !important; }\n  [style*=\"minmax(160px, 1fr)\"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 6px !important; }\n  [style*=\"minmax(340px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; }\n  [role=\"radiogroup\"][style*=\"minmax(220px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  [role=\"radiogroup\"] button { padding: 14px !important; }\n\n  /* home page strain table becomes stacked rows */\n  [style*=\"min-width: 720px\"] { min-width: 0 !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"][style*=\"text-transform: uppercase\"] { display: none !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] { grid-template-columns: minmax(0, 1fr) auto !important; gap: 4px 12px !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] > :nth-child(n+3) { grid-column: 1 / -1; font-size: 13px; }\n\n  /* strains: hero stats stay on one line each */\n  [style*=\"display: flex; gap: 32px\"] { gap: 20px !important; }\n  [style*=\"font-size: 48px; line-height: 1\"] { font-size: 36px !important; white-space: nowrap; }\n\n  /* drops: tighter shop rows */\n  button[style*=\"min-width: 112px\"] { min-width: 0 !important; padding: 0 12px !important; }\n  form[style*=\"padding: 28px\"] { padding: 20px !important; }\n\n  /* strain label viewer */\n  [role=\"dialog\"] [style*=\"justify-content: space-between\"] { flex-wrap: wrap !important; padding: 12px 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 20px 24px\"] { padding: 10px !important; }\n  [role=\"dialog\"] [style*=\"padding: 18px 24px 22px\"] { padding: 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 24px\"] { padding: 10px !important; }\n}\n\u003c/style>\n\u003cstyle>\n  header { position: sticky !important; top: 0; z-index: 50; }\n  #rb-menu:focus-visible ~ div label[for=\"rb-menu\"] { outline: 2px solid #C8102E; outline-offset: 2px; }\n  @media (max-width: 640px) {\n    /* Products: current strains as a list (name + type, genetics, status) */\n    [style*=\"minmax(260px, 1fr)\"]:has(> a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]),\n    [style*=\"minmax(260px, 1fr)\"]:has(> * > a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]) { grid-template-columns: minmax(0, 1fr) !important; gap: 8px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { display: grid !important; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: \"name tag\" \"gen gen\" \"stat stat\"; align-items: center; gap: 2px 10px !important; padding: 12px 14px !important; border-radius: 10px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) { display: contents !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:first-child { grid-area: tag; justify-self: end; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:last-child { display: none !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(2) { grid-area: name; font-size: 24px !important; min-width: 0; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(3) { grid-area: gen; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(4) { grid-area: stat; margin-top: 4px !important; padding-top: 0 !important; border-top: 0 !important; }\n    /* Beta Bud cards, two across: long names and tags stay inside the card */\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] { padding: 14px !important; min-width: 0; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] div[style*=\"font-size: 30px\"] { font-size: 24px !important; overflow-wrap: anywhere; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] > div[style*=\"justify-content: space-between\"] { flex-wrap: wrap; gap: 6px !important; }\n    /* iPhone zooms into any field under 16px: keep form text at 16px */\n    input, select, textarea { font-size: 16px !important; }\n  }\n  @media (max-width: 340px) { [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; } }\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4\">\n\n  \u003cheader style=\"position: sticky; top: 0; z-index: 10; background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 14px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 16px 28px\">\n      \u003cinput type=\"checkbox\" id=\"rb-menu\" aria-label=\"Menu\" style=\"position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none\">\n      \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none; color: #111111\">\n        \u003cimg src=\"/_blob/e3c029787746d07f7ac7aabb57e33d83\" alt=\"Redbird\" style=\"height: 32px; width: auto; display: block\">\n      \u003c/a>\n      \u003cnav aria-label=\"Main\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1\">\n        \u003ca href=\"Flower.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Products\u003c/a>\n        \u003ca href=\"Strains.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Drops\u003c/a>\n        \u003ca href=\"Contact.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Contact\u003c/a>\n        \u003ca href=\"Merch.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Merch\u003cspan style=\"margin-left: 6px; padding: 2px 5px; border-radius: 4px; background: #F2F2F4; font-family: 'Space Mono', monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: #767676; vertical-align: 2px\">Soon\u003c/span>\u003c/a>\n        \u003cspan aria-hidden=\"true\" style=\"flex: none; width: 1px; height: 22px; background: rgba(0,0,0,0.18); align-self: center; margin: 0 10px\">\u003c/span>\n        \u003ca href=\"Retailers.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">For Retailers\u003c/a>\n      \u003c/nav>\n      \u003cdiv style=\"display: flex; align-items: center; gap: 10px\">\n        \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Redbird on Instagram\" style=\"width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.08); display: flex; align-items: center; justify-content: center; color: #111111\">\n          \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\u003crect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\">\u003c/rect>\u003ccircle cx=\"12\" cy=\"12\" r=\"4\">\u003c/circle>\u003ccircle cx=\"17.5\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\">\u003c/circle>\u003c/svg>\n        \u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n        \u003clabel for=\"rb-menu\" aria-hidden=\"true\" style=\"display: none; width: 40px; height: 40px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.12); align-items: center; justify-content: center; color: #111111; cursor: pointer\">\u003csvg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\u003cline x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\">\u003c/line>\u003cline x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\">\u003c/line>\u003cline x1=\"4\" y1=\"17\" x2=\"20\" y2=\"17\">\u003c/line>\u003c/svg>\u003c/label>\n      \u003c/div>\n    \u003c/div>\n  \u003c/header>\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 56px 24px 40px; display: flex; flex-wrap: wrap; gap: 48px; align-items: center\">\n    \u003cdiv style=\"flex: 1 1 460px; display: flex; flex-direction: column; gap: 22px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">Spokane, WA \u00b7 Aeroponic cannabis\u003c/div>\n      \u003ch1 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 104px; line-height: 0.92; letter-spacing: 2px\">Grown in air.\u003cbr>Built for flavor.\u003c/h1>\n      \u003cp style=\"margin: 0; font-size: 18px; line-height: 1.65; color: #555555; max-width: 520px\">High-pressure aeroponics and closed-environment rooms give every Redbird strain vibrant color and a deep terpene profile \u2014 harvested every week.\u003c/p>\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 12px\">\n        \u003ca href=\"Strains.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Explore strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Get drop alerts\u003c/a>\n      \u003c/div>\n      \u003ca href=\"Drops.dc.html\" style=\"display: flex; flex-direction: column; gap: 6px; padding-top: 18px; border-top: 1px solid rgba(0,0,0,0.1); text-decoration: none; color: #111111; max-width: 520px\">\n        \u003cspan style=\"display: flex; align-items: center; gap: 8px; font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #C8102E\">\u003cspan style=\"width: 8px; height: 8px; border-radius: 999px; background: #C8102E; flex: none\">\u003c/span>__RB_H_LANDLABEL__\u003c/span>\n        \u003cspan style=\"font-size: 15px; font-weight: 600; line-height: 1.5\">__RB_H_LANDNAMES__ \u003cspan style=\"color: #C8102E; white-space: nowrap; margin-left: 6px\">See where \u2192\u003c/span>\u003c/span>\n      \u003c/a>\n    \u003c/div>\n    \u003cdiv style=\"flex: 1 1 460px; position: relative\">\n      \u003cimg src=\"/_blob/c8b828b21e21d4a9887f59a0b1515635\" alt=\"A Redbird Chocolate Bars jar with chocolate and flower\" style=\"width: 100%; height: 520px; object-fit: cover; border-radius: 12px; display: block\">\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 8px 24px 56px; display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px\">\n    \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; overflow: hidden; display: flex; flex-direction: column; gap: 10px\">\n      \u003cimg src=\"/_blob/e1a33541d9fd906bb00065334e875d1f\" alt=\"Aeroponic roots on a Redbird clone\" style=\"width: calc(100% + 48px); margin: -24px -24px 6px; height: 220px; object-fit: cover; display: block; border-radius: 12px 12px 0 0\">\u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #C8102E\">01 \u00b7 Grow\u003c/div>\n      \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 30px; letter-spacing: 1.5px; line-height: 1\">High-pressure aeroponics\u003c/div>\n      \u003cdiv style=\"font-size: 15px; line-height: 1.6; color: #555555\">Roots fed by a fine mist, not soil \u2014 precise nutrient delivery at every stage.\u003c/div>\n    \u003c/div>\n    \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; overflow: hidden; display: flex; flex-direction: column; gap: 10px\">\n      \u003cimg src=\"/_blob/41dc519780ca5fcd51c11d318d72b66b\" alt=\"A Redbird grower checking plants in a closed-environment room\" style=\"width: calc(100% + 48px); margin: -24px -24px 6px; height: 220px; object-fit: cover; display: block; border-radius: 12px 12px 0 0\">\u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #C8102E\">02 \u00b7 Environment\u003c/div>\n      \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 30px; letter-spacing: 1.5px; line-height: 1\">Closed-environment rooms\u003c/div>\n      \u003cdiv style=\"font-size: 15px; line-height: 1.6; color: #555555\">Light, air and humidity held steady so each harvest matches the last.\u003c/div>\n    \u003c/div>\n    \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; overflow: hidden; display: flex; flex-direction: column; gap: 10px\">\n      \u003cimg src=\"/_blob/c1827be414c190bc9faa7f53344faef9\" alt=\"A jar of Redbird live rosin\" style=\"width: calc(100% + 48px); margin: -24px -24px 6px; height: 220px; object-fit: cover; display: block; border-radius: 12px 12px 0 0\">\u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #C8102E\">03 \u00b7 Extract\u003c/div>\n      \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 30px; letter-spacing: 1.5px; line-height: 1\">Live rosin, made in house\u003c/div>\n      \u003cdiv style=\"font-size: 15px; line-height: 1.6; color: #555555\">Single source: our own bubble hash from our own flower, pressed into live rosin in a controlled environment \u2014 no solvents.\u003c/div>\n    \u003c/div>\n  \u003c/section>\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 0 24px 64px\">\u003ca href=\"https://www.youtube.com/watch?v=Qq49iym66jU\" target=\"_blank\" rel=\"noopener\" aria-label=\"Watch the Redbird film on YouTube\" style=\"position: relative; display: block; border-radius: 12px; overflow: hidden; text-decoration: none; color: #FFFFFF\">\u003cimg src=\"/_blob/043188f1eee37d7eb0e0e27eee97586f\" alt=\"Redbird grow facility\" style=\"width: 100%; height: 520px; object-fit: cover; display: block; filter: brightness(0.55)\">\u003cdiv style=\"position: absolute; inset: 0; display: flex; flex-direction: column; align-items: flex-start; justify-content: flex-end; gap: 12px; padding: 40px\">\u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #FF9AA8\">The Redbird film\u003c/div>\u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 64px; letter-spacing: 2px; line-height: 0.95\">See how it's grown\u003c/div>\u003cdiv style=\"display: flex; align-items: center; gap: 12px; font-size: 15px; font-weight: 600\">\u003cspan style=\"width: 56px; height: 56px; border-radius: 999px; background: #C8102E; display: flex; align-items: center; justify-content: center\">\u003csvg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"#FFFFFF\" aria-hidden=\"true\">\u003cpath d=\"M8 5v14l11-7z\">\u003c/path>\u003c/svg>\u003c/span>Watch the film\u003c/div>\u003c/div>\u003c/a>\u003c/section>\n\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 0 24px 64px; display: flex; flex-direction: column; gap: 20px\">\n    \u003cdiv style=\"display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px\">\n      \u003cdiv>\n        \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 48px; letter-spacing: 3px; line-height: 1\">Products\u003c/h2>\n        \u003cdiv style=\"font-size: 14px; color: #555555; margin-top: 6px\">Every format, from the same rooms.\u003c/div>\n      \u003c/div>\n      \u003ca href=\"Flower.dc.html\" style=\"font-size: 14px; font-weight: 600\">See all products \u2192\u003c/a>\n    \u003c/div>\n    \u003cdiv style=\"display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px\">\n      \u003csc-for list=\"{{products}}\" as=\"p\" hint-placeholder-count=\"4\">\n        \u003ca href=\"{{p.href}}\" style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; overflow: hidden; text-decoration: none; color: #111111; display: flex; flex-direction: column\">\n          \u003csc-if value=\"{{p.hasPhoto}}\" hint-placeholder-val=\"{{ false }}\">\n            \u003cimg src=\"{{p.img}}\" alt=\"{{p.alt}}\" style=\"width: 100%; height: 210px; object-fit: cover; display: block\">\n          \u003c/sc-if>\n          \u003csc-if value=\"{{p.noPhoto}}\" hint-placeholder-val=\"{{ true }}\">\n            \u003cdiv style=\"height: 210px; background: #F7F7F9; display: flex; align-items: center; justify-content: center; font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">[{{p.name}} photo]\u003c/div>\n          \u003c/sc-if>\n          \u003cdiv style=\"padding: 18px 20px; display: flex; flex-direction: column; gap: 10px\">\n            \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 26px; letter-spacing: 1.5px; line-height: 1\">{{p.name}}\u003c/div>\n            \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 6px\">\n              \u003csc-for list=\"{{p.sizes}}\" as=\"s\" hint-placeholder-count=\"3\">\n                \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; padding: 4px 8px; border-radius: 6px; background: #F2F2F4; color: #555555\">{{s}}\u003c/span>\n              \u003c/sc-for>\n            \u003c/div>\n          \u003c/div>\n        \u003c/a>\n      \u003c/sc-for>\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 0 24px 64px\">\n    \u003cdiv style=\"display: block; border-radius: 12px; overflow: hidden\">\n      \u003cimg src=\"/_blob/e78fcf9b838e0064d7a2ed9e43bcdcbe\" alt=\"Redbird pre-rolled joint boxes on a red table with chocolate and flower\" style=\"width: 100%; height: 520px; object-fit: cover; display: block\">\n    \u003c/div>\n  \u003c/section>\n  \u003csection aria-labelledby=\"home-beta-title\" style=\"max-width: 1200px; margin: 0 auto; padding: 0 24px 64px\">\u003cdiv style=\"background: #111111; color: #FFFFFF; border-radius: 12px; padding: 44px clamp(20px, 4vw, 40px); display: flex; flex-direction: column; gap: 22px\">\u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px 48px; align-items: flex-end; justify-content: space-between\">\u003cdiv style=\"display: flex; flex-direction: column; gap: 10px; max-width: 640px\">\u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #FF9AA8\">Beta Bud \u00b7 new genetics\u003c/div>\u003ch2 id=\"home-beta-title\" style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 56px; letter-spacing: 2px; line-height: 0.95\">What we're testing next\u003c/h2>\u003cp style=\"margin: 0; font-size: 16px; line-height: 1.6; color: #CCCCCC\">Small runs of new genetics under one plain Beta Bud label. Try a jar and tell us what you think. Your feedback decides which ones join the lineup.\u003c/p>\u003c/div>\u003ca href=\"BetaBud.dc.html\" style=\"height: 52px; padding: 0 28px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 700; display: flex; align-items: center; text-decoration: none\">See Beta Bud \u2192\u003c/a>\u003c/div>\u003cdiv style=\"display: grid; grid-template-columns: repeat(auto-fill, minmax(min(240px, 100%), 1fr)); gap: 14px\">__RB_H_BETA__\u003c/div>\u003c/div>\u003c/section>\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 0 24px 64px; display: flex; flex-direction: column; gap: 16px\">\u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">Every jar, hand-drawn\u003c/div>\u003cdiv style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 16px\">\u003cimg src=\"/_blob/5ef53581986f3ec5c33d5aadc2d4361a\" alt=\"Kush Mints jar with mints and flower\" style=\"width: 100%; aspect-ratio: 4 / 5; object-fit: cover; border-radius: 12px; display: block\">\u003cimg src=\"/_blob/605c396932dc4fa9c4519bd76d815dba\" alt=\"Tropicanna Garlic jar with garlic and flower\" style=\"width: 100%; aspect-ratio: 4 / 5; object-fit: cover; border-radius: 12px; display: block\">\u003cimg src=\"/_blob/0cbf7643b72e6108a19fdcc5f2c9b4d6\" alt=\"Candy Chrome jar on a pile of wrapped candy\" style=\"width: 100%; aspect-ratio: 4 / 5; object-fit: cover; border-radius: 12px; display: block\">\u003cimg src=\"/_blob/e46a0e92071863b4754503a664487dfe\" alt=\"Raspberry Dosido jar with raspberries\" style=\"width: 100%; aspect-ratio: 4 / 5; object-fit: cover; border-radius: 12px; display: block\">\u003c/div>\u003c/section>\n\n\n  \u003csection style=\"background: #C8102E; color: #FFFFFF\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 56px 24px; display: flex; flex-wrap: wrap; gap: 40px; align-items: center\">\n      \u003cdiv style=\"flex: 1 1 420px; display: flex; flex-direction: column; gap: 16px\">\n        \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #FFD9DE\">Redbird Drops\u003c/div>\n        \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 72px; letter-spacing: 2px; line-height: 0.95\">Never miss a drop.\u003c/h2>\n        \u003cp style=\"margin: 0; font-size: 17px; line-height: 1.6; color: #FFE9EC; max-width: 480px\">Follow your shops and favorite strains. We'll email you when fresh Redbird lands.\u003c/p>\n        \u003ca href=\"Drops.dc.html\" style=\"align-self: flex-start; height: 50px; padding: 0 24px; border-radius: 8px; background: #FFFFFF; color: #C8102E; font-size: 15px; font-weight: 700; display: flex; align-items: center; text-decoration: none\">Get drop alerts\u003c/a>\n      \u003c/div>\n      \u003cdiv style=\"flex: 1 1 380px; background: #FFFFFF; color: #111111; border-radius: 12px; overflow: hidden\">\n        \u003cdiv style=\"padding: 14px 20px; border-bottom: 1px solid rgba(0,0,0,0.08); display: flex; justify-content: space-between; align-items: center\">\n          \u003cspan style=\"font-family: 'Bebas Neue', sans-serif; font-size: 20px; letter-spacing: 1.5px\">__RB_H_CARDTITLE__\u003c/span>\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; color: #555555\">__RB_H_WKOF__\u003c/span>\n        \u003c/div>\n        \u003csc-for list=\"{{soon}}\" as=\"x\" hint-placeholder-count=\"4\">\n          \u003cdiv style=\"padding: 12px 20px; border-bottom: 1px solid rgba(0,0,0,0.06); display: flex; align-items: center; gap: 12px\">\n            \u003cspan style=\"flex: 1; font-weight: 600; font-size: 15px\">{{x.name}}\u003c/span>\n            \u003cspan style=\"{{x.pill}}\">{{x.type}}\u003c/span>\n          \u003c/div>\n        \u003c/sc-for>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 64px 24px; display: flex; flex-direction: column; gap: 20px\">\n    \u003cdiv style=\"display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px\">\n      \u003cdiv>\n        \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 48px; letter-spacing: 3px; line-height: 1\">Harvesting next\u003c/h2>\n        \u003cdiv style=\"font-size: 14px; color: #555555; margin-top: 6px\">__RB_H_ROTSUB__\u003c/div>\n      \u003c/div>\n      \u003ca href=\"Strains.dc.html\" style=\"font-size: 14px; font-weight: 600\">__RB_H_SEEALL__\u003c/a>\n    \u003c/div>\n    \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; overflow-x: auto\">\n      \u003cdiv style=\"min-width: 720px\">\n        \u003cdiv style=\"display: grid; grid-template-columns: 2fr 1fr 3fr 2fr; gap: 16px; padding: 12px 20px; background: #F7F7F9; border-bottom: 1px solid rgba(0,0,0,0.08); font-family: 'Space Mono', monospace; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">\n          \u003cspan>Strain\u003c/span>\u003cspan>Type\u003c/span>\u003cspan>Genetics\u003c/span>\u003cspan>Breeder\u003c/span>\n        \u003c/div>\n        \u003csc-for list=\"{{strains}}\" as=\"s\" hint-placeholder-count=\"6\">\n          \u003cdiv style=\"display: grid; grid-template-columns: 2fr 1fr 3fr 2fr; gap: 16px; padding: 14px 20px; border-bottom: 1px solid rgba(0,0,0,0.06); align-items: center; font-size: 14px\">\n            \u003cspan style=\"font-weight: 600\">{{s.name}}\u003c/span>\n            \u003cspan>\u003cspan style=\"{{s.pill}}\">{{s.type}}\u003c/span>\u003c/span>\n            \u003cspan style=\"color: #555555\">{{s.genetics}}\u003c/span>\n            \u003cspan style=\"color: #555555\">{{s.breeder}}\u003c/span>\n          \u003c/div>\n        \u003c/sc-for>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 0 24px 64px; display: flex; flex-direction: column; gap: 20px\">\n    \u003cdiv style=\"display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px\">\n      \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 48px; letter-spacing: 3px; line-height: 1\">Follow \u003cspan style=\"color: #C8102E\">@redbird_wa\u003c/span>\u003c/h2>\n      \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"font-size: 14px; font-weight: 600\">Open Instagram \u2192\u003c/a>\n    \u003c/div>\n    \u003cdiv style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 12px\">\n      \u003csc-for list=\"{{insta}}\" as=\"g\" hint-placeholder-count=\"6\">\n        \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Instagram post\" style=\"display: block; border-radius: 12px; overflow: hidden; aspect-ratio: 1 / 1\">\n          \u003cimg src=\"{{g.src}}\" alt=\"\" style=\"width: 100%; height: 100%; object-fit: cover; display: block\">\n        \u003c/a>\n      \u003c/sc-for>\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"background: #FFFFFF; border-top: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 64px 24px; display: flex; flex-wrap: wrap; gap: 48px; align-items: stretch\">\n      \u003cdiv style=\"flex: 1 1 360px; position: relative; border-radius: 12px; overflow: hidden; min-height: 460px\">\n        \u003cimg src=\"/_blob/8679f9a12d6663a5512bcbb9bdf0a3a4\" alt=\"A smiling Redbird team member in a Redbird shirt and cap between shelves of Redbird boxes\" style=\"position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: center 22%\">\n      \u003c/div>\n      \u003cdiv style=\"flex: 1 1 460px; display: flex; flex-direction: column; gap: 18px\">\n        \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">Contact\u003c/div>\n        \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 56px; letter-spacing: 2.5px; line-height: 0.95\">Talk to the team.\u003c/h2>\n        \u003cp style=\"margin: 0; font-size: 16px; line-height: 1.6; color: #555555\">Retailers, partners and fans \u2014 send us a note and a real person at Redbird will get back to you.\u003c/p>\n        \u003csc-if value=\"{{notSent}}\" hint-placeholder-val=\"{{ true }}\">\n        \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 12px\">\n          \u003clabel style=\"flex: 1 1 180px; display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">First name\n            \u003cinput type=\"text\" autocomplete=\"given-name\" value=\"{{fFirst}}\" onChange=\"{{setFirst}}\" style=\"height: 46px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 14px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9\">\n          \u003c/label>\n          \u003clabel style=\"flex: 1 1 180px; display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">Last name\n            \u003cinput type=\"text\" autocomplete=\"family-name\" value=\"{{fLast}}\" onChange=\"{{setLast}}\" style=\"height: 46px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 14px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9\">\n          \u003c/label>\n        \u003c/div>\n        \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 12px\">\n          \u003clabel style=\"flex: 1 1 180px; display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">Email\n            \u003cinput type=\"email\" autocomplete=\"email\" value=\"{{fEmail}}\" onChange=\"{{setEmail}}\" style=\"height: 46px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 14px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9\">\n          \u003c/label>\n          \u003clabel style=\"flex: 1 1 180px; display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">Phone \u003cspan style=\"font-weight: 400; color: #767676\">(optional)\u003c/span>\n            \u003cinput type=\"tel\" autocomplete=\"tel\" value=\"{{fPhone}}\" onChange=\"{{setPhone}}\" style=\"height: 46px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 14px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9\">\n          \u003c/label>\n        \u003c/div>\n        \u003clabel style=\"display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">Message\n          \u003ctextarea rows=\"4\" value=\"{{fMessage}}\" onChange=\"{{setMessage}}\" style=\"border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 12px 14px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9; resize: vertical\">\u003c/textarea>\n        \u003c/label>\n        \u003cinput type=\"text\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" aria-hidden=\"true\" value=\"{{fHp}}\" onChange=\"{{setHp}}\" style=\"position: absolute; left: -9999px; width: 1px; height: 1px; opacity: 0\">\n        \u003cdiv style=\"{{errStyle}}\" role=\"alert\">{{formError}}\u003c/div>\n        \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 14px; align-items: center\">\n          \u003cbutton type=\"button\" onClick=\"{{submit}}\" style=\"height: 50px; padding: 0 28px; border-radius: 8px; border: 0; background: #C8102E; color: #FFFFFF; font: inherit; font-size: 15px; font-weight: 600; cursor: pointer\">{{sendLabel}}\u003c/button>\n          \u003cspan style=\"font-size: 13px; color: #767676\">Want drop alerts? \u003ca href=\"Drops.dc.html\" style=\"font-weight: 600\">Follow shops and strains &rarr;\u003c/a>\u003c/span>\n        \u003c/div>\n        \u003c/sc-if>\n        \u003csc-if value=\"{{sent}}\" hint-placeholder-val=\"{{ false }}\">\n          \u003cdiv style=\"display: flex; flex-direction: column; gap: 12px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px\">\n            \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 36px; letter-spacing: 2px; line-height: 1\">Message sent.\u003c/div>\n            \u003cp style=\"margin: 0; font-size: 15px; line-height: 1.6; color: #555555\">{{sentMsg}}\u003c/p>\n            \u003cbutton type=\"button\" onClick=\"{{again}}\" style=\"align-self: flex-start; height: 44px; padding: 0 18px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; font: inherit; font-size: 14px; font-weight: 600; cursor: pointer\">Send another message\u003c/button>\n          \u003c/div>\n        \u003c/sc-if>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003cfooter style=\"background: #111111; color: #A3A3A3\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px 36px; display: flex; flex-direction: column; gap: 26px\">\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px; align-items: center; justify-content: space-between\">\n        \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none\">\n          \u003cimg src=\"/_blob/186e35dcb739a15a6a58be91a24ac455\" alt=\"Redbird\" style=\"height: 30px; width: auto; display: block\">\n        \u003c/a>\n        \u003cnav aria-label=\"Footer\" style=\"display: flex; flex-wrap: wrap; gap: 24px; font-size: 14px\">\n          \u003ca href=\"Main.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Home\u003c/a>\n          \u003ca href=\"Flower.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Products\u003c/a>\n          \u003ca href=\"Strains.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Strains\u003c/a>\n          \u003ca href=\"Drops.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Drops\u003c/a>\n          \u003ca href=\"Contact.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Contact\u003c/a>\n          \u003ca href=\"Merch.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Merch\u003cspan style=\"margin-left: 5px; font-size: 11px; color: #8A8A8F\">(soon)\u003c/span>\u003c/a>\n          \u003ca href=\"Retailers.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">For Retailers\u003c/a>\n          \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF; text-decoration: none\">Instagram\u003c/a>\n        \u003c/nav>\n      \u003c/div>\n      \u003cdiv style=\"border-top: 1px solid #2A2A2A; padding-top: 22px; display: flex; flex-direction: column; gap: 12px; font-size: 12px; line-height: 1.7; max-width: 980px\">\n        \u003cp style=\"margin: 0\">Redbird is a Tier 3 Producer/Processor headquartered in Spokane, Washington.\u003c/p>\n        \u003cp style=\"margin: 0\">\u003cstrong style=\"color: #FFFFFF; font-weight: 700\">WARNING:\u003c/strong> This product may be unlawful outside of Washington State. This product has intoxicating effects and may be habit forming. Smoking is hazardous to your health. There may be health risks associated with consumption of this product. Should not be used by women that are pregnant or breast feeding. For use only by adults twenty-one and older. Keep out of reach of children. Marijuana can impair concentration, coordination, and judgment. Do not operate a vehicle or machinery under the influence of this drug.\u003c/p>\n        \u003cp style=\"margin: 0\">Redbird uses the following in the production of its cannabis products: Kaligreen by OAT Agrio Co LTD (approved for use in certified organic agriculture, OMRI listed) and Clonex Rooting Gel by Growth Technology, LTD.\u003c/p>\n        \u003cp style=\"margin: 0; font-family: 'Space Mono', monospace; font-size: 11px; color: #8A8A8A\">\u00a9 2016\u20132026 Redbird\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/footer>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":4900}}'>\nclass Component extends DCLogic {\n  constructor(props) {\n    super(props);\n    this.state = { fFirst: '', fLast: '', fEmail: '', fPhone: '', fMessage: '', fHp: '', busy: false, formError: '', sent: false, sentMsg: '' };\n    this.t0 = Date.now();\n  }\n  renderVals() {\n    const pill = {\n      Indica: 'display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; background: rgba(124,58,237,0.07); border: 1px solid rgba(124,58,237,0.2); color: #6D28D9',\n      Sativa: 'display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; background: rgba(180,83,9,0.07); border: 1px solid rgba(180,83,9,0.2); color: #B45309',\n      Hybrid: 'display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; background: rgba(22,163,74,0.07); border: 1px solid rgba(22,163,74,0.2); color: #15803D'\n    };\n    const products = [\n      { name: 'Flower', href: 'Flower.dc.html', sizes: ['3.5G', '7G', '28G'], img: '/_blob/295c326cd260b7386f629ae916ef43cb', alt: 'A Redbird Raspberry Dosido jar' },\n      { name: 'Beta Bud', href: 'BetaBud.dc.html', sizes: ['NEW GENETICS'], img: '/_blob/b59992f64029d5bb28554590dd31dee1', alt: 'The Redbird Beta Buds label' },\n      { name: 'Micro buds', href: 'Micro.dc.html', sizes: ['14G'], img: '/_blob/70a6b4c28b3f104b722d485dc25f2f43', alt: 'The Redbird Micro Buds label' },\n      { name: 'Pre-rolled joints', href: 'Prerolls.dc.html', sizes: ['1G', '2-PACK', '10-PACK'], img: '/_blob/59c3ca3b24e0c7c42577d269ec5e8272', alt: 'A Redbird pre-roll pack with kiwi and pineapple' },\n      { name: 'Rosin', href: 'Rosin.dc.html', sizes: ['LIVE ROSIN'], img: '/_blob/c1827be414c190bc9faa7f53344faef9', alt: 'A jar of Redbird rosin' }\n    ].map((p) => Object.assign({}, p, { hasPhoto: !!p.img, noPhoto: !p.img }));\n    const insta = ['/_blob/766fdc4cacda02beaf14c0a5a0340bab', '/_blob/52ebf00d29f2f2b3b918a26a1f59aa47', '/_blob/ac615debb55668bc0e4d6281aab19ffd', '/_blob/1ee7eb0d5db8b9478ce1cf68070bb021', '/_blob/15e67d4f82bb144f39c0a27b7d18a2e5', '/_blob/9ddcfff3a2d0be8dd3760280bcad8747'].map((u) => ({ src: u }));\n    const soon = __RB_H_SOON__\n      .map((s) => ({ name: s[0], type: s[1], pill: pill[s[1]] }));\n    const strains = __RB_H_ROT__.map((s) => ({ name: s[0], type: s[1], genetics: s[2], breeder: s[3], pill: pill[s[1]] }));\n    const st = this.state, api = (window.parent && window.parent.RB_API) || window.RB_API;\n    const set = (k) => (e) => this.setState({ [k]: e.target.value, formError: '' });\n    const submit = () => {\n      if (st.busy) return;\n      let err = '';\n      if (!st.fFirst.trim()) err = 'Please add your first name.';\n      else if (!/^[^\\s@]+@[^\\s@]+\\.[a-z]{2,}$/i.test(st.fEmail.trim())) err = 'Please enter a valid email address.';\n      else if (st.fMessage.trim().length \u003c 2) err = 'Please add a message.';\n      if (err) return this.setState({ formError: err });\n      if (!api) return this.setState({ formError: 'The contact form isn\\'t connected in this preview.' });\n      this.setState({ busy: true, formError: '' });\n      api({ action: 'contact', topic: 'general', first: st.fFirst.trim(), last: st.fLast.trim(), email: st.fEmail.trim(), phone: st.fPhone.trim(),\n            detail: 'From the home page', message: st.fMessage.trim(), hp: st.fHp, ms: Date.now() - this.t0 })\n        .then((r) => (r && r.ok) ? this.setState({ busy: false, sent: true, sentMsg: r.message, fMessage: '' })\n                                : this.setState({ busy: false, formError: (r && r.error) || 'Something went wrong. Please try again.' }))\n        .catch(() => this.setState({ busy: false, formError: 'We couldn\\'t reach Redbird. Check your connection and try again.' }));\n    };\n    return { products, soon, strains, insta,\n      fFirst: st.fFirst, fLast: st.fLast, fEmail: st.fEmail, fPhone: st.fPhone, fMessage: st.fMessage, fHp: st.fHp,\n      setFirst: set('fFirst'), setLast: set('fLast'), setEmail: set('fEmail'), setPhone: set('fPhone'), setMessage: set('fMessage'), setHp: set('fHp'),\n      errStyle: st.formError ? 'font-size: 14px; font-weight: 600; color: #C8102E; line-height: 1.4' : 'display: none', formError: st.formError,\n      submit, sendLabel: st.busy ? 'Sending\u2026' : 'Send message',\n      notSent: !st.sent, sent: st.sent, sentMsg: st.sentMsg, again: () => this.setState({ sent: false, formError: '' }) };\n  }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n", "Flower": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird \u2014 Flower\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0;background:#F2F2F4}\na{color:#C8102E}a:hover{color:#9E0B22}\n\u003c/style>\n\u003cstyle>\n@media (max-width: 640px) {\n  [style*=\"max-width: 1200px\"] { padding-left: 20px !important; padding-right: 20px !important; }\n  [style*=\"flex: 1 1\"] { flex-basis: 100% !important; min-width: 0 !important; }\n  h1 { font-size: 56px !important; line-height: 0.92 !important; letter-spacing: 1.5px !important; text-wrap: balance; }\n  h2[style*=\"font-size: 72px\"], h2[style*=\"font-size: 56px\"] { font-size: 44px !important; }\n  h2[style*=\"font-size: 48px\"], h2[style*=\"font-size: 44px\"] { font-size: 36px !important; }\n\n  /* header: logo + Find a shop on top, page links in a swipeable row underneath */\n  header > div { gap: 0 10px !important; padding-top: 8px !important; padding-bottom: 8px !important; }\n  header a[aria-label=\"Redbird home\"] img { height: 26px !important; }\n  header a[href=\"Drops.dc.html\"][style*=\"height: 44px\"] { height: 40px !important; padding: 0 14px !important; }\n  header > div > div { margin-left: auto; }\n  header a[aria-label=\"Redbird on Instagram\"] { display: none !important; }\n  /* menu button: tap to show the page links as a list under the header row */\n  header label[for=\"rb-menu\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] { order: 3; flex: 1 1 100% !important; display: none !important; flex-direction: column; gap: 0 !important; margin: 8px -20px -8px; padding: 4px 20px 10px; border-top: 1px solid rgba(0,0,0,0.08); }\n  header #rb-menu:checked ~ nav[aria-label=\"Main\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] > span[aria-hidden=\"true\"] { display: none !important; }\n  header nav[aria-label=\"Main\"] a { display: flex; align-items: center; min-height: 48px; padding: 0 12px !important; margin: 2px 0; font-size: 17px !important; border-radius: 8px; }\n  header nav[aria-label=\"Main\"] a span { margin-left: 8px !important; }\n\n  /* photos */\n  img[style*=\"height: 600px\"], img[style*=\"height: 520px\"] { height: 300px !important; }\n  img[style*=\"height: 210px\"] { height: 130px !important; }\n  [style*=\"min-height: 560px\"], [style*=\"min-height: 460px\"] { min-height: 300px !important; }\n  [style*=\"right: 28px; bottom: 28px\"] { position: static !important; max-width: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n  /* grids */\n  [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { padding: 14px !important; }\n  [style*=\"minmax(160px, 1fr)\"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 6px !important; }\n  [style*=\"minmax(340px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; }\n  [role=\"radiogroup\"][style*=\"minmax(220px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  [role=\"radiogroup\"] button { padding: 14px !important; }\n\n  /* home page strain table becomes stacked rows */\n  [style*=\"min-width: 720px\"] { min-width: 0 !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"][style*=\"text-transform: uppercase\"] { display: none !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] { grid-template-columns: minmax(0, 1fr) auto !important; gap: 4px 12px !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] > :nth-child(n+3) { grid-column: 1 / -1; font-size: 13px; }\n\n  /* strains: hero stats stay on one line each */\n  [style*=\"display: flex; gap: 32px\"] { gap: 20px !important; }\n  [style*=\"font-size: 48px; line-height: 1\"] { font-size: 36px !important; white-space: nowrap; }\n\n  /* drops: tighter shop rows */\n  button[style*=\"min-width: 112px\"] { min-width: 0 !important; padding: 0 12px !important; }\n  form[style*=\"padding: 28px\"] { padding: 20px !important; }\n\n  /* strain label viewer */\n  [role=\"dialog\"] [style*=\"justify-content: space-between\"] { flex-wrap: wrap !important; padding: 12px 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 20px 24px\"] { padding: 10px !important; }\n  [role=\"dialog\"] [style*=\"padding: 18px 24px 22px\"] { padding: 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 24px\"] { padding: 10px !important; }\n}\n\u003c/style>\n\u003cstyle>\n  header { position: sticky !important; top: 0; z-index: 50; }\n  #rb-menu:focus-visible ~ div label[for=\"rb-menu\"] { outline: 2px solid #C8102E; outline-offset: 2px; }\n  @media (max-width: 640px) {\n    /* Products: current strains as a list (name + type, genetics, status) */\n    [style*=\"minmax(260px, 1fr)\"]:has(> a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]),\n    [style*=\"minmax(260px, 1fr)\"]:has(> * > a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]) { grid-template-columns: minmax(0, 1fr) !important; gap: 8px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { display: grid !important; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: \"name tag\" \"gen gen\" \"stat stat\"; align-items: center; gap: 2px 10px !important; padding: 12px 14px !important; border-radius: 10px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) { display: contents !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:first-child { grid-area: tag; justify-self: end; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:last-child { display: none !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(2) { grid-area: name; font-size: 24px !important; min-width: 0; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(3) { grid-area: gen; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(4) { grid-area: stat; margin-top: 4px !important; padding-top: 0 !important; border-top: 0 !important; }\n    /* Beta Bud cards, two across: long names and tags stay inside the card */\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] { padding: 14px !important; min-width: 0; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] div[style*=\"font-size: 30px\"] { font-size: 24px !important; overflow-wrap: anywhere; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] > div[style*=\"justify-content: space-between\"] { flex-wrap: wrap; gap: 6px !important; }\n    /* iPhone zooms into any field under 16px: keep form text at 16px */\n    input, select, textarea { font-size: 16px !important; }\n  }\n  @media (max-width: 340px) { [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; } }\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4\">\n\n  \u003cheader style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 14px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 16px 28px\">\n      \u003cinput type=\"checkbox\" id=\"rb-menu\" aria-label=\"Menu\" style=\"position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none\">\n      \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none; color: #111111\">\n        \u003cimg src=\"/_blob/e3c029787746d07f7ac7aabb57e33d83\" alt=\"Redbird\" style=\"height: 32px; width: auto; display: block\">\n      \u003c/a>\n      \u003cnav aria-label=\"Main\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1\">\n        \u003ca href=\"Flower.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 8px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Products\u003c/a>\n        \u003ca href=\"Strains.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Drops\u003c/a>\n        \u003ca href=\"Contact.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Contact\u003c/a>\n        \u003ca href=\"Merch.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Merch\u003cspan style=\"margin-left: 6px; padding: 2px 5px; border-radius: 4px; background: #F2F2F4; font-family: 'Space Mono', monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: #767676; vertical-align: 2px\">Soon\u003c/span>\u003c/a>\n        \u003cspan aria-hidden=\"true\" style=\"flex: none; width: 1px; height: 22px; background: rgba(0,0,0,0.18); align-self: center; margin: 0 10px\">\u003c/span>\n        \u003ca href=\"Retailers.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">For Retailers\u003c/a>\n      \u003c/nav>\n      \u003cdiv style=\"display: flex; align-items: center; gap: 10px\">\n        \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Redbird on Instagram\" style=\"width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.08); display: flex; align-items: center; justify-content: center; color: #111111\">\n          \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\u003crect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\">\u003c/rect>\u003ccircle cx=\"12\" cy=\"12\" r=\"4\">\u003c/circle>\u003ccircle cx=\"17.5\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\">\u003c/circle>\u003c/svg>\n        \u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n        \u003clabel for=\"rb-menu\" aria-hidden=\"true\" style=\"display: none; width: 40px; height: 40px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.12); align-items: center; justify-content: center; color: #111111; cursor: pointer\">\u003csvg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\u003cline x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\">\u003c/line>\u003cline x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\">\u003c/line>\u003cline x1=\"4\" y1=\"17\" x2=\"20\" y2=\"17\">\u003c/line>\u003c/svg>\u003c/label>\n      \u003c/div>\n    \u003c/div>\n  \u003c/header>\n\n  \u003cnav aria-label=\"Products\" style=\"max-width: 1200px; margin: 0 auto; padding: 28px 24px 0; display: flex; flex-wrap: wrap; align-items: center; gap: 6px\">\n    \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #767676; margin-right: 6px\">Products\u003c/span>\n    \u003ca href=\"Flower.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Flower\u003c/a>\n    \u003ca href=\"BetaBud.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Beta Bud\u003c/a>\n    \u003ca href=\"Micro.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Micro Buds\u003c/a>\n    \u003ca href=\"Prerolls.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Pre-Rolls\u003c/a>\n    \u003ca href=\"Rosin.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Rosin\u003c/a>\n  \u003c/nav>\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 32px 24px 48px; display: flex; flex-wrap: wrap; gap: 48px; align-items: center\">\n    \u003cdiv style=\"flex: 1 1 440px; display: flex; flex-direction: column; gap: 20px\">\n      \u003ch1 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 120px; letter-spacing: 3px; line-height: 0.9; color: #C8102E\">Flower\u003c/h1>\n      \u003cp style=\"margin: 0; font-size: 17px; line-height: 1.7; color: #333333; max-width: 520px\">Redbird cannabis flower, cultivated through high-pressure aeroponics and closed environment agriculture, represents a pinnacle in cannabis cultivation. This cutting-edge approach ensures optimal nutrient delivery, fostering vibrant colors and robust terpene profiles. The result is a personalized cannabis experience, where every bud reflects the dedication to quality and innovation in cultivation.\u003c/p>\n      \u003cdiv style=\"display: flex; flex-direction: column; gap: 8px\">\n        \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">Available in\u003c/div>\n        \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 8px\">\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">3.5G\u003c/span>\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">7G\u003c/span>\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">28G\u003c/span>\n        \u003c/div>\n      \u003c/div>\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 12px\">\n        \u003ca href=\"Strains.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Explore strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop near you\u003c/a>\n      \u003c/div>\n    \u003c/div>\n    \u003cdiv style=\"flex: 1 1 460px\">\n      \u003cimg src=\"/_blob/295c326cd260b7386f629ae916ef43cb\" alt=\"A Redbird Raspberry Dosido jar with raspberry cookies and flower\" style=\"width: 100%; height: 600px; object-fit: cover; border-radius: 12px; display: block\">\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection id=\"strains\" style=\"max-width: 1200px; margin: 0 auto; padding: 16px 24px 72px; display: flex; flex-direction: column; gap: 20px\">\n    \u003cdiv style=\"display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 16px\">\n      \u003cdiv>\n        \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 48px; letter-spacing: 3px; line-height: 1\">Current strains\u003c/h2>\n        \u003cdiv style=\"font-size: 14px; color: #555555; margin-top: 6px\">__RB_F_SUB__\u003c/div>\n      \u003c/div>\n      \u003cdiv role=\"group\" aria-label=\"Filter by type\" style=\"display: flex; gap: 6px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 10px; padding: 4px\">\n        \u003cbutton onClick=\"{{fAll.pick}}\" style=\"{{fAll.style}}\">All\u003c/button>\n        \u003cbutton onClick=\"{{fIndica.pick}}\" style=\"{{fIndica.style}}\">Indica\u003c/button>\n        \u003cbutton onClick=\"{{fSativa.pick}}\" style=\"{{fSativa.style}}\">Sativa\u003c/button>\n        \u003cbutton onClick=\"{{fHybrid.pick}}\" style=\"{{fHybrid.style}}\">Hybrid\u003c/button>\n      \u003c/div>\n    \u003c/div>\n    \u003cdiv style=\"display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 16px\">\n      \u003csc-for list=\"{{strains}}\" as=\"s\" hint-placeholder-count=\"8\">\n        \u003ca href=\"Strains.dc.html\" style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 20px; display: flex; flex-direction: column; gap: 10px; text-decoration: none; color: #111111\">\n          \u003cdiv style=\"display: flex; justify-content: space-between; align-items: center\">\n            \u003cspan style=\"{{s.pill}}\">{{s.type}}\u003c/span>\n            \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 10px; color: #767676\">{{s.breeder}}\u003c/span>\n          \u003c/div>\n          \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 28px; letter-spacing: 1.5px; line-height: 1\">{{s.name}}\u003c/div>\n          \u003cdiv style=\"font-size: 13px; color: #555555\">{{s.genetics}}\u003c/div>\n          \u003cdiv style=\"margin-top: auto; padding-top: 12px; border-top: 1px solid rgba(0,0,0,0.06); font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 0.6px; text-transform: uppercase; color: {{s.dropColor}}\">{{s.drop}}\u003c/div>\n        \u003c/a>\n      \u003c/sc-for>\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"background: #111111; color: #FFFFFF\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px; display: flex; flex-wrap: wrap; gap: 24px; align-items: center; justify-content: space-between\">\n      \u003cdiv style=\"display: flex; flex-direction: column; gap: 6px\">\n        \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 40px; letter-spacing: 2px; line-height: 1\">Want to know when your strain drops?\u003c/div>\n        \u003cdiv style=\"font-size: 15px; color: #CCCCCC\">Follow it and we'll email you when it lands at a shop near you.\u003c/div>\n      \u003c/div>\n      \u003ca href=\"Drops.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Get drop alerts\u003c/a>\n    \u003c/div>\n  \u003c/section>\n\n  \u003cfooter style=\"background: #111111; color: #A3A3A3\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px 36px; display: flex; flex-direction: column; gap: 26px\">\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px; align-items: center; justify-content: space-between\">\n        \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none\">\n          \u003cimg src=\"/_blob/186e35dcb739a15a6a58be91a24ac455\" alt=\"Redbird\" style=\"height: 30px; width: auto; display: block\">\n        \u003c/a>\n        \u003cnav aria-label=\"Footer\" style=\"display: flex; flex-wrap: wrap; gap: 24px; font-size: 14px\">\n          \u003ca href=\"Main.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Home\u003c/a>\n          \u003ca href=\"Flower.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Products\u003c/a>\n          \u003ca href=\"Strains.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Strains\u003c/a>\n          \u003ca href=\"Drops.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Drops\u003c/a>\n          \u003ca href=\"Contact.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Contact\u003c/a>\n          \u003ca href=\"Merch.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Merch\u003cspan style=\"margin-left: 5px; font-size: 11px; color: #8A8A8F\">(soon)\u003c/span>\u003c/a>\n          \u003ca href=\"Retailers.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">For Retailers\u003c/a>\n          \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF; text-decoration: none\">Instagram\u003c/a>\n        \u003c/nav>\n      \u003c/div>\n      \u003cdiv style=\"border-top: 1px solid #2A2A2A; padding-top: 22px; display: flex; flex-direction: column; gap: 12px; font-size: 12px; line-height: 1.7; max-width: 980px\">\n        \u003cp style=\"margin: 0\">Redbird is a Tier 3 Producer/Processor headquartered in Spokane, Washington.\u003c/p>\n        \u003cp style=\"margin: 0\">\u003cstrong style=\"color: #FFFFFF; font-weight: 700\">WARNING:\u003c/strong> This product may be unlawful outside of Washington State. This product has intoxicating effects and may be habit forming. Smoking is hazardous to your health. There may be health risks associated with consumption of this product. Should not be used by women that are pregnant or breast feeding. For use only by adults twenty-one and older. Keep out of reach of children. Marijuana can impair concentration, coordination, and judgment. Do not operate a vehicle or machinery under the influence of this drug.\u003c/p>\n        \u003cp style=\"margin: 0\">Redbird uses the following in the production of its cannabis products: Kaligreen by OAT Agrio Co LTD (approved for use in certified organic agriculture, OMRI listed) and Clonex Rooting Gel by Growth Technology, LTD.\u003c/p>\n        \u003cp style=\"margin: 0; font-family: 'Space Mono', monospace; font-size: 11px; color: #8A8A8A\">\u00a9 2016\u20132026 Redbird\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/footer>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":2400}}'>\nclass Component extends DCLogic {\n  constructor(props) { super(props); this.state = { type: 'All' }; }\n  renderVals() {\n    const st = this.state;\n    const f = (t) => ({ pick: () => this.setState({ type: t }), style: st.type === t ? \"height: 40px; padding: 0 16px; border-radius: 8px; border: 1px solid rgba(200,16,46,0.18); background: rgba(200,16,46,0.06); color: #C8102E; font: inherit; font-size: 14px; font-weight: 600\" : \"height: 40px; padding: 0 16px; border-radius: 8px; border: 0; background: transparent; color: #555555; font: inherit; font-size: 14px; font-weight: 500\" });\n    const pill = {\n      Indica: 'display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; background: rgba(124,58,237,0.07); border: 1px solid rgba(124,58,237,0.2); color: #6D28D9',\n      Sativa: 'display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; background: rgba(180,83,9,0.07); border: 1px solid rgba(180,83,9,0.2); color: #B45309',\n      Hybrid: 'display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; background: rgba(22,163,74,0.07); border: 1px solid rgba(22,163,74,0.2); color: #15803D'\n    };\n    const data = __RB_F_DATA__;\n    return {\n      fAll: f('All'), fIndica: f('Indica'), fSativa: f('Sativa'), fHybrid: f('Hybrid'),\n      strains: data.filter((d) => st.type === 'All' || d[1] === st.type).map((d) => ({\n        name: d[0], type: d[1], genetics: d[2], breeder: d[3], drop: d[4], pill: pill[d[1]],\n        dropColor: d[4].indexOf('In ') === 0 ? '#C8102E' : '#767676'\n      }))\n    };\n  }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n", "Micro": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird \u2014 Micro Buds\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0;background:#F2F2F4}\na{color:#C8102E}a:hover{color:#9E0B22}\n\u003c/style>\n\u003cstyle>\n@media (max-width: 640px) {\n  [style*=\"max-width: 1200px\"] { padding-left: 20px !important; padding-right: 20px !important; }\n  [style*=\"flex: 1 1\"] { flex-basis: 100% !important; min-width: 0 !important; }\n  h1 { font-size: 56px !important; line-height: 0.92 !important; letter-spacing: 1.5px !important; text-wrap: balance; }\n  h2[style*=\"font-size: 72px\"], h2[style*=\"font-size: 56px\"] { font-size: 44px !important; }\n  h2[style*=\"font-size: 48px\"], h2[style*=\"font-size: 44px\"] { font-size: 36px !important; }\n\n  /* header: logo + Find a shop on top, page links in a swipeable row underneath */\n  header > div { gap: 0 10px !important; padding-top: 8px !important; padding-bottom: 8px !important; }\n  header a[aria-label=\"Redbird home\"] img { height: 26px !important; }\n  header a[href=\"Drops.dc.html\"][style*=\"height: 44px\"] { height: 40px !important; padding: 0 14px !important; }\n  header > div > div { margin-left: auto; }\n  header a[aria-label=\"Redbird on Instagram\"] { display: none !important; }\n  /* menu button: tap to show the page links as a list under the header row */\n  header label[for=\"rb-menu\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] { order: 3; flex: 1 1 100% !important; display: none !important; flex-direction: column; gap: 0 !important; margin: 8px -20px -8px; padding: 4px 20px 10px; border-top: 1px solid rgba(0,0,0,0.08); }\n  header #rb-menu:checked ~ nav[aria-label=\"Main\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] > span[aria-hidden=\"true\"] { display: none !important; }\n  header nav[aria-label=\"Main\"] a { display: flex; align-items: center; min-height: 48px; padding: 0 12px !important; margin: 2px 0; font-size: 17px !important; border-radius: 8px; }\n  header nav[aria-label=\"Main\"] a span { margin-left: 8px !important; }\n\n  /* photos */\n  img[style*=\"height: 600px\"], img[style*=\"height: 520px\"] { height: 300px !important; }\n  img[style*=\"height: 210px\"] { height: 130px !important; }\n  [style*=\"min-height: 560px\"], [style*=\"min-height: 460px\"] { min-height: 300px !important; }\n  [style*=\"right: 28px; bottom: 28px\"] { position: static !important; max-width: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n  /* grids */\n  [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { padding: 14px !important; }\n  [style*=\"minmax(160px, 1fr)\"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 6px !important; }\n  [style*=\"minmax(340px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; }\n  [role=\"radiogroup\"][style*=\"minmax(220px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  [role=\"radiogroup\"] button { padding: 14px !important; }\n\n  /* home page strain table becomes stacked rows */\n  [style*=\"min-width: 720px\"] { min-width: 0 !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"][style*=\"text-transform: uppercase\"] { display: none !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] { grid-template-columns: minmax(0, 1fr) auto !important; gap: 4px 12px !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] > :nth-child(n+3) { grid-column: 1 / -1; font-size: 13px; }\n\n  /* strains: hero stats stay on one line each */\n  [style*=\"display: flex; gap: 32px\"] { gap: 20px !important; }\n  [style*=\"font-size: 48px; line-height: 1\"] { font-size: 36px !important; white-space: nowrap; }\n\n  /* drops: tighter shop rows */\n  button[style*=\"min-width: 112px\"] { min-width: 0 !important; padding: 0 12px !important; }\n  form[style*=\"padding: 28px\"] { padding: 20px !important; }\n\n  /* strain label viewer */\n  [role=\"dialog\"] [style*=\"justify-content: space-between\"] { flex-wrap: wrap !important; padding: 12px 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 20px 24px\"] { padding: 10px !important; }\n  [role=\"dialog\"] [style*=\"padding: 18px 24px 22px\"] { padding: 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 24px\"] { padding: 10px !important; }\n}\n\u003c/style>\n\u003cstyle>\n  header { position: sticky !important; top: 0; z-index: 50; }\n  #rb-menu:focus-visible ~ div label[for=\"rb-menu\"] { outline: 2px solid #C8102E; outline-offset: 2px; }\n  @media (max-width: 640px) {\n    /* Products: current strains as a list (name + type, genetics, status) */\n    [style*=\"minmax(260px, 1fr)\"]:has(> a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]),\n    [style*=\"minmax(260px, 1fr)\"]:has(> * > a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]) { grid-template-columns: minmax(0, 1fr) !important; gap: 8px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { display: grid !important; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: \"name tag\" \"gen gen\" \"stat stat\"; align-items: center; gap: 2px 10px !important; padding: 12px 14px !important; border-radius: 10px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) { display: contents !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:first-child { grid-area: tag; justify-self: end; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:last-child { display: none !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(2) { grid-area: name; font-size: 24px !important; min-width: 0; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(3) { grid-area: gen; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(4) { grid-area: stat; margin-top: 4px !important; padding-top: 0 !important; border-top: 0 !important; }\n    /* Beta Bud cards, two across: long names and tags stay inside the card */\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] { padding: 14px !important; min-width: 0; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] div[style*=\"font-size: 30px\"] { font-size: 24px !important; overflow-wrap: anywhere; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] > div[style*=\"justify-content: space-between\"] { flex-wrap: wrap; gap: 6px !important; }\n    /* iPhone zooms into any field under 16px: keep form text at 16px */\n    input, select, textarea { font-size: 16px !important; }\n  }\n  @media (max-width: 340px) { [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; } }\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4\">\n\n  \u003cheader style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 14px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 16px 28px\">\n      \u003cinput type=\"checkbox\" id=\"rb-menu\" aria-label=\"Menu\" style=\"position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none\">\n      \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none; color: #111111\">\n        \u003cimg src=\"/_blob/e3c029787746d07f7ac7aabb57e33d83\" alt=\"Redbird\" style=\"height: 32px; width: auto; display: block\">\n      \u003c/a>\n      \u003cnav aria-label=\"Main\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1\">\n        \u003ca href=\"Flower.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 8px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Products\u003c/a>\n        \u003ca href=\"Strains.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Drops\u003c/a>\n        \u003ca href=\"Contact.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Contact\u003c/a>\n        \u003ca href=\"Merch.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Merch\u003cspan style=\"margin-left: 6px; padding: 2px 5px; border-radius: 4px; background: #F2F2F4; font-family: 'Space Mono', monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: #767676; vertical-align: 2px\">Soon\u003c/span>\u003c/a>\n        \u003cspan aria-hidden=\"true\" style=\"flex: none; width: 1px; height: 22px; background: rgba(0,0,0,0.18); align-self: center; margin: 0 10px\">\u003c/span>\n        \u003ca href=\"Retailers.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">For Retailers\u003c/a>\n      \u003c/nav>\n      \u003cdiv style=\"display: flex; align-items: center; gap: 10px\">\n        \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Redbird on Instagram\" style=\"width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.08); display: flex; align-items: center; justify-content: center; color: #111111\">\n          \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\u003crect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\">\u003c/rect>\u003ccircle cx=\"12\" cy=\"12\" r=\"4\">\u003c/circle>\u003ccircle cx=\"17.5\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\">\u003c/circle>\u003c/svg>\n        \u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n        \u003clabel for=\"rb-menu\" aria-hidden=\"true\" style=\"display: none; width: 40px; height: 40px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.12); align-items: center; justify-content: center; color: #111111; cursor: pointer\">\u003csvg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\u003cline x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\">\u003c/line>\u003cline x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\">\u003c/line>\u003cline x1=\"4\" y1=\"17\" x2=\"20\" y2=\"17\">\u003c/line>\u003c/svg>\u003c/label>\n      \u003c/div>\n    \u003c/div>\n  \u003c/header>\n\n  \u003cnav aria-label=\"Products\" style=\"max-width: 1200px; margin: 0 auto; padding: 28px 24px 0; display: flex; flex-wrap: wrap; align-items: center; gap: 6px\">\n    \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #767676; margin-right: 6px\">Products\u003c/span>\n    \u003ca href=\"Flower.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Flower\u003c/a>\n    \u003ca href=\"BetaBud.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Beta Bud\u003c/a>\n    \u003ca href=\"Micro.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Micro Buds\u003c/a>\n    \u003ca href=\"Prerolls.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Pre-Rolls\u003c/a>\n    \u003ca href=\"Rosin.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Rosin\u003c/a>\n  \u003c/nav>\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 32px 24px 56px; display: flex; flex-wrap: wrap; gap: 48px; align-items: center\">\n    \u003cdiv style=\"flex: 1 1 440px; display: flex; flex-direction: column; gap: 20px\">\n      \u003ch1 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 120px; letter-spacing: 3px; line-height: 0.9; color: #C8102E\">Micro Buds\u003c/h1>\n      \u003cp style=\"margin: 0; font-size: 17px; line-height: 1.7; color: #333333; max-width: 520px\">Redbird Cannabis Micro Buds offer a miniature delight with maximum potency. These small but mighty buds are meticulously cultivated for optimal flavor and potency, providing a concentrated cannabis experience. Perfect for discreet consumption or those who appreciate precision in their cannabis enjoyment, Redbird Micro Buds deliver a satisfying and potent high.\u003c/p>\n      \u003cdiv style=\"display: flex; flex-direction: column; gap: 8px\">\n        \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">Available in\u003c/div>\n        \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 8px\">\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">14G\u003c/span>\n        \u003c/div>\n      \u003c/div>\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 12px\">\n        \u003ca href=\"Strains.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Explore strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop near you\u003c/a>\n      \u003c/div>\n    \u003c/div>\n    \u003cdiv style=\"flex: 1 1 460px\">\n      \u003cimg src=\"/_blob/70a6b4c28b3f104b722d485dc25f2f43\" alt=\"The Redbird Micro Buds label\" style=\"width: 100%; height: 600px; object-fit: cover; border-radius: 12px; display: block\">\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"background: #111111; color: #FFFFFF\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px; display: flex; flex-wrap: wrap; gap: 24px; align-items: center; justify-content: space-between\">\n      \u003cdiv style=\"display: flex; flex-direction: column; gap: 6px\">\n        \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 40px; letter-spacing: 2px; line-height: 1\">Want to know when it lands near you?\u003c/div>\n        \u003cdiv style=\"font-size: 15px; color: #CCCCCC\">Follow your shops and favorite strains. We'll email you when fresh Redbird lands.\u003c/div>\n      \u003c/div>\n      \u003ca href=\"Drops.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Get drop alerts\u003c/a>\n    \u003c/div>\n  \u003c/section>\n\n  \u003cfooter style=\"background: #111111; color: #A3A3A3; border-top: 1px solid #2A2A2A\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px 36px; display: flex; flex-direction: column; gap: 26px\">\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px; align-items: center; justify-content: space-between\">\n        \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none\">\n          \u003cimg src=\"/_blob/186e35dcb739a15a6a58be91a24ac455\" alt=\"Redbird\" style=\"height: 30px; width: auto; display: block\">\n        \u003c/a>\n        \u003cnav aria-label=\"Footer\" style=\"display: flex; flex-wrap: wrap; gap: 24px; font-size: 14px\">\n          \u003ca href=\"Main.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Home\u003c/a>\n          \u003ca href=\"Flower.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Products\u003c/a>\n          \u003ca href=\"Strains.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Strains\u003c/a>\n          \u003ca href=\"Drops.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Drops\u003c/a>\n          \u003ca href=\"Contact.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Contact\u003c/a>\n          \u003ca href=\"Merch.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Merch\u003cspan style=\"margin-left: 5px; font-size: 11px; color: #8A8A8F\">(soon)\u003c/span>\u003c/a>\n          \u003ca href=\"Retailers.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">For Retailers\u003c/a>\n          \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF; text-decoration: none\">Instagram\u003c/a>\n        \u003c/nav>\n      \u003c/div>\n      \u003cdiv style=\"border-top: 1px solid #2A2A2A; padding-top: 22px; display: flex; flex-direction: column; gap: 12px; font-size: 12px; line-height: 1.7; max-width: 980px\">\n        \u003cp style=\"margin: 0\">Redbird is a Tier 3 Producer/Processor headquartered in Spokane, Washington.\u003c/p>\n        \u003cp style=\"margin: 0\">\u003cstrong style=\"color: #FFFFFF; font-weight: 700\">WARNING:\u003c/strong> This product may be unlawful outside of Washington State. This product has intoxicating effects and may be habit forming. Smoking is hazardous to your health. There may be health risks associated with consumption of this product. Should not be used by women that are pregnant or breast feeding. For use only by adults twenty-one and older. Keep out of reach of children. Marijuana can impair concentration, coordination, and judgment. Do not operate a vehicle or machinery under the influence of this drug.\u003c/p>\n        \u003cp style=\"margin: 0\">Redbird uses the following in the production of its cannabis products: Kaligreen by OAT Agrio Co LTD (approved for use in certified organic agriculture, OMRI listed) and Clonex Rooting Gel by Growth Technology, LTD.\u003c/p>\n        \u003cp style=\"margin: 0; font-family: 'Space Mono', monospace; font-size: 11px; color: #8A8A8A\">\u00a9 2016\u20132026 Redbird\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/footer>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":1600}}'>\nclass Component extends DCLogic {\n  renderVals() { return {}; }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n", "Prerolls": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird \u2014 Pre-Rolls\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0;background:#F2F2F4}\na{color:#C8102E}a:hover{color:#9E0B22}\n\u003c/style>\n\u003cstyle>\n@media (max-width: 640px) {\n  [style*=\"max-width: 1200px\"] { padding-left: 20px !important; padding-right: 20px !important; }\n  [style*=\"flex: 1 1\"] { flex-basis: 100% !important; min-width: 0 !important; }\n  h1 { font-size: 56px !important; line-height: 0.92 !important; letter-spacing: 1.5px !important; text-wrap: balance; }\n  h2[style*=\"font-size: 72px\"], h2[style*=\"font-size: 56px\"] { font-size: 44px !important; }\n  h2[style*=\"font-size: 48px\"], h2[style*=\"font-size: 44px\"] { font-size: 36px !important; }\n\n  /* header: logo + Find a shop on top, page links in a swipeable row underneath */\n  header > div { gap: 0 10px !important; padding-top: 8px !important; padding-bottom: 8px !important; }\n  header a[aria-label=\"Redbird home\"] img { height: 26px !important; }\n  header a[href=\"Drops.dc.html\"][style*=\"height: 44px\"] { height: 40px !important; padding: 0 14px !important; }\n  header > div > div { margin-left: auto; }\n  header a[aria-label=\"Redbird on Instagram\"] { display: none !important; }\n  /* menu button: tap to show the page links as a list under the header row */\n  header label[for=\"rb-menu\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] { order: 3; flex: 1 1 100% !important; display: none !important; flex-direction: column; gap: 0 !important; margin: 8px -20px -8px; padding: 4px 20px 10px; border-top: 1px solid rgba(0,0,0,0.08); }\n  header #rb-menu:checked ~ nav[aria-label=\"Main\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] > span[aria-hidden=\"true\"] { display: none !important; }\n  header nav[aria-label=\"Main\"] a { display: flex; align-items: center; min-height: 48px; padding: 0 12px !important; margin: 2px 0; font-size: 17px !important; border-radius: 8px; }\n  header nav[aria-label=\"Main\"] a span { margin-left: 8px !important; }\n\n  /* photos */\n  img[style*=\"height: 600px\"], img[style*=\"height: 520px\"] { height: 300px !important; }\n  img[style*=\"height: 210px\"] { height: 130px !important; }\n  [style*=\"min-height: 560px\"], [style*=\"min-height: 460px\"] { min-height: 300px !important; }\n  [style*=\"right: 28px; bottom: 28px\"] { position: static !important; max-width: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n  /* grids */\n  [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { padding: 14px !important; }\n  [style*=\"minmax(160px, 1fr)\"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 6px !important; }\n  [style*=\"minmax(340px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; }\n  [role=\"radiogroup\"][style*=\"minmax(220px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  [role=\"radiogroup\"] button { padding: 14px !important; }\n\n  /* home page strain table becomes stacked rows */\n  [style*=\"min-width: 720px\"] { min-width: 0 !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"][style*=\"text-transform: uppercase\"] { display: none !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] { grid-template-columns: minmax(0, 1fr) auto !important; gap: 4px 12px !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] > :nth-child(n+3) { grid-column: 1 / -1; font-size: 13px; }\n\n  /* strains: hero stats stay on one line each */\n  [style*=\"display: flex; gap: 32px\"] { gap: 20px !important; }\n  [style*=\"font-size: 48px; line-height: 1\"] { font-size: 36px !important; white-space: nowrap; }\n\n  /* drops: tighter shop rows */\n  button[style*=\"min-width: 112px\"] { min-width: 0 !important; padding: 0 12px !important; }\n  form[style*=\"padding: 28px\"] { padding: 20px !important; }\n\n  /* strain label viewer */\n  [role=\"dialog\"] [style*=\"justify-content: space-between\"] { flex-wrap: wrap !important; padding: 12px 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 20px 24px\"] { padding: 10px !important; }\n  [role=\"dialog\"] [style*=\"padding: 18px 24px 22px\"] { padding: 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 24px\"] { padding: 10px !important; }\n}\n\u003c/style>\n\u003cstyle>\n  header { position: sticky !important; top: 0; z-index: 50; }\n  #rb-menu:focus-visible ~ div label[for=\"rb-menu\"] { outline: 2px solid #C8102E; outline-offset: 2px; }\n  @media (max-width: 640px) {\n    /* Products: current strains as a list (name + type, genetics, status) */\n    [style*=\"minmax(260px, 1fr)\"]:has(> a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]),\n    [style*=\"minmax(260px, 1fr)\"]:has(> * > a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]) { grid-template-columns: minmax(0, 1fr) !important; gap: 8px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { display: grid !important; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: \"name tag\" \"gen gen\" \"stat stat\"; align-items: center; gap: 2px 10px !important; padding: 12px 14px !important; border-radius: 10px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) { display: contents !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:first-child { grid-area: tag; justify-self: end; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:last-child { display: none !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(2) { grid-area: name; font-size: 24px !important; min-width: 0; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(3) { grid-area: gen; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(4) { grid-area: stat; margin-top: 4px !important; padding-top: 0 !important; border-top: 0 !important; }\n    /* Beta Bud cards, two across: long names and tags stay inside the card */\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] { padding: 14px !important; min-width: 0; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] div[style*=\"font-size: 30px\"] { font-size: 24px !important; overflow-wrap: anywhere; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] > div[style*=\"justify-content: space-between\"] { flex-wrap: wrap; gap: 6px !important; }\n    /* iPhone zooms into any field under 16px: keep form text at 16px */\n    input, select, textarea { font-size: 16px !important; }\n  }\n  @media (max-width: 340px) { [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; } }\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4\">\n\n  \u003cheader style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 14px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 16px 28px\">\n      \u003cinput type=\"checkbox\" id=\"rb-menu\" aria-label=\"Menu\" style=\"position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none\">\n      \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none; color: #111111\">\n        \u003cimg src=\"/_blob/e3c029787746d07f7ac7aabb57e33d83\" alt=\"Redbird\" style=\"height: 32px; width: auto; display: block\">\n      \u003c/a>\n      \u003cnav aria-label=\"Main\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1\">\n        \u003ca href=\"Flower.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 8px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Products\u003c/a>\n        \u003ca href=\"Strains.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Drops\u003c/a>\n        \u003ca href=\"Contact.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Contact\u003c/a>\n        \u003ca href=\"Merch.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Merch\u003cspan style=\"margin-left: 6px; padding: 2px 5px; border-radius: 4px; background: #F2F2F4; font-family: 'Space Mono', monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: #767676; vertical-align: 2px\">Soon\u003c/span>\u003c/a>\n        \u003cspan aria-hidden=\"true\" style=\"flex: none; width: 1px; height: 22px; background: rgba(0,0,0,0.18); align-self: center; margin: 0 10px\">\u003c/span>\n        \u003ca href=\"Retailers.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">For Retailers\u003c/a>\n      \u003c/nav>\n      \u003cdiv style=\"display: flex; align-items: center; gap: 10px\">\n        \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Redbird on Instagram\" style=\"width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.08); display: flex; align-items: center; justify-content: center; color: #111111\">\n          \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\u003crect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\">\u003c/rect>\u003ccircle cx=\"12\" cy=\"12\" r=\"4\">\u003c/circle>\u003ccircle cx=\"17.5\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\">\u003c/circle>\u003c/svg>\n        \u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n        \u003clabel for=\"rb-menu\" aria-hidden=\"true\" style=\"display: none; width: 40px; height: 40px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.12); align-items: center; justify-content: center; color: #111111; cursor: pointer\">\u003csvg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\u003cline x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\">\u003c/line>\u003cline x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\">\u003c/line>\u003cline x1=\"4\" y1=\"17\" x2=\"20\" y2=\"17\">\u003c/line>\u003c/svg>\u003c/label>\n      \u003c/div>\n    \u003c/div>\n  \u003c/header>\n\n  \u003cnav aria-label=\"Products\" style=\"max-width: 1200px; margin: 0 auto; padding: 28px 24px 0; display: flex; flex-wrap: wrap; align-items: center; gap: 6px\">\n    \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #767676; margin-right: 6px\">Products\u003c/span>\n    \u003ca href=\"Flower.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Flower\u003c/a>\n    \u003ca href=\"BetaBud.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Beta Bud\u003c/a>\n    \u003ca href=\"Micro.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Micro Buds\u003c/a>\n    \u003ca href=\"Prerolls.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Pre-Rolls\u003c/a>\n    \u003ca href=\"Rosin.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Rosin\u003c/a>\n  \u003c/nav>\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 32px 24px 56px; display: flex; flex-wrap: wrap; gap: 48px; align-items: center\">\n    \u003cdiv style=\"flex: 1 1 440px; display: flex; flex-direction: column; gap: 20px\">\n      \u003ch1 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 120px; letter-spacing: 3px; line-height: 0.9; color: #C8102E\">Pre-Rolled Joints\u003c/h1>\n      \u003cp style=\"margin: 0; font-size: 17px; line-height: 1.7; color: #333333; max-width: 520px\">Redbird Cannabis pre-rolled joints provide convenience without compromising quality. Meticulously crafted with premium flower, these joints offer a smooth and flavorful smoking experience. Individually rolled for consistency, they ensure a hassle-free and enjoyable way to savor the rich terpene profile and potency of Redbird Cannabis.\u003c/p>\n      \u003cdiv style=\"display: flex; flex-direction: column; gap: 8px\">\n        \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">Available in\u003c/div>\n        \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 8px\">\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">1G SINGLE\u003c/span>\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">2-PACK \u00b7 .5G\u003c/span>\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">10-PACK \u00b7 .5G\u003c/span>\n        \u003c/div>\n      \u003c/div>\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 12px\">\n        \u003ca href=\"Strains.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Explore strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop near you\u003c/a>\n      \u003c/div>\n    \u003c/div>\n    \u003cdiv style=\"flex: 1 1 460px\">\n      \u003cimg src=\"/_blob/4bb5b8a779d339cae2a36896e3e42b99\" alt=\"Redbird pre-rolled joints with red mint tins\" style=\"width: 100%; height: 600px; object-fit: cover; border-radius: 12px; display: block\">\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 0 24px 64px\">\n    \u003cdiv style=\"position: relative; border-radius: 12px; overflow: hidden; background: #9E0B22\">\n      \u003cimg src=\"/_blob/e78fcf9b838e0064d7a2ed9e43bcdcbe\" alt=\"Redbird pre-rolled joint boxes on a red table with chocolate and flower\" style=\"width: 100%; height: 440px; object-fit: cover; display: block\">\n    \u003c/div>\n    \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 8px 24px; padding-top: 14px; font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1px; text-transform: uppercase; color: #767676\">\n      \u003cspan>10 half-gram joints\u003c/span>\u003cspan>Aeroponic flower\u003c/span>\u003cspan>Spokane, Washington\u003c/span>\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"background: #111111; color: #FFFFFF\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px; display: flex; flex-wrap: wrap; gap: 24px; align-items: center; justify-content: space-between\">\n      \u003cdiv style=\"display: flex; flex-direction: column; gap: 6px\">\n        \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 40px; letter-spacing: 2px; line-height: 1\">Want to know when it lands near you?\u003c/div>\n        \u003cdiv style=\"font-size: 15px; color: #CCCCCC\">Follow your shops and favorite strains. We'll email you when fresh Redbird lands.\u003c/div>\n      \u003c/div>\n      \u003ca href=\"Drops.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Get drop alerts\u003c/a>\n    \u003c/div>\n  \u003c/section>\n\n  \u003cfooter style=\"background: #111111; color: #A3A3A3; border-top: 1px solid #2A2A2A\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px 36px; display: flex; flex-direction: column; gap: 26px\">\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px; align-items: center; justify-content: space-between\">\n        \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none\">\n          \u003cimg src=\"/_blob/186e35dcb739a15a6a58be91a24ac455\" alt=\"Redbird\" style=\"height: 30px; width: auto; display: block\">\n        \u003c/a>\n        \u003cnav aria-label=\"Footer\" style=\"display: flex; flex-wrap: wrap; gap: 24px; font-size: 14px\">\n          \u003ca href=\"Main.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Home\u003c/a>\n          \u003ca href=\"Flower.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Products\u003c/a>\n          \u003ca href=\"Strains.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Strains\u003c/a>\n          \u003ca href=\"Drops.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Drops\u003c/a>\n          \u003ca href=\"Contact.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Contact\u003c/a>\n          \u003ca href=\"Merch.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Merch\u003cspan style=\"margin-left: 5px; font-size: 11px; color: #8A8A8F\">(soon)\u003c/span>\u003c/a>\n          \u003ca href=\"Retailers.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">For Retailers\u003c/a>\n          \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF; text-decoration: none\">Instagram\u003c/a>\n        \u003c/nav>\n      \u003c/div>\n      \u003cdiv style=\"border-top: 1px solid #2A2A2A; padding-top: 22px; display: flex; flex-direction: column; gap: 12px; font-size: 12px; line-height: 1.7; max-width: 980px\">\n        \u003cp style=\"margin: 0\">Redbird is a Tier 3 Producer/Processor headquartered in Spokane, Washington.\u003c/p>\n        \u003cp style=\"margin: 0\">\u003cstrong style=\"color: #FFFFFF; font-weight: 700\">WARNING:\u003c/strong> This product may be unlawful outside of Washington State. This product has intoxicating effects and may be habit forming. Smoking is hazardous to your health. There may be health risks associated with consumption of this product. Should not be used by women that are pregnant or breast feeding. For use only by adults twenty-one and older. Keep out of reach of children. Marijuana can impair concentration, coordination, and judgment. Do not operate a vehicle or machinery under the influence of this drug.\u003c/p>\n        \u003cp style=\"margin: 0\">Redbird uses the following in the production of its cannabis products: Kaligreen by OAT Agrio Co LTD (approved for use in certified organic agriculture, OMRI listed) and Clonex Rooting Gel by Growth Technology, LTD.\u003c/p>\n        \u003cp style=\"margin: 0; font-family: 'Space Mono', monospace; font-size: 11px; color: #8A8A8A\">\u00a9 2016\u20132026 Redbird\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/footer>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":2160}}'>\nclass Component extends DCLogic {\n  renderVals() { return {}; }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n", "Rosin": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird \u2014 Rosin\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0;background:#F2F2F4}\na{color:#C8102E}a:hover{color:#9E0B22}\n\u003c/style>\n\u003cstyle>\n@media (max-width: 640px) {\n  [style*=\"max-width: 1200px\"] { padding-left: 20px !important; padding-right: 20px !important; }\n  [style*=\"flex: 1 1\"] { flex-basis: 100% !important; min-width: 0 !important; }\n  h1 { font-size: 56px !important; line-height: 0.92 !important; letter-spacing: 1.5px !important; text-wrap: balance; }\n  h2[style*=\"font-size: 72px\"], h2[style*=\"font-size: 56px\"] { font-size: 44px !important; }\n  h2[style*=\"font-size: 48px\"], h2[style*=\"font-size: 44px\"] { font-size: 36px !important; }\n\n  /* header: logo + Find a shop on top, page links in a swipeable row underneath */\n  header > div { gap: 0 10px !important; padding-top: 8px !important; padding-bottom: 8px !important; }\n  header a[aria-label=\"Redbird home\"] img { height: 26px !important; }\n  header a[href=\"Drops.dc.html\"][style*=\"height: 44px\"] { height: 40px !important; padding: 0 14px !important; }\n  header > div > div { margin-left: auto; }\n  header a[aria-label=\"Redbird on Instagram\"] { display: none !important; }\n  /* menu button: tap to show the page links as a list under the header row */\n  header label[for=\"rb-menu\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] { order: 3; flex: 1 1 100% !important; display: none !important; flex-direction: column; gap: 0 !important; margin: 8px -20px -8px; padding: 4px 20px 10px; border-top: 1px solid rgba(0,0,0,0.08); }\n  header #rb-menu:checked ~ nav[aria-label=\"Main\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] > span[aria-hidden=\"true\"] { display: none !important; }\n  header nav[aria-label=\"Main\"] a { display: flex; align-items: center; min-height: 48px; padding: 0 12px !important; margin: 2px 0; font-size: 17px !important; border-radius: 8px; }\n  header nav[aria-label=\"Main\"] a span { margin-left: 8px !important; }\n\n  /* photos */\n  img[style*=\"height: 600px\"], img[style*=\"height: 520px\"] { height: 300px !important; }\n  img[style*=\"height: 210px\"] { height: 130px !important; }\n  [style*=\"min-height: 560px\"], [style*=\"min-height: 460px\"] { min-height: 300px !important; }\n  [style*=\"right: 28px; bottom: 28px\"] { position: static !important; max-width: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n  /* grids */\n  [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { padding: 14px !important; }\n  [style*=\"minmax(160px, 1fr)\"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 6px !important; }\n  [style*=\"minmax(340px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; }\n  [role=\"radiogroup\"][style*=\"minmax(220px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  [role=\"radiogroup\"] button { padding: 14px !important; }\n\n  /* home page strain table becomes stacked rows */\n  [style*=\"min-width: 720px\"] { min-width: 0 !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"][style*=\"text-transform: uppercase\"] { display: none !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] { grid-template-columns: minmax(0, 1fr) auto !important; gap: 4px 12px !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] > :nth-child(n+3) { grid-column: 1 / -1; font-size: 13px; }\n\n  /* strains: hero stats stay on one line each */\n  [style*=\"display: flex; gap: 32px\"] { gap: 20px !important; }\n  [style*=\"font-size: 48px; line-height: 1\"] { font-size: 36px !important; white-space: nowrap; }\n\n  /* drops: tighter shop rows */\n  button[style*=\"min-width: 112px\"] { min-width: 0 !important; padding: 0 12px !important; }\n  form[style*=\"padding: 28px\"] { padding: 20px !important; }\n\n  /* strain label viewer */\n  [role=\"dialog\"] [style*=\"justify-content: space-between\"] { flex-wrap: wrap !important; padding: 12px 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 20px 24px\"] { padding: 10px !important; }\n  [role=\"dialog\"] [style*=\"padding: 18px 24px 22px\"] { padding: 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 24px\"] { padding: 10px !important; }\n}\n\u003c/style>\n\u003cstyle>\n  header { position: sticky !important; top: 0; z-index: 50; }\n  #rb-menu:focus-visible ~ div label[for=\"rb-menu\"] { outline: 2px solid #C8102E; outline-offset: 2px; }\n  @media (max-width: 640px) {\n    /* Products: current strains as a list (name + type, genetics, status) */\n    [style*=\"minmax(260px, 1fr)\"]:has(> a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]),\n    [style*=\"minmax(260px, 1fr)\"]:has(> * > a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]) { grid-template-columns: minmax(0, 1fr) !important; gap: 8px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { display: grid !important; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: \"name tag\" \"gen gen\" \"stat stat\"; align-items: center; gap: 2px 10px !important; padding: 12px 14px !important; border-radius: 10px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) { display: contents !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:first-child { grid-area: tag; justify-self: end; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:last-child { display: none !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(2) { grid-area: name; font-size: 24px !important; min-width: 0; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(3) { grid-area: gen; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(4) { grid-area: stat; margin-top: 4px !important; padding-top: 0 !important; border-top: 0 !important; }\n    /* Beta Bud cards, two across: long names and tags stay inside the card */\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] { padding: 14px !important; min-width: 0; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] div[style*=\"font-size: 30px\"] { font-size: 24px !important; overflow-wrap: anywhere; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] > div[style*=\"justify-content: space-between\"] { flex-wrap: wrap; gap: 6px !important; }\n    /* iPhone zooms into any field under 16px: keep form text at 16px */\n    input, select, textarea { font-size: 16px !important; }\n  }\n  @media (max-width: 340px) { [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; } }\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4\">\n\n  \u003cheader style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 14px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 16px 28px\">\n      \u003cinput type=\"checkbox\" id=\"rb-menu\" aria-label=\"Menu\" style=\"position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none\">\n      \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none; color: #111111\">\n        \u003cimg src=\"/_blob/e3c029787746d07f7ac7aabb57e33d83\" alt=\"Redbird\" style=\"height: 32px; width: auto; display: block\">\n      \u003c/a>\n      \u003cnav aria-label=\"Main\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1\">\n        \u003ca href=\"Flower.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 8px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Products\u003c/a>\n        \u003ca href=\"Strains.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Drops\u003c/a>\n        \u003ca href=\"Contact.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Contact\u003c/a>\n        \u003ca href=\"Merch.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Merch\u003cspan style=\"margin-left: 6px; padding: 2px 5px; border-radius: 4px; background: #F2F2F4; font-family: 'Space Mono', monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: #767676; vertical-align: 2px\">Soon\u003c/span>\u003c/a>\n        \u003cspan aria-hidden=\"true\" style=\"flex: none; width: 1px; height: 22px; background: rgba(0,0,0,0.18); align-self: center; margin: 0 10px\">\u003c/span>\n        \u003ca href=\"Retailers.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">For Retailers\u003c/a>\n      \u003c/nav>\n      \u003cdiv style=\"display: flex; align-items: center; gap: 10px\">\n        \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Redbird on Instagram\" style=\"width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.08); display: flex; align-items: center; justify-content: center; color: #111111\">\n          \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\u003crect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\">\u003c/rect>\u003ccircle cx=\"12\" cy=\"12\" r=\"4\">\u003c/circle>\u003ccircle cx=\"17.5\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\">\u003c/circle>\u003c/svg>\n        \u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n        \u003clabel for=\"rb-menu\" aria-hidden=\"true\" style=\"display: none; width: 40px; height: 40px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.12); align-items: center; justify-content: center; color: #111111; cursor: pointer\">\u003csvg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\u003cline x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\">\u003c/line>\u003cline x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\">\u003c/line>\u003cline x1=\"4\" y1=\"17\" x2=\"20\" y2=\"17\">\u003c/line>\u003c/svg>\u003c/label>\n      \u003c/div>\n    \u003c/div>\n  \u003c/header>\n\n  \u003cnav aria-label=\"Products\" style=\"max-width: 1200px; margin: 0 auto; padding: 28px 24px 0; display: flex; flex-wrap: wrap; align-items: center; gap: 6px\">\n    \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #767676; margin-right: 6px\">Products\u003c/span>\n    \u003ca href=\"Flower.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Flower\u003c/a>\n    \u003ca href=\"BetaBud.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Beta Bud\u003c/a>\n    \u003ca href=\"Micro.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Micro Buds\u003c/a>\n    \u003ca href=\"Prerolls.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Pre-Rolls\u003c/a>\n    \u003ca href=\"Rosin.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Rosin\u003c/a>\n  \u003c/nav>\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 32px 24px 56px; display: flex; flex-wrap: wrap; gap: 48px; align-items: center\">\n    \u003cdiv style=\"flex: 1 1 440px; display: flex; flex-direction: column; gap: 20px\">\n      \u003ch1 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 120px; letter-spacing: 3px; line-height: 0.9; color: #C8102E\">Rosin\u003c/h1>\n      \u003cp style=\"margin: 0; font-size: 17px; line-height: 1.7; color: #333333; max-width: 520px\">Redbird Live Rosin is single source: every jar is pressed in house from bubble hash we make from our own flower, grown and extracted in a controlled environment. No solvents \u2014 just ice, water, heat and pressure \u2014 so it captures each strain's terpenes for a robust flavor. Renowned for high THC content, it delivers a potent experience through dabbing or vaporization. A top choice for connoisseurs seeking an authentic and powerful cannabis journey.\u003c/p>\n      \u003cdiv style=\"display: flex; flex-direction: column; gap: 8px\">\n        \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">How it\u2019s made\u003c/div>\n        \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 8px\">\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">LIVE ROSIN\u003c/span>\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">SOLVENT-FREE\u003c/span>\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">PRESSED IN HOUSE\u003c/span>\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">SINGLE SOURCE\u003c/span>\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">CONTROLLED ENVIRONMENT\u003c/span>\n        \u003c/div>\n      \u003c/div>\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 12px\">\n        \u003ca href=\"Strains.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Explore strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop near you\u003c/a>\n      \u003c/div>\n    \u003c/div>\n    \u003cdiv style=\"flex: 1 1 460px\">\n      \u003cimg src=\"/_blob/c1827be414c190bc9faa7f53344faef9\" alt=\"A jar of Redbird rosin next to its white Redbird lid\" style=\"width: 100%; height: 600px; object-fit: cover; border-radius: 12px; display: block\">\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"background: #111111; color: #FFFFFF\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px; display: flex; flex-wrap: wrap; gap: 24px; align-items: center; justify-content: space-between\">\n      \u003cdiv style=\"display: flex; flex-direction: column; gap: 6px\">\n        \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 40px; letter-spacing: 2px; line-height: 1\">Want to know when it lands near you?\u003c/div>\n        \u003cdiv style=\"font-size: 15px; color: #CCCCCC\">Follow your shops and favorite strains. We'll email you when fresh Redbird lands.\u003c/div>\n      \u003c/div>\n      \u003ca href=\"Drops.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Get drop alerts\u003c/a>\n    \u003c/div>\n  \u003c/section>\n\n  \u003cfooter style=\"background: #111111; color: #A3A3A3; border-top: 1px solid #2A2A2A\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px 36px; display: flex; flex-direction: column; gap: 26px\">\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px; align-items: center; justify-content: space-between\">\n        \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none\">\n          \u003cimg src=\"/_blob/186e35dcb739a15a6a58be91a24ac455\" alt=\"Redbird\" style=\"height: 30px; width: auto; display: block\">\n        \u003c/a>\n        \u003cnav aria-label=\"Footer\" style=\"display: flex; flex-wrap: wrap; gap: 24px; font-size: 14px\">\n          \u003ca href=\"Main.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Home\u003c/a>\n          \u003ca href=\"Flower.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Products\u003c/a>\n          \u003ca href=\"Strains.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Strains\u003c/a>\n          \u003ca href=\"Drops.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Drops\u003c/a>\n          \u003ca href=\"Contact.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Contact\u003c/a>\n          \u003ca href=\"Merch.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Merch\u003cspan style=\"margin-left: 5px; font-size: 11px; color: #8A8A8F\">(soon)\u003c/span>\u003c/a>\n          \u003ca href=\"Retailers.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">For Retailers\u003c/a>\n          \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF; text-decoration: none\">Instagram\u003c/a>\n        \u003c/nav>\n      \u003c/div>\n      \u003cdiv style=\"border-top: 1px solid #2A2A2A; padding-top: 22px; display: flex; flex-direction: column; gap: 12px; font-size: 12px; line-height: 1.7; max-width: 980px\">\n        \u003cp style=\"margin: 0\">Redbird is a Tier 3 Producer/Processor headquartered in Spokane, Washington.\u003c/p>\n        \u003cp style=\"margin: 0\">\u003cstrong style=\"color: #FFFFFF; font-weight: 700\">WARNING:\u003c/strong> This product may be unlawful outside of Washington State. This product has intoxicating effects and may be habit forming. Smoking is hazardous to your health. There may be health risks associated with consumption of this product. Should not be used by women that are pregnant or breast feeding. For use only by adults twenty-one and older. Keep out of reach of children. Marijuana can impair concentration, coordination, and judgment. Do not operate a vehicle or machinery under the influence of this drug.\u003c/p>\n        \u003cp style=\"margin: 0\">Redbird uses the following in the production of its cannabis products: Kaligreen by OAT Agrio Co LTD (approved for use in certified organic agriculture, OMRI listed) and Clonex Rooting Gel by Growth Technology, LTD.\u003c/p>\n        \u003cp style=\"margin: 0; font-family: 'Space Mono', monospace; font-size: 11px; color: #8A8A8A\">\u00a9 2016\u20132026 Redbird\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/footer>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":1600}}'>\nclass Component extends DCLogic {\n  renderVals() { return {}; }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n", "Strains": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird \u2014 Strains\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0;background:#F2F2F4}\na{color:#C8102E}a:hover{color:#9E0B22}\n\u003c/style>\n\u003cstyle>\n@media (max-width: 640px) {\n  [style*=\"max-width: 1200px\"] { padding-left: 20px !important; padding-right: 20px !important; }\n  [style*=\"flex: 1 1\"] { flex-basis: 100% !important; min-width: 0 !important; }\n  h1 { font-size: 56px !important; line-height: 0.92 !important; letter-spacing: 1.5px !important; text-wrap: balance; }\n  h2[style*=\"font-size: 72px\"], h2[style*=\"font-size: 56px\"] { font-size: 44px !important; }\n  h2[style*=\"font-size: 48px\"], h2[style*=\"font-size: 44px\"] { font-size: 36px !important; }\n\n  /* header: logo + Find a shop on top, page links in a swipeable row underneath */\n  header > div { gap: 0 10px !important; padding-top: 8px !important; padding-bottom: 8px !important; }\n  header a[aria-label=\"Redbird home\"] img { height: 26px !important; }\n  header a[href=\"Drops.dc.html\"][style*=\"height: 44px\"] { height: 40px !important; padding: 0 14px !important; }\n  header > div > div { margin-left: auto; }\n  header a[aria-label=\"Redbird on Instagram\"] { display: none !important; }\n  /* menu button: tap to show the page links as a list under the header row */\n  header label[for=\"rb-menu\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] { order: 3; flex: 1 1 100% !important; display: none !important; flex-direction: column; gap: 0 !important; margin: 8px -20px -8px; padding: 4px 20px 10px; border-top: 1px solid rgba(0,0,0,0.08); }\n  header #rb-menu:checked ~ nav[aria-label=\"Main\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] > span[aria-hidden=\"true\"] { display: none !important; }\n  header nav[aria-label=\"Main\"] a { display: flex; align-items: center; min-height: 48px; padding: 0 12px !important; margin: 2px 0; font-size: 17px !important; border-radius: 8px; }\n  header nav[aria-label=\"Main\"] a span { margin-left: 8px !important; }\n\n  /* photos */\n  img[style*=\"height: 600px\"], img[style*=\"height: 520px\"] { height: 300px !important; }\n  img[style*=\"height: 210px\"] { height: 130px !important; }\n  [style*=\"min-height: 560px\"], [style*=\"min-height: 460px\"] { min-height: 300px !important; }\n  [style*=\"right: 28px; bottom: 28px\"] { position: static !important; max-width: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n  /* grids */\n  [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { padding: 14px !important; }\n  [style*=\"minmax(160px, 1fr)\"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 6px !important; }\n  [style*=\"minmax(340px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; }\n  [role=\"radiogroup\"][style*=\"minmax(220px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  [role=\"radiogroup\"] button { padding: 14px !important; }\n\n  /* home page strain table becomes stacked rows */\n  [style*=\"min-width: 720px\"] { min-width: 0 !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"][style*=\"text-transform: uppercase\"] { display: none !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] { grid-template-columns: minmax(0, 1fr) auto !important; gap: 4px 12px !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] > :nth-child(n+3) { grid-column: 1 / -1; font-size: 13px; }\n\n  /* strains: hero stats stay on one line each */\n  [style*=\"display: flex; gap: 32px\"] { gap: 20px !important; }\n  [style*=\"font-size: 48px; line-height: 1\"] { font-size: 36px !important; white-space: nowrap; }\n\n  /* drops: tighter shop rows */\n  button[style*=\"min-width: 112px\"] { min-width: 0 !important; padding: 0 12px !important; }\n  form[style*=\"padding: 28px\"] { padding: 20px !important; }\n\n  /* strain label viewer */\n  [role=\"dialog\"] [style*=\"justify-content: space-between\"] { flex-wrap: wrap !important; padding: 12px 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 20px 24px\"] { padding: 10px !important; }\n  [role=\"dialog\"] [style*=\"padding: 18px 24px 22px\"] { padding: 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 24px\"] { padding: 10px !important; }\n}\n\u003c/style>\n\u003cstyle>\n  header { position: sticky !important; top: 0; z-index: 50; }\n  #rb-menu:focus-visible ~ div label[for=\"rb-menu\"] { outline: 2px solid #C8102E; outline-offset: 2px; }\n  @media (max-width: 640px) {\n    /* Products: current strains as a list (name + type, genetics, status) */\n    [style*=\"minmax(260px, 1fr)\"]:has(> a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]),\n    [style*=\"minmax(260px, 1fr)\"]:has(> * > a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]) { grid-template-columns: minmax(0, 1fr) !important; gap: 8px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { display: grid !important; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: \"name tag\" \"gen gen\" \"stat stat\"; align-items: center; gap: 2px 10px !important; padding: 12px 14px !important; border-radius: 10px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) { display: contents !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:first-child { grid-area: tag; justify-self: end; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:last-child { display: none !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(2) { grid-area: name; font-size: 24px !important; min-width: 0; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(3) { grid-area: gen; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(4) { grid-area: stat; margin-top: 4px !important; padding-top: 0 !important; border-top: 0 !important; }\n    /* Beta Bud cards, two across: long names and tags stay inside the card */\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] { padding: 14px !important; min-width: 0; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] div[style*=\"font-size: 30px\"] { font-size: 24px !important; overflow-wrap: anywhere; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] > div[style*=\"justify-content: space-between\"] { flex-wrap: wrap; gap: 6px !important; }\n    /* iPhone zooms into any field under 16px: keep form text at 16px */\n    input, select, textarea { font-size: 16px !important; }\n  }\n  @media (max-width: 340px) { [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; } }\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4\">\n\n  \u003cheader style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 14px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 16px 28px\">\n      \u003cinput type=\"checkbox\" id=\"rb-menu\" aria-label=\"Menu\" style=\"position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none\">\n      \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none; color: #111111\">\n        \u003cimg src=\"/_blob/e3c029787746d07f7ac7aabb57e33d83\" alt=\"Redbird\" style=\"height: 32px; width: auto; display: block\">\n      \u003c/a>\n      \u003cnav aria-label=\"Main\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1\">\n        \u003ca href=\"Flower.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Products\u003c/a>\n        \u003ca href=\"Strains.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 8px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Drops\u003c/a>\n        \u003ca href=\"Contact.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Contact\u003c/a>\n        \u003ca href=\"Merch.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Merch\u003cspan style=\"margin-left: 6px; padding: 2px 5px; border-radius: 4px; background: #F2F2F4; font-family: 'Space Mono', monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: #767676; vertical-align: 2px\">Soon\u003c/span>\u003c/a>\n        \u003cspan aria-hidden=\"true\" style=\"flex: none; width: 1px; height: 22px; background: rgba(0,0,0,0.18); align-self: center; margin: 0 10px\">\u003c/span>\n        \u003ca href=\"Retailers.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">For Retailers\u003c/a>\n      \u003c/nav>\n      \u003cdiv style=\"display: flex; align-items: center; gap: 10px\">\n        \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Redbird on Instagram\" style=\"width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.08); display: flex; align-items: center; justify-content: center; color: #111111\">\n          \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\u003crect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\">\u003c/rect>\u003ccircle cx=\"12\" cy=\"12\" r=\"4\">\u003c/circle>\u003ccircle cx=\"17.5\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\">\u003c/circle>\u003c/svg>\n        \u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n        \u003clabel for=\"rb-menu\" aria-hidden=\"true\" style=\"display: none; width: 40px; height: 40px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.12); align-items: center; justify-content: center; color: #111111; cursor: pointer\">\u003csvg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\u003cline x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\">\u003c/line>\u003cline x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\">\u003c/line>\u003cline x1=\"4\" y1=\"17\" x2=\"20\" y2=\"17\">\u003c/line>\u003c/svg>\u003c/label>\n      \u003c/div>\n    \u003c/div>\n  \u003c/header>\n\n  \u003csection style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 48px 24px 40px; display: flex; flex-wrap: wrap; gap: 24px 48px; align-items: flex-end; justify-content: space-between\">\n      \u003cdiv style=\"flex: 1 1 560px; display: flex; flex-direction: column; gap: 14px\">\n        \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">Strain library\u003c/div>\n        \u003ch1 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 112px; letter-spacing: 2px; line-height: 0.9\">Strains\u003c/h1>\n        \u003cp style=\"margin: 0; font-size: 17px; line-height: 1.6; color: #555555; max-width: 600px\">Every Redbird strain gets its own hand-drawn label. Browse the lineup in the flower rooms now, the genetics behind each one, and what's coming out of the grow rooms next.\u003c/p>\n      \u003c/div>\n      \u003cdiv style=\"display: flex; gap: 32px\">\n        \u003cdiv style=\"display: flex; flex-direction: column; gap: 2px\">\n          \u003cspan style=\"font-family: 'Bebas Neue', sans-serif; font-size: 48px; line-height: 1; color: #C8102E\">{{total}}\u003c/span>\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; text-transform: uppercase; color: #767676\">Strains\u003c/span>\n        \u003c/div>\n        \u003cdiv style=\"display: flex; flex-direction: column; gap: 2px\">\n          \u003cspan style=\"font-family: 'Bebas Neue', sans-serif; font-size: 48px; line-height: 1; color: #111111\">{{thisWeekCount}}\u003c/span>\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; text-transform: uppercase; color: #767676\">In the flower rooms now\u003c/span>\n        \u003c/div>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection aria-labelledby=\"harvest-title\" style=\"max-width: 1200px; margin: 0 auto; padding: 36px 24px 8px; display: flex; flex-direction: column; gap: 16px\">\n    \u003cdiv style=\"display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 8px 24px\">\n      \u003cdiv style=\"display: flex; flex-direction: column; gap: 6px\">\n        \u003ch2 id=\"harvest-title\" style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 44px; letter-spacing: 3px; line-height: 1\">Harvest board\u003c/h2>\n        \u003cp style=\"margin: 0; font-size: 14px; line-height: 1.6; color: #555555; max-width: 640px\">Real harvest dates from the grow rooms. Harvest isn't the same as a drop: after it's cut, flower dries and cures for about two weeks before it ships to shops.\u003c/p>\n      \u003c/div>\n      \u003ca href=\"Drops.dc.html\" style=\"font-size: 14px; font-weight: 600\">See what's landing at shops \u2192\u003c/a>\n    \u003c/div>\n    \u003cdiv style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 14px\">\n      \u003csc-for list=\"{{board}}\" as=\"w\" hint-placeholder-count=\"3\">\n        \u003cdiv style=\"{{w.boxStyle}}\">\n          \u003cdiv style=\"display: flex; align-items: baseline; justify-content: space-between; gap: 10px; padding-bottom: 10px; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n            \u003cspan style=\"font-family: 'Bebas Neue', sans-serif; font-size: 26px; letter-spacing: 1.5px; line-height: 1; color: {{w.labelColor}}\">{{w.label}}\u003c/span>\n            \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; text-transform: uppercase; color: #767676\">{{w.date}}\u003c/span>\n          \u003c/div>\n          \u003cdiv style=\"display: flex; flex-direction: column; gap: 8px\">\n            \u003csc-for list=\"{{w.items}}\" as=\"i\" hint-placeholder-count=\"4\">\n              \u003cdiv style=\"display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 15px; font-weight: 600\">\n                \u003cspan>{{i.name}}\u003c/span>\n                \u003cspan style=\"{{i.pill}}\">{{i.type}}\u003c/span>\n              \u003c/div>\n            \u003c/sc-for>\n          \u003c/div>\n        \u003c/div>\n      \u003c/sc-for>\n    \u003c/div>\n  \u003c/section>\n\n  \u003cmain style=\"max-width: 1200px; margin: 0 auto; padding: 36px 24px 64px; display: flex; flex-direction: column; gap: 20px\">\n    \u003cdiv style=\"display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px\">\n      \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 44px; letter-spacing: 3px; line-height: 1\">The lineup\u003c/h2>\n      \u003cdiv role=\"group\" aria-label=\"Filter by type\" style=\"display: flex; flex-wrap: wrap; gap: 6px\">\n        \u003csc-for list=\"{{types}}\" as=\"t\" hint-placeholder-count=\"4\">\n          \u003cbutton onClick=\"{{t.pick}}\" aria-pressed=\"{{t.on}}\" style=\"{{t.style}}\">{{t.label}} \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; opacity: 0.7\">{{t.count}}\u003c/span>\u003c/button>\n        \u003c/sc-for>\n      \u003c/div>\n    \u003c/div>\n\n    \u003cdiv style=\"display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 20px\">\n      \u003csc-for list=\"{{strains}}\" as=\"s\" hint-placeholder-count=\"15\">\n        \u003carticle style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; overflow: hidden; display: flex; flex-direction: column\">\n          \u003cdiv style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.06); padding: 10px\">\n            \u003cimg src=\"{{s.img}}\" alt=\"{{s.name}} strain art\" style=\"{{s.imgStyle}}\">\n          \u003c/div>\n          \u003cdiv style=\"padding: 16px 18px 18px; display: flex; flex-direction: column; gap: 8px; flex: 1\">\n            \u003cdiv style=\"display: flex; align-items: center; justify-content: space-between; gap: 10px\">\n              \u003ch3 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 30px; letter-spacing: 1.5px; line-height: 1\">{{s.name}}\u003c/h3>\n              \u003cspan style=\"{{s.pill}}\">{{s.type}}\u003c/span>\n            \u003c/div>\n            \u003cdiv style=\"font-size: 14px; color: #111111\">\u003cspan style=\"color: #767676\">Genetics\u003c/span> \u00b7 {{s.genetics}}\u003c/div>\n            \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; text-transform: uppercase; color: #767676\">{{s.breeder}}\u003c/div>\n            \u003cdiv style=\"margin-top: auto; padding-top: 10px; border-top: 1px solid rgba(0,0,0,0.06); display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap\">\n              \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; text-transform: uppercase; color: {{s.harvestColor}}\">{{s.harvest}}\u003c/span>\n              \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; text-transform: uppercase; color: #767676\">{{s.countLabel}}\u003c/span>\n            \u003c/div>\n          \u003c/div>\n        \u003c/article>\n      \u003c/sc-for>\n    \u003c/div>\n  \u003c/main>\n\n  \u003csection style=\"background: #111111; color: #FFFFFF\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 56px 24px; display: flex; flex-wrap: wrap; gap: 24px; align-items: center; justify-content: space-between\">\n      \u003cdiv style=\"display: flex; flex-direction: column; gap: 10px; max-width: 640px\">\n        \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #FF9AA8\">Redbird Drops\u003c/div>\n        \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 56px; letter-spacing: 2px; line-height: 0.95\">Found a favorite?\u003c/h2>\n        \u003cp style=\"margin: 0; font-size: 16px; line-height: 1.6; color: #CCCCCC\">Follow it and we'll email you when it lands at a shop near you.\u003c/p>\n      \u003c/div>\n      \u003ca href=\"Drops.dc.html\" style=\"height: 52px; padding: 0 28px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 700; display: flex; align-items: center; text-decoration: none\">Follow strains\u003c/a>\n    \u003c/div>\n  \u003c/section>\n\n  \u003cfooter style=\"background: #111111; color: #A3A3A3; border-top: 1px solid #2A2A2A\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px 36px; display: flex; flex-direction: column; gap: 26px\">\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px; align-items: center; justify-content: space-between\">\n        \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none\">\n          \u003cimg src=\"/_blob/186e35dcb739a15a6a58be91a24ac455\" alt=\"Redbird\" style=\"height: 30px; width: auto; display: block\">\n        \u003c/a>\n        \u003cnav aria-label=\"Footer\" style=\"display: flex; flex-wrap: wrap; gap: 24px; font-size: 14px\">\n          \u003ca href=\"Main.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Home\u003c/a>\n          \u003ca href=\"Flower.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Products\u003c/a>\n          \u003ca href=\"Strains.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Strains\u003c/a>\n          \u003ca href=\"Drops.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Drops\u003c/a>\n          \u003ca href=\"Contact.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Contact\u003c/a>\n          \u003ca href=\"Merch.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Merch\u003cspan style=\"margin-left: 5px; font-size: 11px; color: #8A8A8F\">(soon)\u003c/span>\u003c/a>\n          \u003ca href=\"Retailers.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">For Retailers\u003c/a>\n          \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF; text-decoration: none\">Instagram\u003c/a>\n        \u003c/nav>\n      \u003c/div>\n      \u003cdiv style=\"border-top: 1px solid #2A2A2A; padding-top: 22px; display: flex; flex-direction: column; gap: 12px; font-size: 12px; line-height: 1.7; max-width: 980px\">\n        \u003cp style=\"margin: 0\">Redbird is a Tier 3 Producer/Processor headquartered in Spokane, Washington.\u003c/p>\n        \u003cp style=\"margin: 0\">\u003cstrong style=\"color: #FFFFFF; font-weight: 700\">WARNING:\u003c/strong> This product may be unlawful outside of Washington State. This product has intoxicating effects and may be habit forming. Smoking is hazardous to your health. There may be health risks associated with consumption of this product. Should not be used by women that are pregnant or breast feeding. For use only by adults twenty-one and older. Keep out of reach of children. Marijuana can impair concentration, coordination, and judgment. Do not operate a vehicle or machinery under the influence of this drug.\u003c/p>\n        \u003cp style=\"margin: 0\">Redbird uses the following in the production of its cannabis products: Kaligreen by OAT Agrio Co LTD (approved for use in certified organic agriculture, OMRI listed) and Clonex Rooting Gel by Growth Technology, LTD.\u003c/p>\n        \u003cp style=\"margin: 0; font-family: 'Space Mono', monospace; font-size: 11px; color: #8A8A8A\">\u00a9 2016\u20132026 Redbird\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/footer>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":3500}}'>\nclass Component extends DCLogic {\n  constructor(props) { super(props); this.state = { type: 'All' }; }\n  renderVals() {\n    const st = this.state;\n    const pillBase = 'display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; white-space: nowrap; ';\n    const pill = {\n      Indica: pillBase + 'background: rgba(124,58,237,0.07); border: 1px solid rgba(124,58,237,0.2); color: #6D28D9',\n      Sativa: pillBase + 'background: rgba(180,83,9,0.07); border: 1px solid rgba(180,83,9,0.2); color: #B45309',\n      Hybrid: pillBase + 'background: rgba(22,163,74,0.07); border: 1px solid rgba(22,163,74,0.2); color: #15803D'\n    };\n    const darkPill = { Indica: pillBase + 'background: rgba(167,139,250,0.15); color: #C4B5FD', Sativa: pillBase + 'background: rgba(251,191,36,0.15); color: #FCD34D', Hybrid: pillBase + 'background: rgba(74,222,128,0.15); color: #86EFAC' };\n    const TYPE = __RB_S_TYPE__;\n    // Real data from CRM Master WEB tabs, as of __RB_ASOF__\n    const data = __RB_S_LINEUP__.map((s) => Object.assign({}, s, {\n      pill: pill[s.type] || pill.Hybrid,\n      imgStyle: s.kind === 'label'\n        ? 'width: 100%; aspect-ratio: 846 / 693; object-fit: cover; display: block; border-radius: 6px'\n        : 'width: 100%; aspect-ratio: 846 / 693; object-fit: contain; display: block; border-radius: 6px; background: #FFFFFF'\n    }));\n    const board = __RB_S_BOARD__.map((w) => ({\n      label: w.label, date: w.date, labelColor: w.current ? '#C8102E' : '#111111',\n      boxStyle: 'background: #FFFFFF; border-radius: 12px; padding: 18px 20px; display: flex; flex-direction: column; gap: 12px; ' + (w.current ? 'border: 2px solid #C8102E; box-shadow: 0 1px 4px rgba(0,0,0,0.08)' : 'border: 1px solid rgba(0,0,0,0.08)'),\n      items: w.items.map((n) => ({ name: n, type: TYPE[n] || 'Hybrid', pill: pill[TYPE[n]] || pill.Hybrid }))\n    }));\n    const beta = __RB_S_BETA__.map((b) => Object.assign({}, b, { pill: darkPill[b.type] || darkPill.Hybrid }));\n    const chip = 'height: 38px; padding: 0 14px; border-radius: 8px; font: inherit; font-size: 14px; cursor: pointer; display: flex; align-items: center; gap: 6px; ';\n    const types = ['All', 'Indica', 'Sativa', 'Hybrid'].map((t) => ({\n      label: t, on: st.type === t,\n      count: t === 'All' ? data.length : data.filter((s) => s.type === t).length,\n      pick: () => this.setState({ type: t }),\n      style: chip + (st.type === t ? 'font-weight: 600; border: 1px solid rgba(200,16,46,0.18); background: rgba(200,16,46,0.06); color: #C8102E' : 'font-weight: 500; border: 1px solid rgba(0,0,0,0.08); background: #FFFFFF; color: #555555')\n    }));\n    return { types, board, beta, strains: data.filter((s) => st.type === 'All' || s.type === st.type), total: data.length, thisWeekCount: __RB_S_INFLOWER__ };\n  }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n", "Drops": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird \u2014 Drops\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0;background:#F2F2F4}\na{color:#C8102E}a:hover{color:#9E0B22}\ninput::placeholder{color:#8A8A8A}\n\u003c/style>\n\u003cstyle>\n@media (max-width: 640px) {\n  [style*=\"max-width: 1200px\"] { padding-left: 20px !important; padding-right: 20px !important; }\n  [style*=\"flex: 1 1\"] { flex-basis: 100% !important; min-width: 0 !important; }\n  h1 { font-size: 56px !important; line-height: 0.92 !important; letter-spacing: 1.5px !important; text-wrap: balance; }\n  h2[style*=\"font-size: 72px\"], h2[style*=\"font-size: 56px\"] { font-size: 44px !important; }\n  h2[style*=\"font-size: 48px\"], h2[style*=\"font-size: 44px\"] { font-size: 36px !important; }\n\n  /* header: logo + Find a shop on top, page links in a swipeable row underneath */\n  header > div { gap: 0 10px !important; padding-top: 8px !important; padding-bottom: 8px !important; }\n  header a[aria-label=\"Redbird home\"] img { height: 26px !important; }\n  header a[href=\"Drops.dc.html\"][style*=\"height: 44px\"] { height: 40px !important; padding: 0 14px !important; }\n  header > div > div { margin-left: auto; }\n  header a[aria-label=\"Redbird on Instagram\"] { display: none !important; }\n  /* menu button: tap to show the page links as a list under the header row */\n  header label[for=\"rb-menu\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] { order: 3; flex: 1 1 100% !important; display: none !important; flex-direction: column; gap: 0 !important; margin: 8px -20px -8px; padding: 4px 20px 10px; border-top: 1px solid rgba(0,0,0,0.08); }\n  header #rb-menu:checked ~ nav[aria-label=\"Main\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] > span[aria-hidden=\"true\"] { display: none !important; }\n  header nav[aria-label=\"Main\"] a { display: flex; align-items: center; min-height: 48px; padding: 0 12px !important; margin: 2px 0; font-size: 17px !important; border-radius: 8px; }\n  header nav[aria-label=\"Main\"] a span { margin-left: 8px !important; }\n\n  /* photos */\n  img[style*=\"height: 600px\"], img[style*=\"height: 520px\"] { height: 300px !important; }\n  img[style*=\"height: 210px\"] { height: 130px !important; }\n  [style*=\"min-height: 560px\"], [style*=\"min-height: 460px\"] { min-height: 300px !important; }\n  [style*=\"right: 28px; bottom: 28px\"] { position: static !important; max-width: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n  /* grids */\n  [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { padding: 14px !important; }\n  [style*=\"minmax(160px, 1fr)\"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 6px !important; }\n  [style*=\"minmax(340px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; }\n  [role=\"radiogroup\"][style*=\"minmax(220px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  [role=\"radiogroup\"] button { padding: 14px !important; }\n\n  /* home page strain table becomes stacked rows */\n  [style*=\"min-width: 720px\"] { min-width: 0 !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"][style*=\"text-transform: uppercase\"] { display: none !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] { grid-template-columns: minmax(0, 1fr) auto !important; gap: 4px 12px !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] > :nth-child(n+3) { grid-column: 1 / -1; font-size: 13px; }\n\n  /* strains: hero stats stay on one line each */\n  [style*=\"display: flex; gap: 32px\"] { gap: 20px !important; }\n  [style*=\"font-size: 48px; line-height: 1\"] { font-size: 36px !important; white-space: nowrap; }\n\n  /* drops: tighter shop rows */\n  button[style*=\"min-width: 112px\"] { min-width: 0 !important; padding: 0 12px !important; }\n  form[style*=\"padding: 28px\"] { padding: 20px !important; }\n\n  /* strain label viewer */\n  [role=\"dialog\"] [style*=\"justify-content: space-between\"] { flex-wrap: wrap !important; padding: 12px 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 20px 24px\"] { padding: 10px !important; }\n  [role=\"dialog\"] [style*=\"padding: 18px 24px 22px\"] { padding: 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 24px\"] { padding: 10px !important; }\n}\n\u003c/style>\n\u003cstyle>\n  header { position: sticky !important; top: 0; z-index: 50; }\n  #rb-menu:focus-visible ~ div label[for=\"rb-menu\"] { outline: 2px solid #C8102E; outline-offset: 2px; }\n  @media (max-width: 640px) {\n    /* Products: current strains as a list (name + type, genetics, status) */\n    [style*=\"minmax(260px, 1fr)\"]:has(> a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]),\n    [style*=\"minmax(260px, 1fr)\"]:has(> * > a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]) { grid-template-columns: minmax(0, 1fr) !important; gap: 8px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { display: grid !important; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: \"name tag\" \"gen gen\" \"stat stat\"; align-items: center; gap: 2px 10px !important; padding: 12px 14px !important; border-radius: 10px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) { display: contents !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:first-child { grid-area: tag; justify-self: end; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:last-child { display: none !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(2) { grid-area: name; font-size: 24px !important; min-width: 0; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(3) { grid-area: gen; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(4) { grid-area: stat; margin-top: 4px !important; padding-top: 0 !important; border-top: 0 !important; }\n    /* Beta Bud cards, two across: long names and tags stay inside the card */\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] { padding: 14px !important; min-width: 0; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] div[style*=\"font-size: 30px\"] { font-size: 24px !important; overflow-wrap: anywhere; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] > div[style*=\"justify-content: space-between\"] { flex-wrap: wrap; gap: 6px !important; }\n    /* iPhone zooms into any field under 16px: keep form text at 16px */\n    input, select, textarea { font-size: 16px !important; }\n  }\n  @media (max-width: 340px) { [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; } }\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4\">\n\n  \u003cheader style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 14px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 16px 28px\">\n      \u003cinput type=\"checkbox\" id=\"rb-menu\" aria-label=\"Menu\" style=\"position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none\">\n      \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none; color: #111111\">\n        \u003cimg src=\"/_blob/e3c029787746d07f7ac7aabb57e33d83\" alt=\"Redbird\" style=\"height: 32px; width: auto; display: block\">\n      \u003c/a>\n      \u003cnav aria-label=\"Main\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1\">\n        \u003ca href=\"Flower.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Products\u003c/a>\n        \u003ca href=\"Strains.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 8px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Drops\u003c/a>\n        \u003ca href=\"Contact.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Contact\u003c/a>\n        \u003ca href=\"Merch.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Merch\u003cspan style=\"margin-left: 6px; padding: 2px 5px; border-radius: 4px; background: #F2F2F4; font-family: 'Space Mono', monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: #767676; vertical-align: 2px\">Soon\u003c/span>\u003c/a>\n        \u003cspan aria-hidden=\"true\" style=\"flex: none; width: 1px; height: 22px; background: rgba(0,0,0,0.18); align-self: center; margin: 0 10px\">\u003c/span>\n        \u003ca href=\"Retailers.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">For Retailers\u003c/a>\n      \u003c/nav>\n      \u003cdiv style=\"display: flex; align-items: center; gap: 10px\">\n        \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Redbird on Instagram\" style=\"width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.08); display: flex; align-items: center; justify-content: center; color: #111111\">\n          \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\u003crect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\">\u003c/rect>\u003ccircle cx=\"12\" cy=\"12\" r=\"4\">\u003c/circle>\u003ccircle cx=\"17.5\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\">\u003c/circle>\u003c/svg>\n        \u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n        \u003clabel for=\"rb-menu\" aria-hidden=\"true\" style=\"display: none; width: 40px; height: 40px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.12); align-items: center; justify-content: center; color: #111111; cursor: pointer\">\u003csvg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\u003cline x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\">\u003c/line>\u003cline x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\">\u003c/line>\u003cline x1=\"4\" y1=\"17\" x2=\"20\" y2=\"17\">\u003c/line>\u003c/svg>\u003c/label>\n      \u003c/div>\n    \u003c/div>\n  \u003c/header>\n\n  \u003csection style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px 40px; display: flex; flex-direction: column; gap: 14px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">Redbird Drops\u003c/div>\n      \u003ch1 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 88px; letter-spacing: 2px; line-height: 0.92\">Know when it lands at your shop.\u003c/h1>\n      \u003cp style=\"margin: 0; font-size: 17px; line-height: 1.6; color: #555555; max-width: 640px\">Follow the shops you buy from, the strains you love, or both. We'll email you when fresh Redbird is on the shelf.\u003c/p>\n    \u003c/div>\n  \u003c/section>\n\n  \u003cmain style=\"max-width: 1200px; margin: 0 auto; padding: 32px 24px 56px; display: flex; flex-wrap: wrap; gap: 24px; align-items: flex-start\">\n    \u003cdiv style=\"flex: 999 1 560px; min-width: 0; display: flex; flex-direction: column; gap: 16px\">\n      \u003cdiv role=\"tablist\" aria-label=\"What to follow\" style=\"display: flex; gap: 4px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 10px; padding: 4px; align-self: flex-start\">\n        \u003cbutton role=\"tab\" onClick=\"{{showShops}}\" style=\"{{shopTabStyle}}\">Shops ({{shopCount}} of 5)\u003c/button>\n        \u003cbutton role=\"tab\" onClick=\"{{showStrains}}\" style=\"{{strainTabStyle}}\">Strains ({{strainCount}} of 5)\u003c/button>\n      \u003c/div>\n\n      \u003csc-if value=\"{{isShops}}\" hint-placeholder-val=\"{{ true }}\">\n        \u003cdiv style=\"display: flex; flex-direction: column; gap: 14px\">\n          \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 10px\">\n            \u003clabel style=\"flex: 1 1 320px; display: flex; align-items: center; gap: 10px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 14px; height: 48px\">\n              \u003csvg aria-hidden=\"true\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#555555\" stroke-width=\"2\" stroke-linecap=\"round\">\u003ccircle cx=\"11\" cy=\"11\" r=\"7\">\u003c/circle>\u003cpath d=\"M20 20l-3.5-3.5\">\u003c/path>\u003c/svg>\n              \u003cinput type=\"search\" aria-label=\"Search shops\" placeholder=\"Search shop name, city, or zip\" value=\"{{q}}\" onChange=\"{{onSearch}}\" style=\"border: 0; outline: 0; flex: 1; font: inherit; font-size: 15px; background: transparent; min-width: 0\">\n            \u003c/label>\n            \u003cbutton onClick=\"{{findNear}}\" aria-pressed=\"{{nearOn}}\" style=\"{{nearBtnStyle}}\">\n              \u003csvg aria-hidden=\"true\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"{{nearIcon}}\" stroke-width=\"2\" stroke-linecap=\"round\">\u003cpath d=\"M12 21s-7-6.2-7-11.5A7 7 0 0 1 19 9.5C19 14.8 12 21 12 21z\">\u003c/path>\u003ccircle cx=\"12\" cy=\"9.5\" r=\"2.5\">\u003c/circle>\u003c/svg>\n              {{nearLabel}}\n            \u003c/button>\n          \u003c/div>\n          \u003csc-if value=\"{{nearAsk}}\" hint-placeholder-val=\"{{ false }}\">\n            \u003cdiv style=\"display: flex; flex-wrap: wrap; align-items: center; gap: 10px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 8px; padding: 12px 14px\">\n              \u003cspan style=\"font-size: 14px; color: #555555\">Enter your zip to see the closest shops\u003c/span>\n              \u003cinput type=\"text\" inputmode=\"numeric\" autocomplete=\"postal-code\" maxlength=\"5\" placeholder=\"99203\" aria-label=\"Your zip code\" value=\"{{nearZipIn}}\" onChange=\"{{setNearZip}}\" style=\"height: 40px; width: 110px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 12px; font: inherit; font-size: 15px; background: #F7F7F9\">\n              \u003cbutton onClick=\"{{goNearZip}}\" style=\"height: 40px; padding: 0 16px; border-radius: 8px; border: 0; background: #C8102E; color: #FFFFFF; font: inherit; font-size: 14px; font-weight: 600; cursor: pointer\">Show closest\u003c/button>\n              \u003cspan style=\"{{nearErrStyle}}\">{{nearErr}}\u003c/span>\n            \u003c/div>\n          \u003c/sc-if>\n          \u003csc-if value=\"{{nearBar}}\" hint-placeholder-val=\"{{ false }}\">\n            \u003cdiv style=\"display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; font-size: 14px; color: #555555\">\n              \u003cspan>Showing shops closest to \u003cstrong style=\"color: #111111\">{{nearPlace}}\u003c/strong>\u003c/span>\n              \u003cbutton onClick=\"{{changeZip}}\" style=\"border: 0; background: none; padding: 4px 0; font: inherit; font-size: 14px; font-weight: 600; color: #C8102E; cursor: pointer\">Change zip\u003c/button>\n              \u003cbutton onClick=\"{{useLocation}}\" style=\"{{useLocStyle}}\">Use my location\u003c/button>\n              \u003cbutton onClick=\"{{clearNear}}\" style=\"border: 0; background: none; padding: 4px 0; font: inherit; font-size: 14px; font-weight: 600; color: #555555; cursor: pointer\">Show by county\u003c/button>\n            \u003c/div>\n          \u003c/sc-if>\n          \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 6px\">\n            \u003csc-for list=\"{{counties}}\" as=\"c\" hint-placeholder-count=\"6\">\n              \u003cbutton onClick=\"{{c.pick}}\" style=\"{{c.style}}\">{{c.label}}\u003c/button>\n            \u003c/sc-for>\n          \u003c/div>\n          \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 0.8px; text-transform: uppercase; color: #767676\">{{shopListLabel}}\u003c/div>\n          \u003cdiv style=\"{{capStyle}}\">You're following 5 shops, the most you can. Tap \u2713 Following on one to swap it out.\u003c/div>\n          \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; overflow: hidden\">\n            \u003csc-for list=\"{{shops}}\" as=\"s\" hint-placeholder-count=\"7\">\n              \u003cdiv style=\"display: flex; align-items: center; gap: 14px; padding: 14px 18px; border-bottom: 1px solid rgba(0,0,0,0.06)\">\n                \u003cdiv style=\"flex: 1; min-width: 0\">\n                  \u003cdiv style=\"font-weight: 600; font-size: 15px\">{{s.name}}\u003c/div>\n                  \u003cdiv style=\"font-size: 13px; color: #555555\">{{s.address}} \u00b7 {{s.city}}\u003c/div>\n                  \u003cdiv style=\"margin-top: 4px; font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 0.5px; color: {{s.dropColor}}; text-transform: uppercase\">{{s.miles}}\u003c/div>\n                \u003c/div>\n                \u003cbutton onClick=\"{{s.toggle}}\" aria-pressed=\"{{s.selected}}\" style=\"{{s.btnStyle}}\">{{s.btnLabel}}\u003c/button>\n              \u003c/div>\n            \u003c/sc-for>\n          \u003c/div>\n          \u003cbutton onClick=\"{{toggleAll}}\" style=\"{{moreStyle}}\">{{moreLabel}}\u003c/button>\n          \u003cbutton onClick=\"{{showStrains}}\" style=\"align-self: flex-end; height: 48px; padding: 0 24px; border-radius: 8px; border: 0; background: #111111; color: #FFFFFF; font: inherit; font-size: 14px; font-weight: 600; cursor: pointer\">Add strains \u2192\u003c/button>\n        \u003c/div>\n      \u003c/sc-if>\n\n      \u003csc-if value=\"{{isStrains}}\" hint-placeholder-val=\"{{ false }}\">\n        \u003cdiv style=\"display: flex; flex-direction: column; gap: 14px\">\n          \u003cdiv style=\"display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px\">\n            \u003cdiv style=\"display: flex; gap: 6px\">\n              \u003csc-for list=\"{{types}}\" as=\"t\" hint-placeholder-count=\"4\">\n                \u003cbutton onClick=\"{{t.pick}}\" style=\"{{t.style}}\">{{t.label}}\u003c/button>\n              \u003c/sc-for>\n            \u003c/div>\n            \u003cdiv style=\"font-size: 13px; color: #555555\">Up to 5, optional\u003c/div>\n          \u003c/div>\n          \u003cdiv style=\"{{strainCapStyle}}\">You're following 5 strains, the most you can. Tap \u2713 Following on one to swap it out.\u003c/div>\n          \u003cdiv style=\"columns: 2 330px; column-gap: 0; column-rule: 1px solid rgba(0,0,0,0.06); background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; overflow: hidden\">\n            \u003csc-for list=\"{{strains}}\" as=\"x\" hint-placeholder-count=\"9\">\n              \u003cdiv style=\"{{x.rowStyle}}\">\n                \u003cdiv style=\"flex: 1; min-width: 0\">\n                  \u003cdiv style=\"display: flex; align-items: center; gap: 8px; min-width: 0\">\u003cspan style=\"{{x.nameStyle}}\">{{x.name}}\u003c/span>\u003cspan style=\"{{x.tagStyle}}\">{{x.type}}\u003c/span>\u003c/div>\n                  \u003cdiv style=\"{{x.subStyle}}\">{{x.sub}}\u003c/div>\n                \u003c/div>\n                \u003cbutton onClick=\"{{x.toggle}}\" aria-pressed=\"{{x.selected}}\" aria-label=\"Follow {{x.name}}\" style=\"{{x.btnStyle}}\">{{x.btnLabel}}\u003c/button>\n              \u003c/div>\n            \u003c/sc-for>\n          \u003c/div>\n        \u003c/div>\n      \u003c/sc-if>\n    \u003c/div>\n\n    \u003caside aria-label=\"Your alerts\" style=\"position: relative; flex: 1 1 340px; min-width: 0; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; box-shadow: 0 1px 4px rgba(0,0,0,0.08); overflow: hidden\">\n      \u003cdiv style=\"background: #111111; color: #FFFFFF; padding: 18px 22px\">\n        \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #FF9AA8\">Your alerts\u003c/div>\n        \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 32px; letter-spacing: 1.5px; line-height: 1.05; margin-top: 4px\">{{shopCount}} shops \u00b7 {{strainCount}} strains\u003c/div>\n      \u003c/div>\n      \u003cdiv style=\"padding: 20px 22px; display: flex; flex-direction: column; gap: 16px\">\n        \u003cdiv style=\"display: flex; flex-direction: column; gap: 8px\">\n          \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">Shops\u003c/div>\n          \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 6px\">\n            \u003csc-for list=\"{{pickedShops}}\" as=\"p\" hint-placeholder-count=\"2\">\n              \u003cbutton onClick=\"{{p.toggle}}\" aria-label=\"Remove {{p.name}}\" style=\"padding: 5px 10px; border-radius: 999px; border: 1px solid rgba(0,0,0,0.08); background: #F7F7F9; font: inherit; font-size: 12px; font-weight: 600; cursor: pointer\">{{p.name}} \u2715\u003c/button>\n            \u003c/sc-for>\n          \u003c/div>\n          \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676; margin-top: 4px\">Strains\u003c/div>\n          \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 6px\">\n            \u003csc-for list=\"{{pickedStrains}}\" as=\"p\" hint-placeholder-count=\"2\">\n              \u003cbutton onClick=\"{{p.toggle}}\" aria-label=\"Remove {{p.name}}\" style=\"padding: 5px 10px; border-radius: 999px; border: 1px solid rgba(200,16,46,0.18); background: rgba(200,16,46,0.06); color: #C8102E; font: inherit; font-size: 12px; font-weight: 600; cursor: pointer\">{{p.name}} \u2715\u003c/button>\n            \u003c/sc-for>\n          \u003c/div>\n        \u003c/div>\n        \u003csc-if value=\"{{viewForm}}\" hint-placeholder-val=\"{{ true }}\">\n        \u003cdiv style=\"display: flex; flex-direction: column; gap: 16px\">\n        \u003csc-if value=\"{{isManage}}\" hint-placeholder-val=\"{{ false }}\">\n          \u003cdiv style=\"font-size: 13px; line-height: 1.5; color: #555555; background: #F7F7F9; border-radius: 8px; padding: 10px 12px\">Managing alerts for \u003cb>{{manageEmail}}\u003c/b>. Change anything, then save.\u003c/div>\n        \u003c/sc-if>\n        \u003cfieldset style=\"border: 0; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px\">\n          \u003clegend style=\"font-family: 'Space Mono', monospace; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676; margin-bottom: 8px; padding: 0\">What do you buy?\u003c/legend>\n          \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 6px\">\n            \u003cbutton type=\"button\" onClick=\"{{tFlower}}\" aria-pressed=\"{{onFlower}}\" style=\"{{styFlower}}\">{{lblFlower}}\u003c/button>\n            \u003cbutton type=\"button\" onClick=\"{{tMicro}}\" aria-pressed=\"{{onMicro}}\" style=\"{{styMicro}}\">{{lblMicro}}\u003c/button>\n            \u003cbutton type=\"button\" onClick=\"{{tPreroll}}\" aria-pressed=\"{{onPreroll}}\" style=\"{{styPreroll}}\">{{lblPreroll}}\u003c/button>\n          \u003c/div>\n          \u003cdiv style=\"font-size: 12px; line-height: 1.45; color: #767676\">We'll only email you about these. Beta Bud counts in all three.\u003c/div>\n        \u003c/fieldset>\n        \u003cdiv style=\"{{howStyle}}\">{{howText}}\u003c/div>\n        \u003csc-if value=\"{{isNew}}\" hint-placeholder-val=\"{{ true }}\">\n          \u003clabel style=\"display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">Email\n            \u003cinput type=\"email\" autocomplete=\"email\" placeholder=\"you@email.com\" value=\"{{fEmail}}\" onChange=\"{{setEmail}}\" style=\"height: 44px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 12px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9\">\n          \u003c/label>\n        \u003c/sc-if>\n        \u003clabel style=\"display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">First name\n          \u003cinput type=\"text\" autocomplete=\"given-name\" value=\"{{fFirst}}\" onChange=\"{{setFirst}}\" style=\"height: 44px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 12px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9\">\n        \u003c/label>\n        \u003clabel style=\"display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">Zip code \u003cspan style=\"{{zipNoteStyle}}\">{{zipNote}}\u003c/span>\n          \u003cinput type=\"text\" inputmode=\"numeric\" autocomplete=\"postal-code\" maxlength=\"5\" placeholder=\"99203\" value=\"{{fZip}}\" onChange=\"{{setZip}}\" style=\"height: 44px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 12px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9; width: 140px\">\n        \u003c/label>\n        \u003csc-if value=\"{{isNew}}\" hint-placeholder-val=\"{{ true }}\">\n          \u003cfieldset style=\"border: 0; margin: 0; padding: 0\">\n            \u003clegend style=\"font-size: 13px; font-weight: 600; padding: 0; margin-bottom: 6px\">Birthdate\u003c/legend>\n            \u003cdiv style=\"display: flex; gap: 8px\">\n              \u003cinput type=\"text\" inputmode=\"numeric\" maxlength=\"2\" aria-label=\"Birth month\" placeholder=\"MM\" value=\"{{fM}}\" onChange=\"{{setM}}\" style=\"width: 64px; height: 44px; box-sizing: border-box; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; text-align: center; font: inherit; font-size: 15px; background: #F7F7F9\">\n              \u003cinput type=\"text\" inputmode=\"numeric\" maxlength=\"2\" aria-label=\"Birth day\" placeholder=\"DD\" value=\"{{fD}}\" onChange=\"{{setD}}\" style=\"width: 64px; height: 44px; box-sizing: border-box; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; text-align: center; font: inherit; font-size: 15px; background: #F7F7F9\">\n              \u003cinput type=\"text\" inputmode=\"numeric\" maxlength=\"4\" aria-label=\"Birth year\" placeholder=\"YYYY\" value=\"{{fY}}\" onChange=\"{{setY}}\" style=\"width: 92px; height: 44px; box-sizing: border-box; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; text-align: center; font: inherit; font-size: 15px; background: #F7F7F9\">\n            \u003c/div>\n          \u003c/fieldset>\n          \u003clabel style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 12px; color: #555555; line-height: 1.5\">\u003cinput type=\"checkbox\" checked=\"{{agree}}\" onChange=\"{{toggleAgree}}\" style=\"margin-top: 2px; accent-color: #C8102E\"> I'm 21 or older and agree to get drop emails from Redbird. Unsubscribe anytime.\u003c/label>\n        \u003c/sc-if>\n        \u003cinput type=\"text\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" aria-hidden=\"true\" value=\"{{fHp}}\" onChange=\"{{setHp}}\" style=\"position: absolute; left: -9999px; width: 1px; height: 1px; opacity: 0\">\n        \u003cdiv role=\"alert\" style=\"{{errStyle}}\">{{formError}}\u003c/div>\n        \u003cbutton onClick=\"{{submit}}\" style=\"height: 50px; border-radius: 8px; border: 0; background: #C8102E; color: #FFFFFF; font: inherit; font-size: 15px; font-weight: 700; cursor: pointer\">{{submitLabel}}\u003c/button>\n        \u003csc-if value=\"{{isNew}}\" hint-placeholder-val=\"{{ true }}\">\n          \u003cbutton onClick=\"{{openLink}}\" style=\"border: 0; background: none; padding: 4px; font: inherit; font-size: 13px; color: #C8102E; text-decoration: underline; cursor: pointer; align-self: center\">Already following? Get your manage link\u003c/button>\n        \u003c/sc-if>\n        \u003csc-if value=\"{{isManage}}\" hint-placeholder-val=\"{{ false }}\">\n          \u003cbutton onClick=\"{{unsubscribe}}\" style=\"border: 0; background: none; padding: 4px; font: inherit; font-size: 13px; color: #C8102E; text-decoration: underline; cursor: pointer; align-self: center; color: #767676\">Unsubscribe from all drop alerts\u003c/button>\n        \u003c/sc-if>\n        \u003c/div>\n        \u003c/sc-if>\n        \u003csc-if value=\"{{viewLink}}\" hint-placeholder-val=\"{{ false }}\">\n          \u003cdiv style=\"display: flex; flex-direction: column; gap: 14px\">\n            \u003cdiv style=\"font-size: 15px; line-height: 1.5; color: #333333\">Enter the email you signed up with and we'll send you a link to change your alerts.\u003c/div>\n            \u003cinput type=\"email\" autocomplete=\"email\" placeholder=\"you@email.com\" value=\"{{lEmail}}\" onChange=\"{{setLEmail}}\" style=\"height: 44px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 12px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9\">\n            \u003cdiv role=\"alert\" style=\"{{errStyle}}\">{{formError}}\u003c/div>\n            \u003cbutton onClick=\"{{sendLink}}\" style=\"height: 50px; border-radius: 8px; border: 0; background: #C8102E; color: #FFFFFF; font: inherit; font-size: 15px; font-weight: 700; cursor: pointer\">{{linkLabel}}\u003c/button>\n            \u003cbutton onClick=\"{{backToForm}}\" style=\"border: 0; background: none; padding: 4px; font: inherit; font-size: 13px; color: #C8102E; text-decoration: underline; cursor: pointer; align-self: center\">Back\u003c/button>\n          \u003c/div>\n        \u003c/sc-if>\n        \u003csc-if value=\"{{viewDone}}\" hint-placeholder-val=\"{{ false }}\">\n          \u003cdiv style=\"display: flex; flex-direction: column; gap: 12px; padding: 6px 0 4px\">\n            \u003cdiv style=\"width: 52px; height: 52px; border-radius: 999px; background: rgba(200,16,46,0.08); color: #C8102E; display: flex; align-items: center; justify-content: center; font-size: 26px; font-weight: 700\">\u2713\u003c/div>\n            \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 36px; letter-spacing: 1.5px; line-height: 1\">{{doneTitle}}\u003c/div>\n            \u003cdiv style=\"font-size: 15px; line-height: 1.55; color: #555555\">{{doneText}}\u003c/div>\n            \u003cbutton onClick=\"{{backToForm}}\" style=\"border: 0; background: none; padding: 4px; font: inherit; font-size: 13px; color: #C8102E; text-decoration: underline; cursor: pointer; align-self: center; align-self: flex-start; padding-left: 0\">{{backLabel}}\u003c/button>\n          \u003c/div>\n        \u003c/sc-if>\n      \u003c/div>\n    \u003c/aside>\n  \u003c/main>\n\n  \u003cfooter style=\"background: #111111; color: #A3A3A3\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px 36px; display: flex; flex-direction: column; gap: 26px\">\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px; align-items: center; justify-content: space-between\">\n        \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none\">\n          \u003cimg src=\"/_blob/186e35dcb739a15a6a58be91a24ac455\" alt=\"Redbird\" style=\"height: 30px; width: auto; display: block\">\n        \u003c/a>\n        \u003cnav aria-label=\"Footer\" style=\"display: flex; flex-wrap: wrap; gap: 24px; font-size: 14px\">\n          \u003ca href=\"Main.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Home\u003c/a>\n          \u003ca href=\"Flower.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Products\u003c/a>\n          \u003ca href=\"Strains.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Strains\u003c/a>\n          \u003ca href=\"Drops.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Drops\u003c/a>\n          \u003ca href=\"Contact.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Contact\u003c/a>\n          \u003ca href=\"Merch.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Merch\u003cspan style=\"margin-left: 5px; font-size: 11px; color: #8A8A8F\">(soon)\u003c/span>\u003c/a>\n          \u003ca href=\"Retailers.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">For Retailers\u003c/a>\n          \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF; text-decoration: none\">Instagram\u003c/a>\n        \u003c/nav>\n      \u003c/div>\n      \u003cdiv style=\"border-top: 1px solid #2A2A2A; padding-top: 22px; display: flex; flex-direction: column; gap: 12px; font-size: 12px; line-height: 1.7; max-width: 980px\">\n        \u003cp style=\"margin: 0\">Redbird is a Tier 3 Producer/Processor headquartered in Spokane, Washington.\u003c/p>\n        \u003cp style=\"margin: 0\">\u003cstrong style=\"color: #FFFFFF; font-weight: 700\">WARNING:\u003c/strong> This product may be unlawful outside of Washington State. This product has intoxicating effects and may be habit forming. Smoking is hazardous to your health. There may be health risks associated with consumption of this product. Should not be used by women that are pregnant or breast feeding. For use only by adults twenty-one and older. Keep out of reach of children. Marijuana can impair concentration, coordination, and judgment. Do not operate a vehicle or machinery under the influence of this drug.\u003c/p>\n        \u003cp style=\"margin: 0\">Redbird uses the following in the production of its cannabis products: Kaligreen by OAT Agrio Co LTD (approved for use in certified organic agriculture, OMRI listed) and Clonex Rooting Gel by Growth Technology, LTD.\u003c/p>\n        \u003cp style=\"margin: 0; font-family: 'Space Mono', monospace; font-size: 11px; color: #8A8A8A\">\u00a9 2016\u20132026 Redbird\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/footer>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":2200}}'>\nclass Component extends DCLogic {\n  constructor(props) {\n    super(props);\n    const M = (window.parent && window.parent.RB_MANAGE) || window.RB_MANAGE || null;\n    const on = (list) => (list || []).reduce((o, k) => { o[k] = true; return o; }, {});\n    this.M = M; this.t0 = Date.now();\n    this.state = { tab: 'shops', type: 'All', county: __RB_D_COUNTY0__, shops: M ? on(M.shopIds) : {}, strains: M ? on(M.strains) : {},\n      types: on((M && M.products && M.products.length) ? M.products : ['flower', 'micro', 'preroll']), fEmail: '', fFirst: (M && M.first) || '', fZip: (M && M.zip) ? String(M.zip) : '',\n      fM: '', fD: '', fY: '', agree: false, fHp: '', lEmail: '', busy: false, formError: '', view: 'form', doneTitle: '', doneText: '', near: null, nearBusy: false, nearAsk: false, nearZipIn: '', nearErr: '' };\n  }\n  renderVals() {\n    const st = this.state;\n    const pillBase = 'display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; ';\n    const pill = {\n      Indica: pillBase + 'background: rgba(124,58,237,0.07); border: 1px solid rgba(124,58,237,0.2); color: #6D28D9',\n      Sativa: pillBase + 'background: rgba(180,83,9,0.07); border: 1px solid rgba(180,83,9,0.2); color: #B45309',\n      Hybrid: pillBase + 'background: rgba(22,163,74,0.07); border: 1px solid rgba(22,163,74,0.2); color: #15803D'\n    };\n    const shopData = __RB_D_SHOPS__;\n    const strainData = __RB_D_STRAINS__;\n    const chip = 'height: 36px; padding: 0 14px; border-radius: 8px; font: inherit; font-size: 13px; cursor: pointer; ';\n    const chipOn = chip + 'font-weight: 600; border: 1px solid rgba(200,16,46,0.18); background: rgba(200,16,46,0.06); color: #C8102E';\n    const chipOff = chip + 'font-weight: 500; border: 1px solid rgba(0,0,0,0.08); background: #FFFFFF; color: #555555';\n    const tab = 'height: 40px; padding: 0 16px; border-radius: 8px; font: inherit; font-size: 14px; cursor: pointer; ';\n    const tabOn = tab + 'font-weight: 600; border: 1px solid rgba(200,16,46,0.18); background: rgba(200,16,46,0.06); color: #C8102E';\n    const tabOff = tab + 'font-weight: 500; border: 1px solid transparent; background: transparent; color: #555555';\n    const MAX_SHOPS = 5, nFollowed = Object.keys(st.shops).filter((k) => st.shops[k]).length, atCap = nFollowed >= MAX_SHOPS;\n    const toggleShop = (id) => () => { if (!st.shops[id] && atCap) return; this.setState({ shops: Object.assign({}, st.shops, { [id]: !st.shops[id] }), formError: '' }); };\n    const MAX_STRAINS = 5, strainCap = Object.keys(st.strains).filter((k) => st.strains[k]).length >= MAX_STRAINS;\n    const toggleStrain = (id) => () => { if (!st.strains[id] && strainCap) return; this.setState({ strains: Object.assign({}, st.strains, { [id]: !st.strains[id] }), formError: '' }); };\n    const q = (st.q || '').trim().toLowerCase();\n    const Z = (window.parent && window.parent.RB_ZIPS) || window.RB_ZIPS || {};\n    const near = st.near;\n    const C = (window.parent && window.parent.RB_CITIES) || window.RB_CITIES || {};   // shops with no zip: use their city\n    const milesTo = (s) => { const b = Z[String(s.zip || '').slice(0, 5)] || C[String(s.city || '').toLowerCase().replace(/[^a-z]/g, '')]; if (!near || !b) return null;\n      const r = (x) => x * Math.PI / 180, dLat = r(b[0] - near.lat), dLon = r(b[1] - near.lng);\n      const h = Math.sin(dLat / 2) ** 2 + Math.cos(r(near.lat)) * Math.cos(r(b[0])) * Math.sin(dLon / 2) ** 2;\n      return 2 * 3958.8 * Math.asin(Math.sqrt(h)); };\n    const shopsAll = q ? shopData.filter((s) => (s.name + ' ' + s.address + ' ' + s.city + ' ' + s.zip).toLowerCase().indexOf(q) >= 0)\n      : near ? shopData.map((s) => Object.assign({}, s, { dist: milesTo(s) })).sort((a, b) => (a.dist === null ? 1e9 : a.dist) - (b.dist === null ? 1e9 : b.dist))\n      : shopData.filter((s) => st.county === 'All counties' || s.county === st.county);\n    const shops = (st.showAll ? shopsAll : shopsAll.slice(0, 7)).map((s) => {\n      const on = !!st.shops[s.id];\n      return Object.assign({}, s, {\n        initial: s.name.replace(/^The /, '').charAt(0), selected: on, toggle: toggleShop(s.id),\n        miles: (s.dist != null ? (s.dist \u003c 1 ? 'Under 1 mi' : Math.round(s.dist) + ' mi') + (s.miles ? ' \u00b7 ' + s.miles : '') : s.miles),\n        btnLabel: on ? '\u2713 Following' : atCap ? 'Limit reached' : '+ Follow',\n        btnStyle: (!on && atCap ? 'opacity: 0.45; cursor: not-allowed; ' : '') + 'height: 40px; min-width: 112px; padding: 0 14px; border-radius: 8px; font: inherit; font-size: 13px; font-weight: 600; cursor: pointer; flex: none; ' + (on ? 'border: 1px solid #C8102E; background: #C8102E; color: #FFFFFF' : 'border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111')\n      });\n    });\n    const strains = strainData.filter((x) => st.type === 'All' || x.beta || x.type === st.type).map((x) => {\n      const on = !!st.strains[x.id];\n      return Object.assign({}, x, {\n        selected: on, toggle: toggleStrain(x.id), pill: pill[x.type], genColor: '#555555',\n        fill: on ? '#C8102E' : 'none', stroke: on ? '#C8102E' : '#767676',\n        heartBtn: 'width: 40px; height: 40px; margin: -8px -8px 0 0; border-radius: 8px; border: 0; background: ' + (on ? 'rgba(200,16,46,0.06)' : 'transparent') + '; display: flex; align-items: center; justify-content: center; cursor: pointer',\n        cardStyle: 'background: #FFFFFF; border-radius: 12px; padding: 16px; display: flex; flex-direction: column; gap: 8px; ' + (on ? 'border: 2px solid #C8102E' : 'border: 1px solid rgba(0,0,0,0.08)'),\n        dropColor: (x.drop.indexOf('Landing') === 0 || x.drop.indexOf('Next') === 0) ? '#C8102E' : '#767676'\n      });\n    }).map((x) => !x.beta ? x : Object.assign(x, {\n      pill: 'display: inline-block; padding: 3px 10px; border-radius: 4px; font-family: \\'Space Mono\\', monospace; font-size: 11px; letter-spacing: 1px; text-transform: uppercase; background: #C8102E; color: #FFFFFF',\n      cardStyle: 'background: #111111; color: #FFFFFF; border-radius: 12px; padding: 16px; display: flex; flex-direction: column; gap: 8px; ' + (x.selected ? 'border: 2px solid #C8102E' : 'border: 1px solid #111111'),\n      dropColor: '#FF9AA8', genColor: '#C9C9CE', stroke: x.selected ? '#C8102E' : '#A3A3A8',\n      heartBtn: 'width: 40px; height: 40px; margin: -8px -8px 0 0; border-radius: 8px; border: 0; background: ' + (x.selected ? 'rgba(200,16,46,0.25)' : 'transparent') + '; display: flex; align-items: center; justify-content: center; cursor: pointer'\n    }));\n    const TAG = { Sativa: ['#FFF4EC', '#B4530A'], Indica: ['#F3EEFF', '#6B3FD1'], Hybrid: ['#EDF7EF', '#2E7D3E'], Beta: ['#C8102E', '#FFFFFF'] };\n    strains.forEach((x) => {\n      const on = x.selected, dark = !!x.beta, tg = TAG[x.type] || ['#F2F2F4', '#555555'];\n      Object.assign(x, {\n        rowStyle: 'display: flex; align-items: center; gap: 12px; padding: 11px 16px; border-bottom: 1px solid ' + (dark ? '#111111' : 'rgba(0,0,0,0.06)') + '; break-inside: avoid; ' +\n          (dark ? 'background: #111111; color: #FFFFFF' : on ? 'background: rgba(200,16,46,0.03)' : 'background: #FFFFFF'),\n        nameStyle: 'font-size: 15px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: ' + (on && !dark ? '#C8102E' : 'inherit'),\n        tagStyle: 'flex: none; font-size: 11px; font-weight: 700; padding: 2px 7px; border-radius: 4px; background: ' + tg[0] + '; color: ' + tg[1] + (dark ? '; letter-spacing: 1px; text-transform: uppercase; font-size: 10px' : ''),\n        sub: dark ? 'Every new genetic we test \u00b7 ' + x.drop.replace(/ new strains? in the works/, ' in the works') : x.drop,\n        subStyle: 'font-size: 12px; margin-top: 3px; ' + (dark ? 'line-height: 1.35; ' : 'white-space: nowrap; overflow: hidden; text-overflow: ellipsis; ') + 'color: ' + (dark ? '#C9C9CE' : /^Headed|^Landing/.test(x.drop) ? '#555555' : '#A0A0A6'),\n        btnLabel: on ? '\u2713 Following' : strainCap ? 'Limit reached' : '+ Follow',\n        btnStyle: 'flex: none; height: 36px; min-width: 104px; padding: 0 12px; border-radius: 8px; font: inherit; font-size: 13px; font-weight: 600; cursor: pointer; ' +\n          (on ? 'border: 1px solid #C8102E; background: #C8102E; color: #FFFFFF' : dark ? 'border: 1px solid rgba(255,255,255,0.35); background: transparent; color: #FFFFFF' : 'border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111') +\n          (!on && strainCap ? '; opacity: 0.45; cursor: not-allowed' : '')\n      });\n    });\n    const counties = __RB_D_COUNTIES__.map((c) => ({ label: c, style: (!q && !near && st.county === c) ? chipOn : chipOff, pick: () => this.setState({ county: c, q: '', showAll: false, near: null, nearAsk: false }) }));\n    const types = ['All', 'Indica', 'Sativa', 'Hybrid'].map((t) => ({ label: t, style: st.type === t ? chipOn : chipOff, pick: () => this.setState({ type: t }) }));\n    const pickedShops = shopData.filter((s) => st.shops[s.id]).map((s) => ({ name: s.name, toggle: toggleShop(s.id) }));\n    const pickedStrains = strainData.filter((x) => st.strains[x.id]).map((x) => ({ name: x.name, toggle: toggleStrain(x.id) }));\n    const M = this.M, api = (window.parent && window.parent.RB_API) || window.RB_API;\n    const set = (k) => (e) => this.setState({ [k]: e.target.value });\n    const digits = (k, n) => (e) => this.setState({ [k]: String(e.target.value || '').replace(/\\D/g, '').slice(0, n) });\n    const offline = 'We couldn\\'t reach Redbird. Check your connection and try again.';\n    const finish = (title, back) => (r) => (r && r.ok) ? this.setState({ busy: false, view: 'done', doneTitle: title, doneText: r.message, backLabel: back })\n                                                   : this.setState({ busy: false, formError: (r && r.error) || 'Something went wrong. Please try again.' });\n    const nShops = Object.keys(st.shops).filter((k) => st.shops[k]).length, nStrains = Object.keys(st.strains).filter((k) => st.strains[k]).length;\n    // What do you buy? Flower / Micro Buds / Pre-rolls (all on by default)\n    const TYPES = { flower: 'Flower', micro: 'Micro Buds', preroll: 'Pre-rolls' };\n    const typeOn = (k) => !!(st.types || {})[k];\n    const typeChip = (k) => 'height: 38px; padding: 0 11px; border-radius: 999px; font: inherit; font-size: 13px; font-weight: 600; white-space: nowrap; cursor: pointer; ' +\n      (typeOn(k) ? 'border: 1px solid #C8102E; background: rgba(200,16,46,0.06); color: #C8102E' : 'border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111');\n    const tType = (k) => () => this.setState({ types: Object.assign({}, st.types, { [k]: !typeOn(k) }), formError: '' });\n    // How strain alerts work for their zip: shops within 25 miles, or their 3 closest up to 50 miles\n    const ZZ = (window.parent && window.parent.RB_ZIPS) || window.RB_ZIPS || {}, CC = (window.parent && window.parent.RB_CITIES) || window.RB_CITIES || {};\n    const zip5 = (st.fZip || '').trim(), home = /^\\d{5}$/.test(zip5) ? ZZ[zip5] : null;\n    let howText = '';\n    if (nStrains) {\n      if (!home) howText = 'Strain alerts cover shops within 25 miles of your zip (or your 3 closest, up to 50 miles).';\n      else {\n        const r = (x) => x * Math.PI / 180;\n        const dist = (b) => { const h = Math.sin(r(b[0] - home[0]) / 2) ** 2 + Math.cos(r(home[0])) * Math.cos(r(b[0])) * Math.sin(r(b[1] - home[1]) / 2) ** 2; return 2 * 3958.8 * Math.asin(Math.sqrt(h)); };\n        const list = (typeof shopData !== 'undefined' ? shopData : []).map((x) => { const b = ZZ[String(x.zip || '').slice(0, 5)] || CC[String(x.city || '').toLowerCase().replace(/[^a-z]/g, '')]; return b ? dist(b) : null; })\n          .filter((d) => d !== null && d \u003c= 50).sort((a, b) => a - b);\n        const n25 = Math.min(10, list.filter((d) => d \u003c= 25).length);   // your 10 closest within 25 miles\n        howText = n25 >= 3 ? 'Strain alerts: your ' + n25 + ' closest shops to ' + zip5 + ', all within ' + Math.max(1, Math.ceil(list[n25 - 1])) + ' miles.'\n                : list.length ? 'Few shops within 25 miles of ' + zip5 + ', so strain alerts use your ' + Math.min(3, list.length) + ' closest (up to ' + Math.round(list[Math.min(3, list.length) - 1]) + ' miles away).'\n                : 'No shops within 50 miles of ' + zip5 + ' yet, so strain alerts won\\'t have anything for now.';\n      }\n      if (nShops) howText += ' Emails about your shops will only list your strains.';\n    }\n    const submit = () => {\n      if (st.busy) return;\n      const shopIds = Object.keys(st.shops).filter((k) => st.shops[k]), strainNames = Object.keys(st.strains).filter((k) => st.strains[k]);\n      let err = '', dob = '';\n      const types = Object.keys(TYPES).filter(typeOn);\n      if (!shopIds.length && !strainNames.length) err = 'Pick at least one shop or strain to follow.';\n      else if (shopIds.length > 5) err = 'You can follow up to 5 shops. Remove one to add another.';\n      else if (strainNames.length > 5) err = 'You can follow up to 5 strains. Remove one to add another.';\n      else if (!types.length) err = 'Pick at least one: Flower, Micro Buds or Pre-rolls.';\n      else if (!M && !/^[^\\s@]+@[^\\s@]+\\.[a-z]{2,}$/i.test(st.fEmail.trim())) err = 'Please enter a valid email address.';\n      else if (!/^\\d{5}$/.test(st.fZip.trim())) err = st.fZip.trim() ? 'Zip code should be 5 digits.' : 'Please add your zip code.';\n      if (!err && !M) {\n        const mm = +st.fM, dd = +st.fD, yy = +st.fY, b = new Date(yy, mm - 1, dd), n = new Date();\n        if (st.fY.length !== 4 || b.getMonth() !== mm - 1 || b.getDate() !== dd || b > n || yy \u003c 1900) err = 'Please enter your birthday (MM / DD / YYYY).';\n        else if (n.getFullYear() - yy - ((n.getMonth() \u003c mm - 1 || (n.getMonth() === mm - 1 && n.getDate() \u003c dd)) ? 1 : 0) \u003c 21) err = 'Sorry, you must be 21 or older to sign up.';\n        else if (!st.agree) err = 'Please check the box to confirm you\\'re 21+ and want drop emails.';\n        dob = yy + '-' + String(mm).padStart(2, '0') + '-' + String(dd).padStart(2, '0');\n      }\n      if (err) return this.setState({ formError: err });\n      if (!api) return this.setState({ formError: 'Sign-ups aren\\'t connected in this preview.' });\n      this.setState({ busy: true, formError: '' });\n      const req = M ? { action: 'update', t: M.token, zip: st.fZip.trim(), first: st.fFirst.trim(), shops: shopIds, strains: strainNames, products: types }\n                    : { action: 'signup', email: st.fEmail.trim(), first: st.fFirst.trim(), zip: st.fZip.trim(), shops: shopIds, strains: strainNames, products: types, dob: dob, hp: st.fHp, ms: Date.now() - this.t0 };\n      api(req).then(finish(M ? 'Saved' : 'Check your email', M ? 'Keep editing' : 'Back')).catch(() => this.setState({ busy: false, formError: offline }));\n    };\n    const sendLink = () => {\n      if (st.busy) return;\n      if (!/^[^\\s@]+@[^\\s@]+\\.[a-z]{2,}$/i.test(st.lEmail.trim())) return this.setState({ formError: 'Please enter a valid email address.' });\n      if (!api) return this.setState({ formError: 'Sign-ups aren\\'t connected in this preview.' });\n      this.setState({ busy: true, formError: '' });\n      api({ action: 'link', email: st.lEmail.trim(), hp: st.fHp }).then(finish('Check your email', 'Back')).catch(() => this.setState({ busy: false, formError: offline }));\n    };\n    const unsubscribe = () => {\n      if (st.busy || !api || !M) return;\n      this.setState({ busy: true, formError: '' });\n      api({ action: 'unsub', t: M.token }).then(finish('Unsubscribed', 'Changed your mind? Save your alerts again')).catch(() => this.setState({ busy: false, formError: offline }));\n    };\n    const formVals = {\n      viewForm: st.view === 'form', viewLink: st.view === 'link', viewDone: st.view === 'done', isManage: !!M, isNew: !M, manageEmail: M ? M.email : '',\n      onFlower: typeOn('flower'), onMicro: typeOn('micro'), onPreroll: typeOn('preroll'),\n      styFlower: typeChip('flower'), styMicro: typeChip('micro'), styPreroll: typeChip('preroll'),\n      lblFlower: (typeOn('flower') ? '\u2713 ' : '') + 'Flower', lblMicro: (typeOn('micro') ? '\u2713 ' : '') + 'Micro Buds', lblPreroll: (typeOn('preroll') ? '\u2713 ' : '') + 'Pre-rolls',\n      tFlower: tType('flower'), tMicro: tType('micro'), tPreroll: tType('preroll'),\n      howText, howStyle: howText ? 'font-size: 12px; line-height: 1.5; color: #555555; background: #F7F7F9; border-radius: 8px; padding: 10px 12px' : 'display: none',\n      zipNote: 'So we can show you the shops near you.',\n      zipNoteStyle: 'font-weight: 400; color: #767676',\n      fEmail: st.fEmail, fFirst: st.fFirst, fZip: st.fZip, fM: st.fM, fD: st.fD, fY: st.fY, fHp: st.fHp, lEmail: st.lEmail, agree: st.agree,\n      setEmail: set('fEmail'), setFirst: set('fFirst'), setZip: digits('fZip', 5), setM: digits('fM', 2), setD: digits('fD', 2), setY: digits('fY', 4), setHp: set('fHp'), setLEmail: set('lEmail'),\n      toggleAgree: () => this.setState({ agree: !st.agree }),\n      errStyle: st.formError ? 'font-size: 14px; font-weight: 600; color: #C8102E; line-height: 1.4' : 'display: none',\n      formError: st.formError, submit, sendLink, unsubscribe,\n      submitLabel: st.busy ? 'Sending\u2026' : (M ? 'Save changes' : 'Turn on alerts'), linkLabel: st.busy ? 'Sending\u2026' : 'Email me my link',\n      openLink: () => this.setState({ view: 'link', formError: '' }), backToForm: () => this.setState({ view: 'form', formError: '' }),\n      doneTitle: st.doneTitle, doneText: st.doneText, backLabel: st.backLabel || 'Back'\n    };\n    const useZip = (z) => { const p = Z[z]; if (!p) return false;\n      this.setState({ near: { lat: p[0], lng: p[1], label: z }, nearAsk: false, nearErr: '', showAll: false, q: '', fZip: st.fZip || z }); return true; };\n    const findNear = () => {\n      if (st.nearBusy) return;\n      if (st.near) return this.setState({ near: null, nearAsk: false, nearErr: '' });   // tap again = back to counties\n      if (useZip((st.fZip || '').trim())) return;                                    // they already typed a zip in the form\n      locate();\n    };\n    const locate = () => {                                                            // phone/browser location; if refused, ask for a zip\n      if (!navigator.geolocation) return this.setState({ nearAsk: true, nearZipIn: '' });\n      this.setState({ nearBusy: true });\n      navigator.geolocation.getCurrentPosition(\n        (p) => this.setState({ nearBusy: false, nearAsk: false, nearErr: '', showAll: false, q: '', near: { lat: p.coords.latitude, lng: p.coords.longitude, label: 'you' } }),\n        () => this.setState({ nearBusy: false, nearAsk: true, nearErr: st.near ? 'We could not get your location. Enter a zip instead.' : '' }),\n        { timeout: 8000, maximumAge: 600000 });\n    };\n    const nearVals = {\n      findNear, nearOn: !!st.near, nearAsk: st.nearAsk, nearBar: !!st.near && !st.nearAsk,\n      nearPlace: st.near ? (st.near.label === 'you' ? 'your location' : st.near.label) : '',\n      changeZip: () => this.setState({ nearAsk: true, nearErr: '', nearZipIn: st.near && st.near.label !== 'you' ? st.near.label : '' }),\n      useLocation: () => locate(), useLocStyle: 'border: 0; background: none; padding: 4px 0; font: inherit; font-size: 14px; font-weight: 600; color: #C8102E; cursor: pointer; ' + (st.near && st.near.label === 'you' ? 'display: none' : ''),\n      clearNear: () => this.setState({ near: null, nearAsk: false, nearErr: '' }), nearZipIn: st.nearZipIn, nearErr: st.nearErr,\n      setNearZip: (e) => this.setState({ nearZipIn: String(e.target.value || '').replace(/\\D/g, '').slice(0, 5), nearErr: '' }),\n      goNearZip: () => { const z = (st.nearZipIn || '').trim(); if (!useZip(z)) this.setState({ nearErr: /^\\d{5}$/.test(z) ? 'We don\\'t know that zip. Try a Washington zip.' : 'Enter a 5-digit zip.' }); },\n      nearErrStyle: st.nearErr ? 'font-size: 13px; font-weight: 600; color: #C8102E' : 'display: none',\n      nearLabel: st.nearBusy ? 'Finding you\u2026' : st.near ? 'Near ' + st.near.label + ' \u2715' : 'Shops near me',\n      nearIcon: st.near ? '#FFFFFF' : '#C8102E',\n      nearBtnStyle: 'display: flex; align-items: center; gap: 8px; height: 48px; padding: 0 18px; border-radius: 8px; font: inherit; font-size: 14px; font-weight: 600; cursor: pointer; ' +\n        (st.near ? 'border: 1px solid #C8102E; background: #C8102E; color: #FFFFFF' : 'border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111')\n    };\n    return {\n      ...formVals, ...nearVals,\n      isShops: st.tab === 'shops', isStrains: st.tab === 'strains',\n      showShops: () => this.setState({ tab: 'shops' }), showStrains: () => this.setState({ tab: 'strains' }),\n      shopTabStyle: st.tab === 'shops' ? tabOn : tabOff, strainTabStyle: st.tab === 'strains' ? tabOn : tabOff,\n      shops, strains, counties, types, pickedShops, pickedStrains,\n      shopCount: pickedShops.length, capStyle: atCap ? 'font-size: 13px; line-height: 1.45; color: #555555; background: #F7F7F9; border-radius: 8px; padding: 10px 12px' : 'display: none', q: st.q || '', onSearch: (e) => this.setState({ q: e.target.value, showAll: false }),\n      shopListLabel: q ? shopsAll.length + (shopsAll.length === 1 ? ' shop' : ' shops') + ' matching \"' + st.q.trim() + '\"' : near ? 'Closest shops to ' + near.label : shopsAll.length + ' shops' + (st.county === 'All counties' ? '' : ' in ' + st.county + ' County') + ' \u00b7 upcoming drops first',\n      toggleAll: () => this.setState({ showAll: !st.showAll }),\n      moreLabel: st.showAll ? 'Show fewer' : 'Show all ' + shopsAll.length + ' shops',\n      moreStyle: 'height: 46px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111; font: inherit; font-size: 14px; font-weight: 600; cursor: pointer; display: ' + (shopsAll.length > 7 ? 'block' : 'none'), strainCount: pickedStrains.length, strainCapStyle: strainCap ? 'font-size: 13px; line-height: 1.45; color: #555555; background: #F7F7F9; border-radius: 8px; padding: 10px 12px' : 'display: none'\n    };\n  }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n", "Contact": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird \u2014 Contact\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0;background:#F2F2F4}\na{color:#C8102E}a:hover{color:#9E0B22}\n\u003c/style>\n\u003cstyle>\n@media (max-width: 640px) {\n  [style*=\"max-width: 1200px\"] { padding-left: 20px !important; padding-right: 20px !important; }\n  [style*=\"flex: 1 1\"] { flex-basis: 100% !important; min-width: 0 !important; }\n  h1 { font-size: 56px !important; line-height: 0.92 !important; letter-spacing: 1.5px !important; text-wrap: balance; }\n  h2[style*=\"font-size: 72px\"], h2[style*=\"font-size: 56px\"] { font-size: 44px !important; }\n  h2[style*=\"font-size: 48px\"], h2[style*=\"font-size: 44px\"] { font-size: 36px !important; }\n\n  /* header: logo + Find a shop on top, page links in a swipeable row underneath */\n  header > div { gap: 0 10px !important; padding-top: 8px !important; padding-bottom: 8px !important; }\n  header a[aria-label=\"Redbird home\"] img { height: 26px !important; }\n  header a[href=\"Drops.dc.html\"][style*=\"height: 44px\"] { height: 40px !important; padding: 0 14px !important; }\n  header > div > div { margin-left: auto; }\n  header a[aria-label=\"Redbird on Instagram\"] { display: none !important; }\n  /* menu button: tap to show the page links as a list under the header row */\n  header label[for=\"rb-menu\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] { order: 3; flex: 1 1 100% !important; display: none !important; flex-direction: column; gap: 0 !important; margin: 8px -20px -8px; padding: 4px 20px 10px; border-top: 1px solid rgba(0,0,0,0.08); }\n  header #rb-menu:checked ~ nav[aria-label=\"Main\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] > span[aria-hidden=\"true\"] { display: none !important; }\n  header nav[aria-label=\"Main\"] a { display: flex; align-items: center; min-height: 48px; padding: 0 12px !important; margin: 2px 0; font-size: 17px !important; border-radius: 8px; }\n  header nav[aria-label=\"Main\"] a span { margin-left: 8px !important; }\n\n  /* photos */\n  img[style*=\"height: 600px\"], img[style*=\"height: 520px\"] { height: 300px !important; }\n  img[style*=\"height: 210px\"] { height: 130px !important; }\n  [style*=\"min-height: 560px\"], [style*=\"min-height: 460px\"] { min-height: 300px !important; }\n  [style*=\"right: 28px; bottom: 28px\"] { position: static !important; max-width: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n  /* grids */\n  [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { padding: 14px !important; }\n  [style*=\"minmax(160px, 1fr)\"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 6px !important; }\n  [style*=\"minmax(340px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; }\n  [role=\"radiogroup\"][style*=\"minmax(220px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  [role=\"radiogroup\"] button { padding: 14px !important; }\n\n  /* home page strain table becomes stacked rows */\n  [style*=\"min-width: 720px\"] { min-width: 0 !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"][style*=\"text-transform: uppercase\"] { display: none !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] { grid-template-columns: minmax(0, 1fr) auto !important; gap: 4px 12px !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] > :nth-child(n+3) { grid-column: 1 / -1; font-size: 13px; }\n\n  /* strains: hero stats stay on one line each */\n  [style*=\"display: flex; gap: 32px\"] { gap: 20px !important; }\n  [style*=\"font-size: 48px; line-height: 1\"] { font-size: 36px !important; white-space: nowrap; }\n\n  /* drops: tighter shop rows */\n  button[style*=\"min-width: 112px\"] { min-width: 0 !important; padding: 0 12px !important; }\n  form[style*=\"padding: 28px\"] { padding: 20px !important; }\n\n  /* strain label viewer */\n  [role=\"dialog\"] [style*=\"justify-content: space-between\"] { flex-wrap: wrap !important; padding: 12px 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 20px 24px\"] { padding: 10px !important; }\n  [role=\"dialog\"] [style*=\"padding: 18px 24px 22px\"] { padding: 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 24px\"] { padding: 10px !important; }\n}\n\u003c/style>\n\u003cstyle>@media (max-width: 640px) { [style*=\"min-height: 560px\"] { min-height: 0 !important; } [style*=\"min-height: 560px\"] > img { position: static !important; display: block; height: 340px !important; object-position: center 18% !important; } [style*=\"left: 16px; right: 16px; bottom: 16px\"] { position: static !important; border-radius: 0 !important; box-shadow: none !important; } form[style*=\"min-height: 650px\"] { min-height: 0 !important; } }\u003c/style>\n\u003cstyle>\n  header { position: sticky !important; top: 0; z-index: 50; }\n  #rb-menu:focus-visible ~ div label[for=\"rb-menu\"] { outline: 2px solid #C8102E; outline-offset: 2px; }\n  @media (max-width: 640px) {\n    /* Products: current strains as a list (name + type, genetics, status) */\n    [style*=\"minmax(260px, 1fr)\"]:has(> a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]),\n    [style*=\"minmax(260px, 1fr)\"]:has(> * > a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]) { grid-template-columns: minmax(0, 1fr) !important; gap: 8px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { display: grid !important; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: \"name tag\" \"gen gen\" \"stat stat\"; align-items: center; gap: 2px 10px !important; padding: 12px 14px !important; border-radius: 10px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) { display: contents !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:first-child { grid-area: tag; justify-self: end; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:last-child { display: none !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(2) { grid-area: name; font-size: 24px !important; min-width: 0; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(3) { grid-area: gen; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(4) { grid-area: stat; margin-top: 4px !important; padding-top: 0 !important; border-top: 0 !important; }\n    /* Beta Bud cards, two across: long names and tags stay inside the card */\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] { padding: 14px !important; min-width: 0; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] div[style*=\"font-size: 30px\"] { font-size: 24px !important; overflow-wrap: anywhere; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] > div[style*=\"justify-content: space-between\"] { flex-wrap: wrap; gap: 6px !important; }\n    /* iPhone zooms into any field under 16px: keep form text at 16px */\n    input, select, textarea { font-size: 16px !important; }\n  }\n  @media (max-width: 340px) { [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; } }\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4\">\n\n  \u003cheader style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 14px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 16px 28px\">\n      \u003cinput type=\"checkbox\" id=\"rb-menu\" aria-label=\"Menu\" style=\"position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none\">\n      \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none; color: #111111\">\n        \u003cimg src=\"/_blob/e3c029787746d07f7ac7aabb57e33d83\" alt=\"Redbird\" style=\"height: 32px; width: auto; display: block\">\n      \u003c/a>\n      \u003cnav aria-label=\"Main\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1\">\n        \u003ca href=\"Flower.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Products\u003c/a>\n        \u003ca href=\"Strains.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Drops\u003c/a>\n        \u003ca href=\"Contact.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 8px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Contact\u003c/a>\n        \u003ca href=\"Merch.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Merch\u003cspan style=\"margin-left: 6px; padding: 2px 5px; border-radius: 4px; background: #F2F2F4; font-family: 'Space Mono', monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: #767676; vertical-align: 2px\">Soon\u003c/span>\u003c/a>\n        \u003cspan aria-hidden=\"true\" style=\"flex: none; width: 1px; height: 22px; background: rgba(0,0,0,0.18); align-self: center; margin: 0 10px\">\u003c/span>\n        \u003ca href=\"Retailers.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">For Retailers\u003c/a>\n      \u003c/nav>\n      \u003cdiv style=\"display: flex; align-items: center; gap: 10px\">\n        \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Redbird on Instagram\" style=\"width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.08); display: flex; align-items: center; justify-content: center; color: #111111\">\n          \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\u003crect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\">\u003c/rect>\u003ccircle cx=\"12\" cy=\"12\" r=\"4\">\u003c/circle>\u003ccircle cx=\"17.5\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\">\u003c/circle>\u003c/svg>\n        \u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n        \u003clabel for=\"rb-menu\" aria-hidden=\"true\" style=\"display: none; width: 40px; height: 40px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.12); align-items: center; justify-content: center; color: #111111; cursor: pointer\">\u003csvg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\u003cline x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\">\u003c/line>\u003cline x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\">\u003c/line>\u003cline x1=\"4\" y1=\"17\" x2=\"20\" y2=\"17\">\u003c/line>\u003c/svg>\u003c/label>\n      \u003c/div>\n    \u003c/div>\n  \u003c/header>\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 48px 24px 24px; display: flex; flex-wrap: wrap; gap: 32px; align-items: flex-end; justify-content: space-between\">\n    \u003cdiv style=\"flex: 1 1 520px; display: flex; flex-direction: column; gap: 14px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">Contact\u003c/div>\n      \u003ch1 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 104px; letter-spacing: 2px; line-height: 0.9\">Talk to the team.\u003c/h1>\n      \u003cp style=\"margin: 0; font-size: 17px; line-height: 1.6; color: #555555; max-width: 560px\">Press, careers, retail accounts or just a question about a strain \u2014 pick a topic and it goes straight to the right person.\u003c/p>\n    \u003c/div>\n    \u003cdiv style=\"flex: 0 1 360px; display: flex; flex-direction: column; gap: 10px; font-size: 14px; color: #555555\">\n      \u003cdiv style=\"display: flex; gap: 12px; align-items: baseline\">\u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; text-transform: uppercase; color: #767676; width: 72px; flex: none\">Where\u003c/span> Spokane, Washington\u003c/div>\n      \u003cdiv style=\"display: flex; gap: 12px; align-items: baseline\">\u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; text-transform: uppercase; color: #767676; width: 72px; flex: none\">Social\u003c/span> \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\">@redbird_wa\u003c/a>\u003c/div>\n      \u003cdiv style=\"display: flex; gap: 12px; align-items: baseline\">\u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; text-transform: uppercase; color: #767676; width: 72px; flex: none\">Reply\u003c/span> Usually within 1\u20132 business days\u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \n\n  \u003cmain style=\"max-width: 1200px; margin: 0 auto; padding: 16px 24px 64px; display: flex; flex-direction: column; gap: 24px\">\n    \u003cdiv role=\"radiogroup\" aria-label=\"What's this about?\" style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px\">\n      \u003csc-for list=\"{{topics}}\" as=\"t\" hint-placeholder-count=\"4\">\n        \u003cbutton role=\"radio\" aria-checked=\"{{t.on}}\" onClick=\"{{t.pick}}\" style=\"{{t.style}}\">\n          \u003cspan style=\"{{t.iconWrap}}\">\n            \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\u003cpath d=\"{{t.icon}}\">\u003c/path>\u003c/svg>\n          \u003c/span>\n          \u003cspan style=\"font-family: 'Bebas Neue', sans-serif; font-size: 26px; letter-spacing: 1.5px; line-height: 1\">{{t.label}}\u003c/span>\n          \u003cspan style=\"font-size: 13px; line-height: 1.5; color: #555555\">{{t.blurb}}\u003c/span>\n        \u003c/button>\n      \u003c/sc-for>\n    \u003c/div>\n\n    \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 24px; align-items: stretch\">\n      \u003cdiv style=\"flex: 1 1 380px; position: relative; border-radius: 12px; overflow: hidden; min-height: 560px; background: #111111\">\n        \u003cimg src=\"{{active.img}}\" alt=\"{{active.imgAlt}}\" style=\"position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: {{active.imgPos}}\">\n        \u003cdiv style=\"position: absolute; left: 16px; right: 16px; bottom: 16px; background: #FFFFFF; border-radius: 12px; padding: 18px 20px; box-shadow: 0 8px 32px rgba(0,0,0,0.14); display: flex; flex-direction: column; gap: 6px\">\n          \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 10px; letter-spacing: 1.2px; text-transform: uppercase; color: #C8102E\">{{active.eyebrow}}\u003c/div>\n          \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 28px; letter-spacing: 1.5px; line-height: 1\">{{active.cardTitle}}\u003c/div>\n          \u003cdiv style=\"font-size: 14px; line-height: 1.55; color: #555555\">{{active.cardBody}}\u003c/div>\n        \u003c/div>\n      \u003c/div>\n\n      \u003cform onsubmit=\"return false\" style=\"min-height: 650px; flex: 1 1 520px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; box-shadow: 0 1px 4px rgba(0,0,0,0.08); padding: 28px; display: flex; flex-direction: column; gap: 16px\">\n        \u003csc-if value=\"{{notSent}}\" hint-placeholder-val=\"{{ true }}\">\n        \u003cdiv style=\"display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap\">\n          \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 36px; letter-spacing: 2px; line-height: 1\">{{active.formTitle}}\u003c/h2>\n          \u003cspan style=\"padding: 5px 12px; border-radius: 999px; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); color: #C8102E; font-size: 12px; font-weight: 600\">{{active.label}}\u003c/span>\n        \u003c/div>\n        \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 12px\">\n          \u003clabel style=\"flex: 1 1 200px; display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">First name\n            \u003cinput type=\"text\" autocomplete=\"given-name\" value=\"{{fFirst}}\" onChange=\"{{setFirst}}\" style=\"height: 46px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 14px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9\">\n          \u003c/label>\n          \u003clabel style=\"flex: 1 1 200px; display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">Last name\n            \u003cinput type=\"text\" autocomplete=\"family-name\" value=\"{{fLast}}\" onChange=\"{{setLast}}\" style=\"height: 46px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 14px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9\">\n          \u003c/label>\n        \u003c/div>\n        \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 12px\">\n          \u003clabel style=\"flex: 1 1 200px; display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">Email\n            \u003cinput type=\"email\" autocomplete=\"email\" value=\"{{fEmail}}\" onChange=\"{{setEmail}}\" style=\"height: 46px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 14px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9\">\n          \u003c/label>\n          \u003clabel style=\"flex: 1 1 200px; display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">Phone \u003cspan style=\"font-weight: 400; color: #767676\">(optional)\u003c/span>\n            \u003cinput type=\"tel\" autocomplete=\"tel\" value=\"{{fPhone}}\" onChange=\"{{setPhone}}\" style=\"height: 46px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 14px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9\">\n          \u003c/label>\n        \u003c/div>\n        \u003clabel style=\"display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">{{active.extraLabel}}\n          \u003cinput type=\"text\" placeholder=\"{{active.extraHint}}\" value=\"{{fDetail}}\" onChange=\"{{setDetail}}\" style=\"height: 46px; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 0 14px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9\">\n        \u003c/label>\n        \u003cinput type=\"text\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" aria-hidden=\"true\" value=\"{{fHp}}\" onChange=\"{{setHp}}\" style=\"position: absolute; left: -9999px; width: 1px; height: 1px; opacity: 0\">\n        \u003csc-if value=\"{{isCareers}}\" hint-placeholder-val=\"{{ false }}\">\n          \u003clabel style=\"position: relative; display: flex; align-items: center; gap: 14px; border: 1px dashed rgba(0,0,0,0.2); border-radius: 8px; padding: 14px 16px; background: #F7F7F9; cursor: pointer\">\n            \u003csvg aria-hidden=\"true\" width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#C8102E\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\u003cpath d=\"M12 16V4M7 9l5-5 5 5M5 20h14\">\u003c/path>\u003c/svg>\n            \u003cdiv style=\"flex: 1; min-width: 0; font-size: 14px\">\u003cstrong>{{fileTitle}}\u003c/strong> \u003cspan style=\"color: #555555; overflow-wrap: anywhere\">{{fileNote}}\u003c/span>\u003c/div>\n            \u003cspan style=\"height: 36px; padding: 0 14px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; font-size: 13px; font-weight: 600; display: flex; align-items: center; white-space: nowrap\">{{fileBtn}}\u003c/span>\n            \u003cinput type=\"file\" accept=\".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document\" onChange=\"{{pickFile}}\" style=\"position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; cursor: pointer\">\n          \u003c/label>\n        \u003c/sc-if>\n        \u003clabel style=\"flex: 1; display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 600\">Message\n          \u003ctextarea rows=\"5\" placeholder=\"{{active.msgHint}}\" value=\"{{fMessage}}\" onChange=\"{{setMessage}}\" style=\"flex: 1; border: 1px solid rgba(0,0,0,0.15); border-radius: 8px; padding: 12px 14px; font: inherit; font-size: 15px; font-weight: 400; background: #F7F7F9; resize: vertical\">\u003c/textarea>\n        \u003c/label>\n        \u003cdiv style=\"{{errStyle}}\" role=\"alert\">{{formError}}\u003c/div>\n        \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 14px; align-items: center\">\n          \u003cbutton type=\"button\" onClick=\"{{submit}}\" style=\"height: 50px; padding: 0 28px; border-radius: 8px; border: 0; background: #C8102E; color: #FFFFFF; font: inherit; font-size: 15px; font-weight: 600; cursor: pointer\">{{sendLabel}}\u003c/button>\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; text-transform: uppercase; color: #767676\">Goes to: {{active.routes}}\u003c/span>\n        \u003c/div>\n        \u003cdiv style=\"font-size: 13px; color: #767676\">Want drop alerts? \u003ca href=\"Drops.dc.html\" style=\"font-weight: 600\">Follow your shops and strains on Drops &rarr;\u003c/a>\u003c/div>\n        \u003c/sc-if>\n        \u003csc-if value=\"{{sent}}\" hint-placeholder-val=\"{{ false }}\">\n          \u003cdiv style=\"flex: 1; display: flex; flex-direction: column; justify-content: center; gap: 14px; padding: 24px 8px\">\n            \u003cdiv style=\"width: 52px; height: 52px; border-radius: 999px; background: #C8102E; color: #FFFFFF; display: flex; align-items: center; justify-content: center\">\n              \u003csvg aria-hidden=\"true\" width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\u003cpath d=\"M5 12l5 5L20 7\">\u003c/path>\u003c/svg>\n            \u003c/div>\n            \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 44px; letter-spacing: 2px; line-height: 1\">Message sent.\u003c/h2>\n            \u003cp style=\"margin: 0; font-size: 16px; line-height: 1.6; color: #555555; max-width: 460px\">{{sentMsg}}\u003c/p>\n            \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 12px; margin-top: 6px\">\n              \u003cbutton type=\"button\" onClick=\"{{again}}\" style=\"height: 46px; padding: 0 20px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; font: inherit; font-size: 14px; font-weight: 600; cursor: pointer\">Send another message\u003c/button>\n              \u003ca href=\"Drops.dc.html\" style=\"height: 46px; padding: 0 20px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Get drop alerts\u003c/a>\n            \u003c/div>\n          \u003c/div>\n        \u003c/sc-if>\n      \u003c/form>\n    \u003c/div>\n  \u003c/main>\n\n  \u003cfooter style=\"background: #111111; color: #A3A3A3\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px 36px; display: flex; flex-direction: column; gap: 26px\">\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px; align-items: center; justify-content: space-between\">\n        \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none\">\n          \u003cimg src=\"/_blob/186e35dcb739a15a6a58be91a24ac455\" alt=\"Redbird\" style=\"height: 30px; width: auto; display: block\">\n        \u003c/a>\n        \u003cnav aria-label=\"Footer\" style=\"display: flex; flex-wrap: wrap; gap: 24px; font-size: 14px\">\n          \u003ca href=\"Main.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Home\u003c/a>\n          \u003ca href=\"Flower.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Products\u003c/a>\n          \u003ca href=\"Strains.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Strains\u003c/a>\n          \u003ca href=\"Drops.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Drops\u003c/a>\n          \u003ca href=\"Contact.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Contact\u003c/a>\n          \u003ca href=\"Merch.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Merch\u003cspan style=\"margin-left: 5px; font-size: 11px; color: #8A8A8F\">(soon)\u003c/span>\u003c/a>\n          \u003ca href=\"Retailers.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">For Retailers\u003c/a>\n          \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF; text-decoration: none\">Instagram\u003c/a>\n        \u003c/nav>\n      \u003c/div>\n      \u003cdiv style=\"border-top: 1px solid #2A2A2A; padding-top: 22px; display: flex; flex-direction: column; gap: 12px; font-size: 12px; line-height: 1.7; max-width: 980px\">\n        \u003cp style=\"margin: 0\">Redbird is a Tier 3 Producer/Processor headquartered in Spokane, Washington.\u003c/p>\n        \u003cp style=\"margin: 0\">\u003cstrong style=\"color: #FFFFFF; font-weight: 700\">WARNING:\u003c/strong> This product may be unlawful outside of Washington State. This product has intoxicating effects and may be habit forming. Smoking is hazardous to your health. There may be health risks associated with consumption of this product. Should not be used by women that are pregnant or breast feeding. For use only by adults twenty-one and older. Keep out of reach of children. Marijuana can impair concentration, coordination, and judgment. Do not operate a vehicle or machinery under the influence of this drug.\u003c/p>\n        \u003cp style=\"margin: 0\">Redbird uses the following in the production of its cannabis products: Kaligreen by OAT Agrio Co LTD (approved for use in certified organic agriculture, OMRI listed) and Clonex Rooting Gel by Growth Technology, LTD.\u003c/p>\n        \u003cp style=\"margin: 0; font-family: 'Space Mono', monospace; font-size: 11px; color: #8A8A8A\">\u00a9 2016\u20132026 Redbird\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/footer>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":1900}}'>\nclass Component extends DCLogic {\n  constructor(props) {\n    super(props);\n    const T = (window.parent && window.parent.RB_TOPIC) || '';\n    this.state = { topic: ['general', 'retail', 'press', 'careers'].indexOf(T) > -1 ? T : 'general',\n      fFirst: '', fLast: '', fEmail: '', fPhone: '', fDetail: '', fMessage: '', fHp: '', file: null, busy: false, formError: '', sent: false, sentMsg: '' };\n    this.t0 = Date.now();\n  }\n  renderVals() {\n    const data = [\n      { id: 'general', img: '/_blob/8679f9a12d6663a5512bcbb9bdf0a3a4', imgPos: 'center 22%', imgAlt: \"A smiling Redbird team member in a Redbird shirt and cap between shelves of Redbird boxes\", label: 'General', blurb: 'Questions about a strain, a product, or where to find us.',\n        icon: 'M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.4A8 8 0 1 1 21 12z',\n        eyebrow: 'General questions', cardTitle: 'A real person reads every note.', cardBody: 'Ask about a strain, a product or where it landed. For shop-by-shop alerts, try Drops.',\n        formTitle: 'Send us a note', extraLabel: 'Subject', extraHint: 'What\u2019s on your mind?', msgHint: 'Tell us what you\u2019re looking for\u2026', routes: 'Front office' },\n      { id: 'retail', img: '/_blob/9ca56d3b9a154088a5cc2cbb5c4db1f0', imgPos: '72% center', imgAlt: \"A Redbird team member stocking shelves of Redbird boxes\", label: 'Retail & wholesale', blurb: 'Carry Redbird, request samples, or get help with an order.',\n        icon: 'M3 9l2-5h14l2 5M3 9h18v11H3zM9 20v-6h6v6',\n        eyebrow: 'For retailers', cardTitle: 'Carry Redbird at your shop.', cardBody: 'Ask about samples, menus and weekly harvest availability. Existing accounts can reach their rep here too.',\n        formTitle: 'Retail inquiry', extraLabel: 'Shop name & license #', extraHint: 'e.g. Smokane \u00b7 4xxxxx', msgHint: 'Products you\u2019re interested in, timing, questions\u2026', routes: 'Sales team' },\n      { id: 'press', img: '/_blob/e0179ef06f9e30bfdce87f6d1ce533a9', imgPos: 'center center', imgAlt: \"The Wing A hallway inside the Redbird facility\", label: 'Press & media', blurb: 'Interviews, features, photo requests and brand assets.',\n        icon: 'M4 5h13v14H6a2 2 0 0 1-2-2zM17 9h3v8a2 2 0 0 1-2 2M8 9h5M8 13h5',\n        eyebrow: 'Press & media', cardTitle: 'Writing about Washington cannabis?', cardBody: 'We\u2019re happy to talk aeroponics, live rosin and how we grow. Logos and product photos on request.',\n        formTitle: 'Press request', extraLabel: 'Outlet', extraHint: 'Publication, podcast or channel', msgHint: 'Your story, deadline and what you need from us\u2026', routes: 'Marketing' },\n      { id: 'careers', img: '/_blob/e4571f6f6dfd10cf6483e349d017eac3', imgPos: '62% center', imgAlt: \"A Redbird grower cutting clones into a tray\", label: 'Careers', blurb: 'Grow, extraction, packaging and sales roles in Spokane.',\n        icon: 'M4 8h16v11H4zM9 8V5h6v3M4 13h16',\n        eyebrow: 'Careers', cardTitle: 'Grow with Redbird.', cardBody: 'We hire in cultivation, extraction, packaging and sales. Tell us what you do best \u2014 we keep every application on file.',\n        formTitle: 'Join the team', extraLabel: 'Role you\u2019re interested in', extraHint: 'e.g. Cultivation tech, Trimmer, Sales rep', msgHint: 'A little about you and your experience\u2026', routes: 'Hiring' }\n    ];\n    const cur = this.state.topic;\n    const topics = data.map((t) => {\n      const on = t.id === cur;\n      return {\n        label: t.label, blurb: t.blurb, icon: t.icon, on,\n        pick: () => this.setState({ topic: t.id }),\n        style: 'text-align: left; font: inherit; cursor: pointer; display: flex; flex-direction: column; gap: 10px; padding: 18px; border-radius: 12px; color: #111111; ' + (on ? 'background: #FFFFFF; border: 2px solid #C8102E; box-shadow: 0 1px 4px rgba(0,0,0,0.08)' : 'background: #FFFFFF; border: 2px solid transparent; outline: 1px solid rgba(0,0,0,0.08); outline-offset: -2px'),\n        iconWrap: 'width: 40px; height: 40px; border-radius: 8px; display: flex; align-items: center; justify-content: center; ' + (on ? 'background: #C8102E; color: #FFFFFF' : 'background: rgba(200,16,46,0.06); color: #C8102E')\n      };\n    });\n    const active = data.find((t) => t.id === cur);\n    const st = this.state, api = (window.parent && window.parent.RB_API) || window.RB_API;\n    const set = (k) => (e) => this.setState({ [k]: e.target.value, formError: '' });\n    const pickFile = (e) => {\n      const f = e.target.files && e.target.files[0]; if (!f) return;\n      if (!/\\.(pdf|docx?)$/i.test(f.name)) return this.setState({ file: null, formError: 'R\u00e9sum\u00e9s need to be a PDF or Word file.' });\n      if (f.size > 10 * 1024 * 1024) return this.setState({ file: null, formError: 'R\u00e9sum\u00e9s can be up to 10MB.' });\n      const rd = new FileReader();\n      rd.onload = () => this.setState({ file: { name: f.name, type: f.type, data: String(rd.result).split(',')[1] || '' }, formError: '' });\n      rd.onerror = () => this.setState({ file: null, formError: 'We couldn\\'t read that file. Please try another.' });\n      rd.readAsDataURL(f);\n    };\n    const submit = () => {\n      if (st.busy) return;\n      let err = '';\n      if (!st.fFirst.trim()) err = 'Please add your first name.';\n      else if (!/^[^\\s@]+@[^\\s@]+\\.[a-z]{2,}$/i.test(st.fEmail.trim())) err = 'Please enter a valid email address.';\n      else if (st.fMessage.trim().length \u003c 2) err = 'Please add a message.';\n      if (err) return this.setState({ formError: err });\n      if (!api) return this.setState({ formError: 'The contact form isn\\'t connected in this preview.' });\n      this.setState({ busy: true, formError: '' });\n      const req = { action: 'contact', topic: cur, first: st.fFirst.trim(), last: st.fLast.trim(), email: st.fEmail.trim(), phone: st.fPhone.trim(),\n                    detail: st.fDetail.trim(), message: st.fMessage.trim(), hp: st.fHp, ms: Date.now() - this.t0 };\n      if (cur === 'careers' && st.file) req.file = st.file;\n      api(req).then((r) => (r && r.ok)\n          ? this.setState({ busy: false, sent: true, sentMsg: r.message, fDetail: '', fMessage: '', file: null })\n          : this.setState({ busy: false, formError: (r && r.error) || 'Something went wrong. Please try again.' }))\n        .catch(() => this.setState({ busy: false, formError: 'We couldn\\'t reach Redbird. Check your connection and try again.' }));\n    };\n    return { topics, active, isCareers: cur === 'careers',\n      fFirst: st.fFirst, fLast: st.fLast, fEmail: st.fEmail, fPhone: st.fPhone, fDetail: st.fDetail, fMessage: st.fMessage, fHp: st.fHp,\n      setFirst: set('fFirst'), setLast: set('fLast'), setEmail: set('fEmail'), setPhone: set('fPhone'), setDetail: set('fDetail'), setMessage: set('fMessage'), setHp: set('fHp'),\n      pickFile, fileTitle: st.file ? 'R\u00e9sum\u00e9 attached' : 'Attach a r\u00e9sum\u00e9', fileNote: st.file ? st.file.name : 'PDF or Word, up to 10MB', fileBtn: st.file ? 'Change' : 'Choose file',\n      errStyle: st.formError ? 'font-size: 14px; font-weight: 600; color: #C8102E; line-height: 1.4' : 'display: none', formError: st.formError,\n      submit, sendLabel: st.busy ? 'Sending\u2026' : 'Send message',\n      notSent: !st.sent, sent: st.sent, sentMsg: st.sentMsg, again: () => this.setState({ sent: false, formError: '' }) };\n  }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n", "Mobile-Home": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird \u2014 Home (mobile)\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0}\na{color:#C8102E}a:hover{color:#9E0B22}\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"width: 390px; height: 2720px; overflow: hidden; font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4; display: flex; flex-direction: column\">\n  \u003cheader style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08); padding: 12px 16px; display: flex; align-items: center; justify-content: space-between\">\n    \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 8px; text-decoration: none; color: #111111\">\n      \u003cimg src=\"/_blob/e3c029787746d07f7ac7aabb57e33d83\" alt=\"Redbird\" style=\"height: 28px; width: auto; display: block\">\n    \u003c/a>\n    \u003cdiv style=\"display: flex; gap: 8px\">\n      \u003ca href=\"Drops.dc.html\" style=\"height: 44px; padding: 0 14px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n      \u003cbutton aria-label=\"Open menu\" style=\"width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.08); background: #FFFFFF; display: flex; align-items: center; justify-content: center\">\n        \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111111\" stroke-width=\"2\" stroke-linecap=\"round\">\u003cpath d=\"M4 7h16M4 12h16M4 17h16\">\u003c/path>\u003c/svg>\n      \u003c/button>\n    \u003c/div>\n  \u003c/header>\n\n  \u003csection style=\"padding: 28px 20px 20px; display: flex; flex-direction: column; gap: 16px\">\n    \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #C8102E\">Spokane, WA \u00b7 Aeroponic cannabis\u003c/div>\n    \u003ch1 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 64px; line-height: 0.92; letter-spacing: 1.5px\">Grown in air.\u003cbr>Built for flavor.\u003c/h1>\n    \u003cp style=\"margin: 0; font-size: 16px; line-height: 1.6; color: #555555\">High-pressure aeroponics and closed-environment rooms give every Redbird strain vibrant color and a deep terpene profile \u2014 harvested every week.\u003c/p>\n    \u003cdiv style=\"display: flex; flex-direction: column; gap: 10px\">\n      \u003ca href=\"Strains.dc.html\" style=\"height: 50px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 600; display: flex; align-items: center; justify-content: center; text-decoration: none\">Explore strains\u003c/a>\n      \u003ca href=\"Drops.dc.html\" style=\"height: 50px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111; font-size: 15px; font-weight: 600; display: flex; align-items: center; justify-content: center; text-decoration: none\">Get drop alerts\u003c/a>\n    \u003c/div>\n    \u003cimg src=\"/_blob/c8b828b21e21d4a9887f59a0b1515635\" alt=\"A Redbird Chocolate Bars jar with chocolate and flower\" style=\"width: 100%; height: 300px; object-fit: cover; border-radius: 12px; display: block\">\n  \u003c/section>\n\n  \u003csection style=\"padding: 8px 20px 24px; display: flex; flex-direction: column; gap: 10px\">\n    \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 16px 18px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 10px; letter-spacing: 1.2px; text-transform: uppercase; color: #C8102E\">01 \u00b7 Grow\u003c/div>\n      \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 24px; letter-spacing: 1.2px; margin-top: 4px\">High-pressure aeroponics\u003c/div>\n    \u003c/div>\n    \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 16px 18px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 10px; letter-spacing: 1.2px; text-transform: uppercase; color: #C8102E\">02 \u00b7 Environment\u003c/div>\n      \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 24px; letter-spacing: 1.2px; margin-top: 4px\">Closed-environment rooms\u003c/div>\n    \u003c/div>\n    \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 16px 18px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 10px; letter-spacing: 1.2px; text-transform: uppercase; color: #C8102E\">03 \u00b7 Extract\u003c/div>\n      \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 24px; letter-spacing: 1.2px; margin-top: 4px\">Live rosin, made in house\u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"padding: 8px 20px 28px; display: flex; flex-direction: column; gap: 12px\">\n    \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 40px; letter-spacing: 2.5px; line-height: 1\">Products\u003c/h2>\n    \u003cdiv style=\"display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px\">\n      \u003csc-for list=\"{{products}}\" as=\"p\" hint-placeholder-count=\"6\">\n        \u003ca href=\"{{p.href}}\" style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; overflow: hidden; text-decoration: none; color: #111111; display: flex; flex-direction: column\">\n          \u003csc-if value=\"{{p.hasPhoto}}\" hint-placeholder-val=\"{{ false }}\">\n            \u003cimg src=\"{{p.img}}\" alt=\"{{p.alt}}\" style=\"width: 100%; height: 120px; object-fit: cover; display: block\">\n          \u003c/sc-if>\n          \u003csc-if value=\"{{p.noPhoto}}\" hint-placeholder-val=\"{{ true }}\">\n            \u003cdiv style=\"height: 120px; background: #F7F7F9; display: flex; align-items: center; justify-content: center; font-family: 'Space Mono', monospace; font-size: 9px; letter-spacing: 1px; text-transform: uppercase; color: #767676\">[photo]\u003c/div>\n          \u003c/sc-if>\n          \u003cdiv style=\"padding: 10px 12px 12px; display: flex; flex-direction: column; gap: 4px\">\n            \u003cspan style=\"font-family: 'Bebas Neue', sans-serif; font-size: 21px; letter-spacing: 1.2px; line-height: 1\">{{p.name}}\u003c/span>\n            \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 10px; color: #767676\">{{p.sizes}}\u003c/span>\n          \u003c/div>\n        \u003c/a>\n      \u003c/sc-for>\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"padding: 0 20px 28px; display: flex; flex-direction: column; gap: 12px\">\n    \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 34px; letter-spacing: 2px; line-height: 1\">Follow \u003cspan style=\"color: #C8102E\">@redbird_wa\u003c/span>\u003c/h2>\n    \u003cdiv style=\"display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px\">\n      \u003csc-for list=\"{{insta}}\" as=\"g\" hint-placeholder-count=\"6\">\n        \u003cimg src=\"{{g.src}}\" alt=\"\" style=\"width: 100%; aspect-ratio: 1 / 1; object-fit: cover; border-radius: 8px; display: block\">\n      \u003c/sc-for>\n    \u003c/div>\n  \u003c/section>\n\n  \u003csection style=\"background: #C8102E; color: #FFFFFF; padding: 32px 20px; display: flex; flex-direction: column; gap: 14px\">\n    \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #FFD9DE\">Redbird Drops\u003c/div>\n    \u003ch2 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 52px; letter-spacing: 1.5px; line-height: 0.95\">Never miss a drop.\u003c/h2>\n    \u003cp style=\"margin: 0; font-size: 15px; line-height: 1.6; color: #FFE9EC\">Follow your shops and favorite strains. We'll email you when fresh Redbird lands.\u003c/p>\n    \u003ca href=\"Drops.dc.html\" style=\"height: 50px; border-radius: 8px; background: #FFFFFF; color: #C8102E; font-size: 15px; font-weight: 700; display: flex; align-items: center; justify-content: center; text-decoration: none\">Get drop alerts\u003c/a>\n  \u003c/section>\n\n  \u003cfooter style=\"background: #111111; color: #A3A3A3; padding: 32px 20px 28px; display: flex; flex-direction: column; gap: 20px; flex: 1\">\n    \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; justify-content: center; gap: 8px; text-decoration: none\">\n      \u003cimg src=\"/_blob/186e35dcb739a15a6a58be91a24ac455\" alt=\"Redbird\" style=\"height: 26px; width: auto; display: block\">\n    \u003c/a>\n    \u003cnav aria-label=\"Footer\" style=\"display: flex; flex-wrap: wrap; justify-content: center; gap: 8px 20px; font-size: 14px\">\n      \u003ca href=\"Flower.dc.html\" style=\"color: #FFFFFF; text-decoration: none; padding: 6px 0\">Products\u003c/a>\n      \u003ca href=\"Strains.dc.html\" style=\"color: #FFFFFF; text-decoration: none; padding: 6px 0\">Strains\u003c/a>\n      \u003ca href=\"Drops.dc.html\" style=\"color: #FFFFFF; text-decoration: none; padding: 6px 0\">Drops\u003c/a>\n      \u003ca href=\"Contact.dc.html\" style=\"color: #FFFFFF; text-decoration: none; padding: 6px 0\">Contact\u003c/a>\n      \u003ca href=\"Merch.dc.html\" style=\"color: #FFFFFF; text-decoration: none; padding: 6px 0\">Merch\u003cspan style=\"margin-left: 5px; font-size: 11px; color: #8A8A8F\">(soon)\u003c/span>\u003c/a>\n      \u003ca href=\"Retailers.dc.html\" style=\"color: #FFFFFF; text-decoration: none; padding: 6px 0\">For Retailers\u003c/a>\n    \u003c/nav>\n    \u003cdiv style=\"border-top: 1px solid #2A2A2A; padding-top: 18px; display: flex; flex-direction: column; gap: 10px; font-size: 12px; line-height: 1.65; text-align: center\">\n      \u003cp style=\"margin: 0\">Redbird is a Tier 3 Producer/Processor headquartered in Spokane, Washington.\u003c/p>\n      \u003cp style=\"margin: 0\">\u003cstrong style=\"color: #FFFFFF; font-weight: 700\">WARNING:\u003c/strong> This product may be unlawful outside of Washington State. This product has intoxicating effects and may be habit forming. Smoking is hazardous to your health. There may be health risks associated with consumption of this product. Should not be used by women that are pregnant or breast feeding. For use only by adults twenty-one and older. Keep out of reach of children. Marijuana can impair concentration, coordination, and judgment. Do not operate a vehicle or machinery under the influence of this drug.\u003c/p>\n      \u003cp style=\"margin: 0\">Redbird uses the following in the production of its cannabis products: Kaligreen by OAT Agrio Co LTD (approved for use in certified organic agriculture, OMRI listed) and Clonex Rooting Gel by Growth Technology, LTD.\u003c/p>\n      \u003cp style=\"margin: 0; font-family: 'Space Mono', monospace; font-size: 11px; color: #8A8A8A\">\u00a9 2016\u20132026 Redbird\u003c/p>\n    \u003c/div>\n  \u003c/footer>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":390,\"height\":2720}}'>\nclass Component extends DCLogic {\n  renderVals() {\n    const products = [\n      { name: 'Flower', href: 'Flower.dc.html', sizes: '3.5G \u00b7 7G \u00b7 28G', img: '/_blob/295c326cd260b7386f629ae916ef43cb', alt: 'A Redbird Raspberry Dosido jar' },\n      { name: 'Beta Bud', href: 'BetaBud.dc.html', sizes: 'NEW GENETICS', img: '/_blob/b59992f64029d5bb28554590dd31dee1', alt: 'The Redbird Beta Buds label' },\n      { name: 'Micro buds', href: 'Micro.dc.html', sizes: '14G', img: '/_blob/70a6b4c28b3f104b722d485dc25f2f43', alt: 'The Redbird Micro Buds label' },\n      { name: 'Pre-rolls', href: 'Prerolls.dc.html', sizes: '1G \u00b7 2PK \u00b7 10PK', img: '/_blob/59c3ca3b24e0c7c42577d269ec5e8272', alt: 'Redbird pre-roll pack' },\n      { name: 'Rosin', href: 'Rosin.dc.html', sizes: 'LIVE ROSIN', img: '/_blob/c1827be414c190bc9faa7f53344faef9', alt: 'Redbird rosin jar' }\n    ].map((p) => Object.assign({}, p, { hasPhoto: !!p.img, noPhoto: !p.img }));\n    const insta = ['/_blob/766fdc4cacda02beaf14c0a5a0340bab', '/_blob/52ebf00d29f2f2b3b918a26a1f59aa47', '/_blob/ac615debb55668bc0e4d6281aab19ffd', '/_blob/1ee7eb0d5db8b9478ce1cf68070bb021', '/_blob/15e67d4f82bb144f39c0a27b7d18a2e5', '/_blob/9ddcfff3a2d0be8dd3760280bcad8747'].map((u) => ({ src: u }));\n    return { products, insta };\n  }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n", "Style-Guide": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird style guide\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0}\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"width: 1440px; height: 1160px; box-sizing: border-box; padding: 56px 64px; font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4; display: flex; flex-direction: column; gap: 36px\">\n  \u003cdiv style=\"display: flex; align-items: center; gap: 14px\">\n    \u003cimg src=\"/_blob/8f919b08492a1623d03820e2c5327fa4\" alt=\"Redbird bird mark\" style=\"height: 44px; width: auto\">\n    \u003cdiv>\n      \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 44px; letter-spacing: 3px; line-height: 1\">Redbird style guide\u003c/div>\n      \u003cdiv style=\"font-size: 14px; color: #555555\">One system for the website, the CRM, the pre-order portal and drop emails.\u003c/div>\n    \u003c/div>\n  \u003c/div>\n\n  \u003cdiv style=\"display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px\">\n    \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; gap: 16px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">Color\u003c/div>\n      \u003cdiv style=\"display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px\">\n        \u003csc-for list=\"{{colors}}\" as=\"c\" hint-placeholder-count=\"8\">\n          \u003cdiv style=\"display: flex; flex-direction: column; gap: 6px\">\n            \u003cdiv style=\"{{c.swatch}}\">\u003c/div>\n            \u003cdiv style=\"font-size: 13px; font-weight: 600\">{{c.name}}\u003c/div>\n            \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; color: #555555\">{{c.hex}}\u003c/div>\n          \u003c/div>\n        \u003c/sc-for>\n      \u003c/div>\n    \u003c/div>\n\n    \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; gap: 18px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">Type\u003c/div>\n      \u003cdiv style=\"display: flex; align-items: baseline; gap: 18px; border-bottom: 1px solid rgba(0,0,0,0.06); padding-bottom: 14px\">\n        \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 56px; letter-spacing: 3px; line-height: 1\">Bebas Neue\u003c/div>\n        \u003cdiv style=\"font-size: 13px; color: #555555\">Headlines, page titles, product names \u00b7 tracking 1.5\u20133px\u003c/div>\n      \u003c/div>\n      \u003cdiv style=\"display: flex; align-items: baseline; gap: 18px; border-bottom: 1px solid rgba(0,0,0,0.06); padding-bottom: 14px\">\n        \u003cdiv style=\"font-size: 30px; font-weight: 700\">DM Sans\u003c/div>\n        \u003cdiv style=\"font-size: 13px; color: #555555\">Body copy, buttons, nav \u00b7 400 / 500 / 600 / 700\u003c/div>\n      \u003c/div>\n      \u003cdiv style=\"display: flex; align-items: baseline; gap: 18px\">\n        \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 22px; font-weight: 700\">SPACE MONO\u003c/div>\n        \u003cdiv style=\"font-size: 13px; color: #555555\">Eyebrow labels, sizes, dates, data \u00b7 uppercase, 10\u201312px\u003c/div>\n      \u003c/div>\n    \u003c/div>\n  \u003c/div>\n\n  \u003cdiv style=\"display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px\">\n    \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; gap: 16px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">Buttons \u00b7 8px radius\u003c/div>\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 10px\">\n        \u003cspan style=\"height: 44px; padding: 0 20px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: inline-flex; align-items: center\">Primary\u003c/span>\n        \u003cspan style=\"height: 44px; padding: 0 20px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; font-size: 14px; font-weight: 600; display: inline-flex; align-items: center\">Secondary\u003c/span>\n        \u003cspan style=\"height: 44px; padding: 0 20px; border-radius: 8px; background: #111111; color: #FFFFFF; font-size: 14px; font-weight: 600; display: inline-flex; align-items: center\">On light/red\u003c/span>\n      \u003c/div>\n      \u003cdiv style=\"font-size: 13px; color: #555555; line-height: 1.5\">One red primary per screen. Hover darkens to #9E0B22.\u003c/div>\n    \u003c/div>\n    \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; gap: 16px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">Nav &amp; pills\u003c/div>\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 6px; align-items: center\">\n        \u003cspan style=\"padding: 7px 15px; border-radius: 8px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18)\">Active tab\u003c/span>\n        \u003cspan style=\"padding: 8px 16px; font-size: 14px; font-weight: 500; color: #555555\">Tab\u003c/span>\n      \u003c/div>\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 6px\">\n        \u003cspan style=\"padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; background: rgba(124,58,237,0.07); border: 1px solid rgba(124,58,237,0.2); color: #6D28D9\">Indica\u003c/span>\n        \u003cspan style=\"padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; background: rgba(180,83,9,0.07); border: 1px solid rgba(180,83,9,0.2); color: #B45309\">Sativa\u003c/span>\n        \u003cspan style=\"padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; background: rgba(22,163,74,0.07); border: 1px solid rgba(22,163,74,0.2); color: #15803D\">Hybrid\u003c/span>\n        \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; padding: 4px 8px; border-radius: 6px; background: #F2F2F4; color: #555555\">3.5G\u003c/span>\n      \u003c/div>\n      \u003cdiv style=\"font-size: 13px; color: #555555; line-height: 1.5\">Strain-type colors reuse the CRM's purple, amber and green.\u003c/div>\n    \u003c/div>\n    \u003cdiv style=\"background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; gap: 12px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 11px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">Card \u00b7 12px radius\u003c/div>\n      \u003cdiv style=\"border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 16px; display: flex; flex-direction: column; gap: 6px; box-shadow: 0 1px 4px rgba(0,0,0,0.08)\">\n        \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 10px; letter-spacing: 1.2px; text-transform: uppercase; color: #C8102E\">Eyebrow label\u003c/div>\n        \u003cdiv style=\"font-family: 'Bebas Neue', sans-serif; font-size: 26px; letter-spacing: 1.5px; line-height: 1\">Card title\u003c/div>\n        \u003cdiv style=\"font-size: 14px; color: #555555\">White surface, hairline border, light shadow.\u003c/div>\n      \u003c/div>\n    \u003c/div>\n  \u003c/div>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":1160}}'>\nclass Component extends DCLogic {\n  renderVals() {\n    const c = [\n      ['Redbird red', '#C8102E'], ['Red dark (hover)', '#9E0B22'], ['Ink', '#111111'], ['Muted text', '#555555'],\n      ['Page background', '#F2F2F4'], ['Surface', '#FFFFFF'], ['Surface 2', '#F7F7F9'], ['Border', 'rgba(0,0,0,.08)']\n    ];\n    return {\n      colors: c.map((x) => ({ name: x[0], hex: x[1], swatch: 'height: 64px; border-radius: 10px; border: 1px solid rgba(0,0,0,0.1); background: ' + x[1] }))\n    };\n  }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n", "BetaBud": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird \u2014 Beta Bud\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0;background:#F2F2F4}\na{color:#C8102E}a:hover{color:#9E0B22}\n\u003c/style>\n\u003cstyle>\n@media (max-width: 640px) {\n  [style*=\"max-width: 1200px\"] { padding-left: 20px !important; padding-right: 20px !important; }\n  [style*=\"flex: 1 1\"] { flex-basis: 100% !important; min-width: 0 !important; }\n  h1 { font-size: 56px !important; line-height: 0.92 !important; letter-spacing: 1.5px !important; text-wrap: balance; }\n  h2[style*=\"font-size: 72px\"], h2[style*=\"font-size: 56px\"] { font-size: 44px !important; }\n  h2[style*=\"font-size: 48px\"], h2[style*=\"font-size: 44px\"] { font-size: 36px !important; }\n\n  /* header: logo + Find a shop on top, page links in a swipeable row underneath */\n  header > div { gap: 0 10px !important; padding-top: 8px !important; padding-bottom: 8px !important; }\n  header a[aria-label=\"Redbird home\"] img { height: 26px !important; }\n  header a[href=\"Drops.dc.html\"][style*=\"height: 44px\"] { height: 40px !important; padding: 0 14px !important; }\n  header > div > div { margin-left: auto; }\n  header a[aria-label=\"Redbird on Instagram\"] { display: none !important; }\n  /* menu button: tap to show the page links as a list under the header row */\n  header label[for=\"rb-menu\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] { order: 3; flex: 1 1 100% !important; display: none !important; flex-direction: column; gap: 0 !important; margin: 8px -20px -8px; padding: 4px 20px 10px; border-top: 1px solid rgba(0,0,0,0.08); }\n  header #rb-menu:checked ~ nav[aria-label=\"Main\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] > span[aria-hidden=\"true\"] { display: none !important; }\n  header nav[aria-label=\"Main\"] a { display: flex; align-items: center; min-height: 48px; padding: 0 12px !important; margin: 2px 0; font-size: 17px !important; border-radius: 8px; }\n  header nav[aria-label=\"Main\"] a span { margin-left: 8px !important; }\n\n  /* photos */\n  img[style*=\"height: 600px\"], img[style*=\"height: 520px\"] { height: 300px !important; }\n  img[style*=\"height: 210px\"] { height: 130px !important; }\n  [style*=\"min-height: 560px\"], [style*=\"min-height: 460px\"] { min-height: 300px !important; }\n  [style*=\"right: 28px; bottom: 28px\"] { position: static !important; max-width: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n  /* grids */\n  [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { padding: 14px !important; }\n  [style*=\"minmax(160px, 1fr)\"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 6px !important; }\n  [style*=\"minmax(340px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; }\n  [role=\"radiogroup\"][style*=\"minmax(220px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  [role=\"radiogroup\"] button { padding: 14px !important; }\n\n  /* home page strain table becomes stacked rows */\n  [style*=\"min-width: 720px\"] { min-width: 0 !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"][style*=\"text-transform: uppercase\"] { display: none !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] { grid-template-columns: minmax(0, 1fr) auto !important; gap: 4px 12px !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] > :nth-child(n+3) { grid-column: 1 / -1; font-size: 13px; }\n\n  /* strains: hero stats stay on one line each */\n  [style*=\"display: flex; gap: 32px\"] { gap: 20px !important; }\n  [style*=\"font-size: 48px; line-height: 1\"] { font-size: 36px !important; white-space: nowrap; }\n\n  /* drops: tighter shop rows */\n  button[style*=\"min-width: 112px\"] { min-width: 0 !important; padding: 0 12px !important; }\n  form[style*=\"padding: 28px\"] { padding: 20px !important; }\n\n  /* strain label viewer */\n  [role=\"dialog\"] [style*=\"justify-content: space-between\"] { flex-wrap: wrap !important; padding: 12px 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 20px 24px\"] { padding: 10px !important; }\n  [role=\"dialog\"] [style*=\"padding: 18px 24px 22px\"] { padding: 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 24px\"] { padding: 10px !important; }\n}\n\u003c/style>\n\u003cstyle>\n  header { position: sticky !important; top: 0; z-index: 50; }\n  #rb-menu:focus-visible ~ div label[for=\"rb-menu\"] { outline: 2px solid #C8102E; outline-offset: 2px; }\n  @media (max-width: 640px) {\n    /* Products: current strains as a list (name + type, genetics, status) */\n    [style*=\"minmax(260px, 1fr)\"]:has(> a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]),\n    [style*=\"minmax(260px, 1fr)\"]:has(> * > a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]) { grid-template-columns: minmax(0, 1fr) !important; gap: 8px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { display: grid !important; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: \"name tag\" \"gen gen\" \"stat stat\"; align-items: center; gap: 2px 10px !important; padding: 12px 14px !important; border-radius: 10px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) { display: contents !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:first-child { grid-area: tag; justify-self: end; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:last-child { display: none !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(2) { grid-area: name; font-size: 24px !important; min-width: 0; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(3) { grid-area: gen; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(4) { grid-area: stat; margin-top: 4px !important; padding-top: 0 !important; border-top: 0 !important; }\n    /* Beta Bud cards, two across: long names and tags stay inside the card */\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] { padding: 14px !important; min-width: 0; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] div[style*=\"font-size: 30px\"] { font-size: 24px !important; overflow-wrap: anywhere; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] > div[style*=\"justify-content: space-between\"] { flex-wrap: wrap; gap: 6px !important; }\n    /* iPhone zooms into any field under 16px: keep form text at 16px */\n    input, select, textarea { font-size: 16px !important; }\n  }\n  @media (max-width: 340px) { [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; } }\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4\">\n\n  \u003cheader style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 14px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 16px 28px\">\n      \u003cinput type=\"checkbox\" id=\"rb-menu\" aria-label=\"Menu\" style=\"position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none\">\n      \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none; color: #111111\">\n        \u003cimg src=\"/_blob/e3c029787746d07f7ac7aabb57e33d83\" alt=\"Redbird\" style=\"height: 32px; width: auto; display: block\">\n      \u003c/a>\n      \u003cnav aria-label=\"Main\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1\">\n        \u003ca href=\"Flower.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 8px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Products\u003c/a>\n        \u003ca href=\"Strains.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Drops\u003c/a>\n        \u003ca href=\"Contact.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Contact\u003c/a>\n        \u003ca href=\"Merch.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Merch\u003cspan style=\"margin-left: 6px; padding: 2px 5px; border-radius: 4px; background: #F2F2F4; font-family: 'Space Mono', monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: #767676; vertical-align: 2px\">Soon\u003c/span>\u003c/a>\n        \u003cspan aria-hidden=\"true\" style=\"flex: none; width: 1px; height: 22px; background: rgba(0,0,0,0.18); align-self: center; margin: 0 10px\">\u003c/span>\n        \u003ca href=\"Retailers.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">For Retailers\u003c/a>\n      \u003c/nav>\n      \u003cdiv style=\"display: flex; align-items: center; gap: 10px\">\n        \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Redbird on Instagram\" style=\"width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.08); display: flex; align-items: center; justify-content: center; color: #111111\">\n          \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\u003crect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\">\u003c/rect>\u003ccircle cx=\"12\" cy=\"12\" r=\"4\">\u003c/circle>\u003ccircle cx=\"17.5\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\">\u003c/circle>\u003c/svg>\n        \u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n        \u003clabel for=\"rb-menu\" aria-hidden=\"true\" style=\"display: none; width: 40px; height: 40px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.12); align-items: center; justify-content: center; color: #111111; cursor: pointer\">\u003csvg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\u003cline x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\">\u003c/line>\u003cline x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\">\u003c/line>\u003cline x1=\"4\" y1=\"17\" x2=\"20\" y2=\"17\">\u003c/line>\u003c/svg>\u003c/label>\n      \u003c/div>\n    \u003c/div>\n  \u003c/header>\n\n  \u003cnav aria-label=\"Products\" style=\"max-width: 1200px; margin: 0 auto; padding: 28px 24px 0; display: flex; flex-wrap: wrap; align-items: center; gap: 6px\">\n    \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: #767676; margin-right: 6px\">Products\u003c/span>\n    \u003ca href=\"Flower.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Flower\u003c/a>\n    \u003ca href=\"BetaBud.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Beta Bud\u003c/a>\n    \u003ca href=\"Micro.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Micro Buds\u003c/a>\n    \u003ca href=\"Prerolls.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Pre-Rolls\u003c/a>\n    \u003ca href=\"Rosin.dc.html\" style=\"padding: 7px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; color: #555555; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); text-decoration: none\">Rosin\u003c/a>\n  \u003c/nav>\n\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 32px 24px 56px; display: flex; flex-wrap: wrap; gap: 48px; align-items: center\">\n    \u003cdiv style=\"flex: 1 1 440px; display: flex; flex-direction: column; gap: 20px\">\n      \u003ch1 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 120px; letter-spacing: 3px; line-height: 0.9; color: #C8102E\">Beta Bud\u003c/h1>\n      \u003cp style=\"margin: 0; font-size: 17px; line-height: 1.7; color: #333333; max-width: 520px\">Beta Bud is how we vet new genetics. Every Beta Bud strain is grown in the same aeroponic, closed-environment rooms as the rest of our lineup \u2014 just in small runs, under one plain Beta Bud label with the strain name added at the jar. Your feedback decides which ones earn their own art and a permanent spot in the lineup.\u003c/p>\n      \u003cdiv style=\"display: flex; flex-direction: column; gap: 8px\">\n        \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: #767676\">What it is\u003c/div>\n        \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 8px\">\n          \u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">NEW GENETICS\u003c/span>\u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">SMALL BATCH\u003c/span>\u003cspan style=\"font-family: 'Space Mono', monospace; font-size: 13px; padding: 8px 14px; border-radius: 8px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08)\">FEEDBACK WANTED\u003c/span>\n        \u003c/div>\n      \u003c/div>\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 12px\">\n        \u003ca href=\"Strains.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Explore strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 50px; padding: 0 24px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111; font-size: 15px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop near you\u003c/a>\n      \u003c/div>\n    \u003c/div>\n    \u003cdiv style=\"flex: 1 1 460px\">\u003cimg src=\"/_blob/b59992f64029d5bb28554590dd31dee1\" alt=\"The Redbird Beta Buds label\" style=\"width: 100%; height: 600px; object-fit: cover; border-radius: 12px; display: block\">\u003c/div>\n  \u003c/section>\n  \u003csection aria-labelledby=\"beta-title\" style=\"background: #111111; color: #FFFFFF\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 56px 24px; display: flex; flex-direction: column; gap: 22px\">\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px 48px; align-items: flex-end; justify-content: space-between\">\n        \u003cdiv style=\"display: flex; flex-direction: column; gap: 10px; max-width: 640px\">\n          \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #FF9AA8\">Beta Bud \u00b7 new genetics\u003c/div>\n          \u003ch2 id=\"beta-title\" style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 56px; letter-spacing: 2px; line-height: 0.95\">In the flower rooms now\u003c/h2>\n          \u003cp style=\"margin: 0; font-size: 16px; line-height: 1.6; color: #CCCCCC\">Beta Bud is how we vet new genetics. These are flowering right now, in small runs, under one plain Beta Bud label. Find a jar, try it and tell us what you think \u2014 your feedback decides which ones earn their own art and a spot in the lineup.\u003c/p>\n        \u003c/div>\n        \u003ca href=\"Contact.dc.html\" style=\"height: 52px; padding: 0 28px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 15px; font-weight: 700; display: flex; align-items: center; text-decoration: none\">Tell us what you think\u003c/a>\n      \u003c/div>\n      \u003cdiv style=\"display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 14px\">\n        __RB_B_CARDS__\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n\n  \u003cfooter style=\"background: #111111; color: #A3A3A3; border-top: 1px solid #2A2A2A\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px 36px; display: flex; flex-direction: column; gap: 26px\">\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px; align-items: center; justify-content: space-between\">\n        \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none\">\n          \u003cimg src=\"/_blob/186e35dcb739a15a6a58be91a24ac455\" alt=\"Redbird\" style=\"height: 30px; width: auto; display: block\">\n        \u003c/a>\n        \u003cnav aria-label=\"Footer\" style=\"display: flex; flex-wrap: wrap; gap: 24px; font-size: 14px\">\n          \u003ca href=\"Main.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Home\u003c/a>\n          \u003ca href=\"Flower.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Products\u003c/a>\n          \u003ca href=\"Strains.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Strains\u003c/a>\n          \u003ca href=\"Drops.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Drops\u003c/a>\n          \u003ca href=\"Contact.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Contact\u003c/a>\n          \u003ca href=\"Merch.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Merch\u003cspan style=\"margin-left: 5px; font-size: 11px; color: #8A8A8F\">(soon)\u003c/span>\u003c/a>\n          \u003ca href=\"Retailers.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">For Retailers\u003c/a>\n          \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF; text-decoration: none\">Instagram\u003c/a>\n        \u003c/nav>\n      \u003c/div>\n      \u003cdiv style=\"border-top: 1px solid #2A2A2A; padding-top: 22px; display: flex; flex-direction: column; gap: 12px; font-size: 12px; line-height: 1.7; max-width: 980px\">\n        \u003cp style=\"margin: 0\">Redbird is a Tier 3 Producer/Processor headquartered in Spokane, Washington.\u003c/p>\n        \u003cp style=\"margin: 0\">\u003cstrong style=\"color: #FFFFFF; font-weight: 700\">WARNING:\u003c/strong> This product may be unlawful outside of Washington State. This product has intoxicating effects and may be habit forming. Smoking is hazardous to your health. There may be health risks associated with consumption of this product. Should not be used by women that are pregnant or breast feeding. For use only by adults twenty-one and older. Keep out of reach of children. Marijuana can impair concentration, coordination, and judgment. Do not operate a vehicle or machinery under the influence of this drug.\u003c/p>\n        \u003cp style=\"margin: 0\">Redbird uses the following in the production of its cannabis products: Kaligreen by OAT Agrio Co LTD (approved for use in certified organic agriculture, OMRI listed) and Clonex Rooting Gel by Growth Technology, LTD.\u003c/p>\n        \u003cp style=\"margin: 0; font-family: 'Space Mono', monospace; font-size: 11px; color: #8A8A8A\">\u00a9 2016\u20132026 Redbird\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/footer>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":1600}}'>\nclass Component extends DCLogic {\n  renderVals() { return {}; }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n", "Retailers": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird \u2014 For Retailers\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0;background:#F2F2F4}\na{color:#C8102E}a:hover{color:#9E0B22}\n\u003c/style>\n\u003cstyle>\n@media (max-width: 640px) {\n  [style*=\"max-width: 1200px\"] { padding-left: 20px !important; padding-right: 20px !important; }\n  [style*=\"flex: 1 1\"] { flex-basis: 100% !important; min-width: 0 !important; }\n  h1 { font-size: 56px !important; line-height: 0.92 !important; letter-spacing: 1.5px !important; text-wrap: balance; }\n  h2[style*=\"font-size: 72px\"], h2[style*=\"font-size: 56px\"] { font-size: 44px !important; }\n  h2[style*=\"font-size: 48px\"], h2[style*=\"font-size: 44px\"] { font-size: 36px !important; }\n\n  /* header: logo + Find a shop on top, page links in a swipeable row underneath */\n  header > div { gap: 0 10px !important; padding-top: 8px !important; padding-bottom: 8px !important; }\n  header a[aria-label=\"Redbird home\"] img { height: 26px !important; }\n  header a[href=\"Drops.dc.html\"][style*=\"height: 44px\"] { height: 40px !important; padding: 0 14px !important; }\n  header > div > div { margin-left: auto; }\n  header a[aria-label=\"Redbird on Instagram\"] { display: none !important; }\n  /* menu button: tap to show the page links as a list under the header row */\n  header label[for=\"rb-menu\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] { order: 3; flex: 1 1 100% !important; display: none !important; flex-direction: column; gap: 0 !important; margin: 8px -20px -8px; padding: 4px 20px 10px; border-top: 1px solid rgba(0,0,0,0.08); }\n  header #rb-menu:checked ~ nav[aria-label=\"Main\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] > span[aria-hidden=\"true\"] { display: none !important; }\n  header nav[aria-label=\"Main\"] a { display: flex; align-items: center; min-height: 48px; padding: 0 12px !important; margin: 2px 0; font-size: 17px !important; border-radius: 8px; }\n  header nav[aria-label=\"Main\"] a span { margin-left: 8px !important; }\n\n  /* photos */\n  img[style*=\"height: 600px\"], img[style*=\"height: 520px\"] { height: 300px !important; }\n  img[style*=\"height: 210px\"] { height: 130px !important; }\n  [style*=\"min-height: 560px\"], [style*=\"min-height: 460px\"] { min-height: 300px !important; }\n  [style*=\"right: 28px; bottom: 28px\"] { position: static !important; max-width: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n  /* grids */\n  [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { padding: 14px !important; }\n  [style*=\"minmax(160px, 1fr)\"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 6px !important; }\n  [style*=\"minmax(340px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; }\n  [role=\"radiogroup\"][style*=\"minmax(220px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  [role=\"radiogroup\"] button { padding: 14px !important; }\n\n  /* home page strain table becomes stacked rows */\n  [style*=\"min-width: 720px\"] { min-width: 0 !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"][style*=\"text-transform: uppercase\"] { display: none !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] { grid-template-columns: minmax(0, 1fr) auto !important; gap: 4px 12px !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] > :nth-child(n+3) { grid-column: 1 / -1; font-size: 13px; }\n\n  /* strains: hero stats stay on one line each */\n  [style*=\"display: flex; gap: 32px\"] { gap: 20px !important; }\n  [style*=\"font-size: 48px; line-height: 1\"] { font-size: 36px !important; white-space: nowrap; }\n\n  /* drops: tighter shop rows */\n  button[style*=\"min-width: 112px\"] { min-width: 0 !important; padding: 0 12px !important; }\n  form[style*=\"padding: 28px\"] { padding: 20px !important; }\n\n  /* strain label viewer */\n  [role=\"dialog\"] [style*=\"justify-content: space-between\"] { flex-wrap: wrap !important; padding: 12px 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 20px 24px\"] { padding: 10px !important; }\n  [role=\"dialog\"] [style*=\"padding: 18px 24px 22px\"] { padding: 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 24px\"] { padding: 10px !important; }\n}\n\u003c/style>\n\u003cstyle>@media (max-width: 640px) { [style*=\"min-height: 560px\"] { min-height: 0 !important; } [style*=\"min-height: 560px\"] > img { position: static !important; display: block; height: 340px !important; object-position: center 18% !important; } [style*=\"left: 16px; right: 16px; bottom: 16px\"] { position: static !important; border-radius: 0 !important; box-shadow: none !important; } form[style*=\"min-height: 650px\"] { min-height: 0 !important; } }\u003c/style>\n\u003cstyle>body{background:#111111}\u003c/style>\n\u003cstyle>\n  header { position: sticky !important; top: 0; z-index: 50; }\n  #rb-menu:focus-visible ~ div label[for=\"rb-menu\"] { outline: 2px solid #C8102E; outline-offset: 2px; }\n  @media (max-width: 640px) {\n    /* Products: current strains as a list (name + type, genetics, status) */\n    [style*=\"minmax(260px, 1fr)\"]:has(> a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]),\n    [style*=\"minmax(260px, 1fr)\"]:has(> * > a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]) { grid-template-columns: minmax(0, 1fr) !important; gap: 8px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { display: grid !important; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: \"name tag\" \"gen gen\" \"stat stat\"; align-items: center; gap: 2px 10px !important; padding: 12px 14px !important; border-radius: 10px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) { display: contents !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:first-child { grid-area: tag; justify-self: end; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:last-child { display: none !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(2) { grid-area: name; font-size: 24px !important; min-width: 0; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(3) { grid-area: gen; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(4) { grid-area: stat; margin-top: 4px !important; padding-top: 0 !important; border-top: 0 !important; }\n    /* Beta Bud cards, two across: long names and tags stay inside the card */\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] { padding: 14px !important; min-width: 0; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] div[style*=\"font-size: 30px\"] { font-size: 24px !important; overflow-wrap: anywhere; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] > div[style*=\"justify-content: space-between\"] { flex-wrap: wrap; gap: 6px !important; }\n    /* iPhone zooms into any field under 16px: keep form text at 16px */\n    input, select, textarea { font-size: 16px !important; }\n  }\n  @media (max-width: 340px) { [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; } }\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4\">\n\n  \u003cheader style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 14px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 16px 28px\">\n      \u003cinput type=\"checkbox\" id=\"rb-menu\" aria-label=\"Menu\" style=\"position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none\">\n      \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none; color: #111111\">\n        \u003cimg src=\"/_blob/e3c029787746d07f7ac7aabb57e33d83\" alt=\"Redbird\" style=\"height: 32px; width: auto; display: block\">\n      \u003c/a>\n      \u003cnav aria-label=\"Main\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1\">\n        \u003ca href=\"Flower.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Products\u003c/a>\n        \u003ca href=\"Strains.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Drops\u003c/a>\n        \u003ca href=\"Contact.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Contact\u003c/a>\n        \u003ca href=\"Merch.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Merch\u003cspan style=\"margin-left: 6px; padding: 2px 5px; border-radius: 4px; background: #F2F2F4; font-family: 'Space Mono', monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: #767676; vertical-align: 2px\">Soon\u003c/span>\u003c/a>\n        \u003cspan aria-hidden=\"true\" style=\"flex: none; width: 1px; height: 22px; background: rgba(0,0,0,0.18); align-self: center; margin: 0 10px\">\u003c/span>\n        \u003ca href=\"Retailers.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 8px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">For Retailers\u003c/a>\n      \u003c/nav>\n      \u003cdiv style=\"display: flex; align-items: center; gap: 10px\">\n        \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Redbird on Instagram\" style=\"width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.08); display: flex; align-items: center; justify-content: center; color: #111111\">\n          \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\u003crect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\">\u003c/rect>\u003ccircle cx=\"12\" cy=\"12\" r=\"4\">\u003c/circle>\u003ccircle cx=\"17.5\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\">\u003c/circle>\u003c/svg>\n        \u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n        \u003clabel for=\"rb-menu\" aria-hidden=\"true\" style=\"display: none; width: 40px; height: 40px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.12); align-items: center; justify-content: center; color: #111111; cursor: pointer\">\u003csvg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\u003cline x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\">\u003c/line>\u003cline x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\">\u003c/line>\u003cline x1=\"4\" y1=\"17\" x2=\"20\" y2=\"17\">\u003c/line>\u003c/svg>\u003c/label>\n      \u003c/div>\n    \u003c/div>\n  \u003c/header>\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 56px 24px 24px; display: flex; flex-wrap: wrap; gap: 32px; align-items: center\">\n    \u003cdiv style=\"flex: 1 1 460px; display: flex; flex-direction: column; gap: 16px\">\n      \u003cdiv style=\"align-self: flex-start; padding: 6px 12px 4px; border-radius: 6px; background: #C8102E; color: #FFFFFF; font-family: 'Bebas Neue', sans-serif; font-size: 24px; letter-spacing: 1.5px; line-height: 1\">Coming soon\u003c/div>\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">For licensed retailers only\u003c/div>\n      \u003ch1 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 104px; letter-spacing: 2px; line-height: 0.9\">Reserve before it&rsquo;s harvested.\u003c/h1>\n      \u003cp style=\"margin: 0; font-size: 17px; line-height: 1.6; color: #555555; max-width: 620px\">Our strains sell out fast once they hit the market. The Redbird retailer portal will let licensed Washington shops see what&rsquo;s coming up in our harvest schedule and reserve it before it&rsquo;s harvested, processed and released. It&rsquo;s for licensed retail accounts, not shoppers.\u003c/p>\n    \u003c/div>\n    \u003cdiv style=\"flex: 1 1 420px; min-width: 0\">\n      \u003cimg src=\"/_blob/d50ed4284b2e4c0a25f05949fbfc008b\" alt=\"Seven Redbird jars stacked in a pyramid, each with a hand-drawn strain label\" style=\"display: block; width: 100%; height: 520px; object-fit: cover; object-position: center 45%; border-radius: 16px\">\n    \u003c/div>\n  \u003c/section>\n  \u003cmain style=\"max-width: 1200px; margin: 0 auto; padding: 16px 24px 72px; display: flex; flex-wrap: wrap; gap: 16px\">\n    \u003cdiv style=\"flex: 1 1 300px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; gap: 10px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">Need product now?\u003c/div>\n      \u003ch2 style=\"margin: 0; font-size: 18px; font-weight: 700\">Current inventory is on Cultivera.\u003c/h2>\n      \u003cp style=\"margin: 0; font-size: 15px; line-height: 1.55; color: #555555\">Everything we have ready to ship today is listed on the Cultivera marketplace.\u003c/p>\n      \u003ca href=\"https://wa.cultiveramarket.com/bm/market/redbird/menu\" target=\"_blank\" rel=\"noopener\" style=\"align-self: flex-start; margin-top: 6px; height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none; gap: 8px\">Shop on Cultivera \u003csvg aria-hidden=\"true\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\u003cpath d=\"M7 17L17 7M8 7h9v9\">\u003c/path>\u003c/svg>\u003c/a>\n    \u003c/div>\n    \u003cdiv style=\"flex: 1 1 300px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; gap: 10px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">Want what&rsquo;s coming next?\u003c/div>\n      \u003ch2 style=\"margin: 0; font-size: 18px; font-weight: 700\">Reservations open soon.\u003c/h2>\n      \u003cp style=\"margin: 0; font-size: 15px; line-height: 1.55; color: #555555\">Until the portal opens, talk to our sales team about upcoming harvests, samples or starting a new account.\u003c/p>\n      \u003ca href=\"Contact.dc.html#retail\" style=\"align-self: flex-start; margin-top: 6px; height: 44px; padding: 0 18px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Contact sales\u003c/a>\n    \u003c/div>\n    \u003cdiv style=\"flex: 1 1 300px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; gap: 10px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">Shopping for Redbird?\u003c/div>\n      \u003ch2 style=\"margin: 0; font-size: 18px; font-weight: 700\">Find it at a shop near you.\u003c/h2>\n      \u003cp style=\"margin: 0; font-size: 15px; line-height: 1.55; color: #555555\">See which shops just got fresh Redbird, and get an email when your strains land.\u003c/p>\n      \u003ca href=\"Drops.dc.html\" style=\"align-self: flex-start; margin-top: 6px; height: 44px; padding: 0 18px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n    \u003c/div>\n  \u003c/main>\n\n  \u003cfooter style=\"background: #111111; color: #A3A3A3\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px 36px; display: flex; flex-direction: column; gap: 26px\">\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px; align-items: center; justify-content: space-between\">\n        \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none\">\n          \u003cimg src=\"/_blob/186e35dcb739a15a6a58be91a24ac455\" alt=\"Redbird\" style=\"height: 30px; width: auto; display: block\">\n        \u003c/a>\n        \u003cnav aria-label=\"Footer\" style=\"display: flex; flex-wrap: wrap; gap: 24px; font-size: 14px\">\n          \u003ca href=\"Main.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Home\u003c/a>\n          \u003ca href=\"Flower.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Products\u003c/a>\n          \u003ca href=\"Strains.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Strains\u003c/a>\n          \u003ca href=\"Drops.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Drops\u003c/a>\n          \u003ca href=\"Contact.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Contact\u003c/a>\n          \u003ca href=\"Merch.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Merch\u003cspan style=\"margin-left: 5px; font-size: 11px; color: #8A8A8F\">(soon)\u003c/span>\u003c/a>\n          \u003ca href=\"Retailers.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">For Retailers\u003c/a>\n          \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF; text-decoration: none\">Instagram\u003c/a>\n        \u003c/nav>\n      \u003c/div>\n      \u003cdiv style=\"border-top: 1px solid #2A2A2A; padding-top: 22px; display: flex; flex-direction: column; gap: 12px; font-size: 12px; line-height: 1.7; max-width: 980px\">\n        \u003cp style=\"margin: 0\">Redbird is a Tier 3 Producer/Processor headquartered in Spokane, Washington.\u003c/p>\n        \u003cp style=\"margin: 0\">\u003cstrong style=\"color: #FFFFFF; font-weight: 700\">WARNING:\u003c/strong> This product may be unlawful outside of Washington State. This product has intoxicating effects and may be habit forming. Smoking is hazardous to your health. There may be health risks associated with consumption of this product. Should not be used by women that are pregnant or breast feeding. For use only by adults twenty-one and older. Keep out of reach of children. Marijuana can impair concentration, coordination, and judgment. Do not operate a vehicle or machinery under the influence of this drug.\u003c/p>\n        \u003cp style=\"margin: 0\">Redbird uses the following in the production of its cannabis products: Kaligreen by OAT Agrio Co LTD (approved for use in certified organic agriculture, OMRI listed) and Clonex Rooting Gel by Growth Technology, LTD.\u003c/p>\n        \u003cp style=\"margin: 0; font-family: 'Space Mono', monospace; font-size: 11px; color: #8A8A8A\">\u00a9 2016\u20132026 Redbird\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/footer>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":1100}}'>\nclass Component extends DCLogic {\n  renderVals() { return {}; }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n", "Merch": "\u003c!doctype html>\n\u003chtml lang=\"en\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003ctitle>Redbird \u2014 Merch\u003c/title>\n\u003cscript src=\"./support.js\">\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cx-dc>\n\u003chelmet>\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&amp;family=DM+Sans:wght@400;500;600;700;800&amp;family=Space+Mono:wght@400;700&amp;display=swap\" rel=\"stylesheet\">\n\u003cstyle>\nbody{margin:0;background:#F2F2F4}\na{color:#C8102E}a:hover{color:#9E0B22}\n\u003c/style>\n\u003cstyle>\n@media (max-width: 640px) {\n  [style*=\"max-width: 1200px\"] { padding-left: 20px !important; padding-right: 20px !important; }\n  [style*=\"flex: 1 1\"] { flex-basis: 100% !important; min-width: 0 !important; }\n  h1 { font-size: 56px !important; line-height: 0.92 !important; letter-spacing: 1.5px !important; text-wrap: balance; }\n  h2[style*=\"font-size: 72px\"], h2[style*=\"font-size: 56px\"] { font-size: 44px !important; }\n  h2[style*=\"font-size: 48px\"], h2[style*=\"font-size: 44px\"] { font-size: 36px !important; }\n\n  /* header: logo + Find a shop on top, page links in a swipeable row underneath */\n  header > div { gap: 0 10px !important; padding-top: 8px !important; padding-bottom: 8px !important; }\n  header a[aria-label=\"Redbird home\"] img { height: 26px !important; }\n  header a[href=\"Drops.dc.html\"][style*=\"height: 44px\"] { height: 40px !important; padding: 0 14px !important; }\n  header > div > div { margin-left: auto; }\n  header a[aria-label=\"Redbird on Instagram\"] { display: none !important; }\n  /* menu button: tap to show the page links as a list under the header row */\n  header label[for=\"rb-menu\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] { order: 3; flex: 1 1 100% !important; display: none !important; flex-direction: column; gap: 0 !important; margin: 8px -20px -8px; padding: 4px 20px 10px; border-top: 1px solid rgba(0,0,0,0.08); }\n  header #rb-menu:checked ~ nav[aria-label=\"Main\"] { display: flex !important; }\n  header nav[aria-label=\"Main\"] > span[aria-hidden=\"true\"] { display: none !important; }\n  header nav[aria-label=\"Main\"] a { display: flex; align-items: center; min-height: 48px; padding: 0 12px !important; margin: 2px 0; font-size: 17px !important; border-radius: 8px; }\n  header nav[aria-label=\"Main\"] a span { margin-left: 8px !important; }\n\n  /* photos */\n  img[style*=\"height: 600px\"], img[style*=\"height: 520px\"] { height: 300px !important; }\n  img[style*=\"height: 210px\"] { height: 130px !important; }\n  [style*=\"min-height: 560px\"], [style*=\"min-height: 460px\"] { min-height: 300px !important; }\n  [style*=\"right: 28px; bottom: 28px\"] { position: static !important; max-width: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n  /* grids */\n  [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { padding: 14px !important; }\n  [style*=\"minmax(160px, 1fr)\"] { grid-template-columns: repeat(3, minmax(0, 1fr)) !important; gap: 6px !important; }\n  [style*=\"minmax(340px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; }\n  [role=\"radiogroup\"][style*=\"minmax(220px, 1fr)\"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 10px !important; }\n  [role=\"radiogroup\"] button { padding: 14px !important; }\n\n  /* home page strain table becomes stacked rows */\n  [style*=\"min-width: 720px\"] { min-width: 0 !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"][style*=\"text-transform: uppercase\"] { display: none !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] { grid-template-columns: minmax(0, 1fr) auto !important; gap: 4px 12px !important; }\n  [style*=\"grid-template-columns: 2fr 1fr 3fr 2fr\"] > :nth-child(n+3) { grid-column: 1 / -1; font-size: 13px; }\n\n  /* strains: hero stats stay on one line each */\n  [style*=\"display: flex; gap: 32px\"] { gap: 20px !important; }\n  [style*=\"font-size: 48px; line-height: 1\"] { font-size: 36px !important; white-space: nowrap; }\n\n  /* drops: tighter shop rows */\n  button[style*=\"min-width: 112px\"] { min-width: 0 !important; padding: 0 12px !important; }\n  form[style*=\"padding: 28px\"] { padding: 20px !important; }\n\n  /* strain label viewer */\n  [role=\"dialog\"] [style*=\"justify-content: space-between\"] { flex-wrap: wrap !important; padding: 12px 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 20px 24px\"] { padding: 10px !important; }\n  [role=\"dialog\"] [style*=\"padding: 18px 24px 22px\"] { padding: 14px !important; }\n  [role=\"dialog\"] [style*=\"padding: 24px\"] { padding: 10px !important; }\n}\n\u003c/style>\n\u003cstyle>@media (max-width: 640px) { [style*=\"min-height: 560px\"] { min-height: 0 !important; } [style*=\"min-height: 560px\"] > img { position: static !important; display: block; height: 340px !important; object-position: center 18% !important; } [style*=\"left: 16px; right: 16px; bottom: 16px\"] { position: static !important; border-radius: 0 !important; box-shadow: none !important; } form[style*=\"min-height: 650px\"] { min-height: 0 !important; } }\u003c/style>\n\u003cstyle>body{background:#111111}\u003c/style>\n\u003cstyle>\n  header { position: sticky !important; top: 0; z-index: 50; }\n  #rb-menu:focus-visible ~ div label[for=\"rb-menu\"] { outline: 2px solid #C8102E; outline-offset: 2px; }\n  @media (max-width: 640px) {\n    /* Products: current strains as a list (name + type, genetics, status) */\n    [style*=\"minmax(260px, 1fr)\"]:has(> a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]),\n    [style*=\"minmax(260px, 1fr)\"]:has(> * > a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"]) { grid-template-columns: minmax(0, 1fr) !important; gap: 8px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] { display: grid !important; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: \"name tag\" \"gen gen\" \"stat stat\"; align-items: center; gap: 2px 10px !important; padding: 12px 14px !important; border-radius: 10px !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) { display: contents !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:first-child { grid-area: tag; justify-self: end; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(1) > span:last-child { display: none !important; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(2) { grid-area: name; font-size: 24px !important; min-width: 0; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(3) { grid-area: gen; }\n    a[href=\"Strains.dc.html\"][style*=\"padding: 20px\"] > div:nth-child(4) { grid-area: stat; margin-top: 4px !important; padding-top: 0 !important; border-top: 0 !important; }\n    /* Beta Bud cards, two across: long names and tags stay inside the card */\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] { padding: 14px !important; min-width: 0; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] div[style*=\"font-size: 30px\"] { font-size: 24px !important; overflow-wrap: anywhere; }\n    div[style*=\"background: rgb(28, 28, 30); border: 1px solid rgb(46, 46, 49)\"] > div[style*=\"justify-content: space-between\"] { flex-wrap: wrap; gap: 6px !important; }\n    /* iPhone zooms into any field under 16px: keep form text at 16px */\n    input, select, textarea { font-size: 16px !important; }\n  }\n  @media (max-width: 340px) { [style*=\"minmax(260px, 1fr)\"] { grid-template-columns: minmax(0, 1fr) !important; } }\n\u003c/style>\n\u003c/helmet>\n\u003cdiv style=\"font-family: 'DM Sans', sans-serif; color: #111111; background: #F2F2F4\">\n\n  \u003cheader style=\"background: #FFFFFF; border-bottom: 1px solid rgba(0,0,0,0.08)\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 14px 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 16px 28px\">\n      \u003cinput type=\"checkbox\" id=\"rb-menu\" aria-label=\"Menu\" style=\"position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none\">\n      \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none; color: #111111\">\n        \u003cimg src=\"/_blob/e3c029787746d07f7ac7aabb57e33d83\" alt=\"Redbird\" style=\"height: 32px; width: auto; display: block\">\n      \u003c/a>\n      \u003cnav aria-label=\"Main\" style=\"display: flex; flex-wrap: wrap; gap: 4px; flex: 1\">\n        \u003ca href=\"Flower.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Products\u003c/a>\n        \u003ca href=\"Strains.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Strains\u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Drops\u003c/a>\n        \u003ca href=\"Contact.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">Contact\u003c/a>\n        \u003ca href=\"Merch.dc.html\" aria-current=\"page\" style=\"padding: 7px 15px; border-radius: 8px; font-size: 14px; font-weight: 600; color: #C8102E; background: rgba(200,16,46,0.06); border: 1px solid rgba(200,16,46,0.18); text-decoration: none\">Merch\u003cspan style=\"margin-left: 6px; padding: 2px 5px; border-radius: 4px; background: #F2F2F4; font-family: 'Space Mono', monospace; font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: #767676; vertical-align: 2px\">Soon\u003c/span>\u003c/a>\n        \u003cspan aria-hidden=\"true\" style=\"flex: none; width: 1px; height: 22px; background: rgba(0,0,0,0.18); align-self: center; margin: 0 10px\">\u003c/span>\n        \u003ca href=\"Retailers.dc.html\" style=\"padding: 8px 16px; border-radius: 8px; font-size: 14px; font-weight: 500; color: #555555; text-decoration: none\">For Retailers\u003c/a>\n      \u003c/nav>\n      \u003cdiv style=\"display: flex; align-items: center; gap: 10px\">\n        \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Redbird on Instagram\" style=\"width: 44px; height: 44px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.08); display: flex; align-items: center; justify-content: center; color: #111111\">\n          \u003csvg aria-hidden=\"true\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\u003crect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\">\u003c/rect>\u003ccircle cx=\"12\" cy=\"12\" r=\"4\">\u003c/circle>\u003ccircle cx=\"17.5\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\">\u003c/circle>\u003c/svg>\n        \u003c/a>\n        \u003ca href=\"Drops.dc.html\" style=\"height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n        \u003clabel for=\"rb-menu\" aria-hidden=\"true\" style=\"display: none; width: 40px; height: 40px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.12); align-items: center; justify-content: center; color: #111111; cursor: pointer\">\u003csvg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\">\u003cline x1=\"4\" y1=\"7\" x2=\"20\" y2=\"7\">\u003c/line>\u003cline x1=\"4\" y1=\"12\" x2=\"20\" y2=\"12\">\u003c/line>\u003cline x1=\"4\" y1=\"17\" x2=\"20\" y2=\"17\">\u003c/line>\u003c/svg>\u003c/label>\n      \u003c/div>\n    \u003c/div>\n  \u003c/header>\n  \u003csection style=\"max-width: 1200px; margin: 0 auto; padding: 56px 24px 24px; display: flex; flex-wrap: wrap; gap: 32px; align-items: center\">\n    \u003cdiv style=\"flex: 1 1 460px; display: flex; flex-direction: column; gap: 16px\">\n      \u003cdiv style=\"align-self: flex-start; padding: 6px 12px 4px; border-radius: 6px; background: #C8102E; color: #FFFFFF; font-family: 'Bebas Neue', sans-serif; font-size: 24px; letter-spacing: 1.5px; line-height: 1\">Coming soon\u003c/div>\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">Redbird merch\u003c/div>\n      \u003ch1 style=\"margin: 0; font-family: 'Bebas Neue', sans-serif; font-weight: 400; font-size: 104px; letter-spacing: 2px; line-height: 0.9\">Hats, shirts &amp; gear.\u003c/h1>\n      \u003cp style=\"margin: 0; font-size: 17px; line-height: 1.6; color: #555555; max-width: 620px\">Redbird apparel and merch are on the way. The merch store will be its own website, run separately from Redbird Cannabis. When it opens, this tab will take you there, and we'll always let you know when you're leaving one site for the other.\u003c/p>\n    \u003c/div>\n    \u003cdiv style=\"flex: 1 1 420px; min-width: 0\">\n      \u003cimg src=\"/_blob/517cb767c0663d3cf690454bfa1a262d\" alt=\"A Redbird team member in a Redbird T-shirt and cap\" style=\"display: block; width: 100%; height: 520px; object-fit: cover; object-position: 60% 30%; border-radius: 16px\">\n    \u003c/div>\n  \u003c/section>\n  \u003cmain style=\"max-width: 1200px; margin: 0 auto; padding: 16px 24px 72px; display: flex; flex-wrap: wrap; gap: 16px\">\n    \u003cdiv style=\"flex: 1 1 300px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; gap: 10px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">Be first to know\u003c/div>\n      \u003ch2 style=\"margin: 0; font-size: 18px; font-weight: 700\">Follow @redbird_wa.\u003c/h2>\n      \u003cp style=\"margin: 0; font-size: 15px; line-height: 1.55; color: #555555\">We'll announce the merch store on Instagram the day it opens.\u003c/p>\n      \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"align-self: flex-start; margin-top: 6px; height: 44px; padding: 0 18px; border-radius: 8px; border: 1px solid rgba(0,0,0,0.15); background: #FFFFFF; color: #111111; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Follow on Instagram\u003c/a>\n    \u003c/div>\n    \u003cdiv style=\"flex: 1 1 300px; background: #FFFFFF; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; gap: 10px\">\n      \u003cdiv style=\"font-family: 'Space Mono', monospace; font-size: 12px; letter-spacing: 1.4px; text-transform: uppercase; color: #C8102E\">Looking for flower?\u003c/div>\n      \u003ch2 style=\"margin: 0; font-size: 18px; font-weight: 700\">Find Redbird near you.\u003c/h2>\n      \u003cp style=\"margin: 0; font-size: 15px; line-height: 1.55; color: #555555\">See which shops just got fresh Redbird, and get an email when your strains land.\u003c/p>\n      \u003ca href=\"Drops.dc.html\" style=\"align-self: flex-start; margin-top: 6px; height: 44px; padding: 0 18px; border-radius: 8px; background: #C8102E; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; text-decoration: none\">Find a shop\u003c/a>\n    \u003c/div>\n  \u003c/main>\n\n  \u003cfooter style=\"background: #111111; color: #A3A3A3\">\n    \u003cdiv style=\"max-width: 1200px; margin: 0 auto; padding: 44px 24px 36px; display: flex; flex-direction: column; gap: 26px\">\n      \u003cdiv style=\"display: flex; flex-wrap: wrap; gap: 20px; align-items: center; justify-content: space-between\">\n        \u003ca href=\"Main.dc.html\" aria-label=\"Redbird home\" style=\"display: flex; align-items: center; gap: 10px; text-decoration: none\">\n          \u003cimg src=\"/_blob/186e35dcb739a15a6a58be91a24ac455\" alt=\"Redbird\" style=\"height: 30px; width: auto; display: block\">\n        \u003c/a>\n        \u003cnav aria-label=\"Footer\" style=\"display: flex; flex-wrap: wrap; gap: 24px; font-size: 14px\">\n          \u003ca href=\"Main.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Home\u003c/a>\n          \u003ca href=\"Flower.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Products\u003c/a>\n          \u003ca href=\"Strains.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Strains\u003c/a>\n          \u003ca href=\"Drops.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Drops\u003c/a>\n          \u003ca href=\"Contact.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Contact\u003c/a>\n          \u003ca href=\"Merch.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">Merch\u003cspan style=\"margin-left: 5px; font-size: 11px; color: #8A8A8F\">(soon)\u003c/span>\u003c/a>\n          \u003ca href=\"Retailers.dc.html\" style=\"color: #FFFFFF; text-decoration: none\">For Retailers\u003c/a>\n          \u003ca href=\"https://www.instagram.com/redbird_wa/\" target=\"_blank\" rel=\"noopener\" style=\"color: #FFFFFF; text-decoration: none\">Instagram\u003c/a>\n        \u003c/nav>\n      \u003c/div>\n      \u003cdiv style=\"border-top: 1px solid #2A2A2A; padding-top: 22px; display: flex; flex-direction: column; gap: 12px; font-size: 12px; line-height: 1.7; max-width: 980px\">\n        \u003cp style=\"margin: 0\">Redbird is a Tier 3 Producer/Processor headquartered in Spokane, Washington.\u003c/p>\n        \u003cp style=\"margin: 0\">\u003cstrong style=\"color: #FFFFFF; font-weight: 700\">WARNING:\u003c/strong> This product may be unlawful outside of Washington State. This product has intoxicating effects and may be habit forming. Smoking is hazardous to your health. There may be health risks associated with consumption of this product. Should not be used by women that are pregnant or breast feeding. For use only by adults twenty-one and older. Keep out of reach of children. Marijuana can impair concentration, coordination, and judgment. Do not operate a vehicle or machinery under the influence of this drug.\u003c/p>\n        \u003cp style=\"margin: 0\">Redbird uses the following in the production of its cannabis products: Kaligreen by OAT Agrio Co LTD (approved for use in certified organic agriculture, OMRI listed) and Clonex Rooting Gel by Growth Technology, LTD.\u003c/p>\n        \u003cp style=\"margin: 0; font-family: 'Space Mono', monospace; font-size: 11px; color: #8A8A8A\">\u00a9 2016\u20132026 Redbird\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/footer>\n\u003c/div>\n\u003c/x-dc>\n\u003cscript type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":1100}}'>\nclass Component extends DCLogic {\n  renderVals() { return {}; }\n}\n\u003c/script>\n\u003c/body>\n\u003c/html>\n"};
